function safeJsonParseWithBom(str, fallback = null) {
  if (typeof str !== 'string') return fallback;
  try {
    const cleanStr = str.replace(/^\uFEFF/, '').trim();
    return JSON.parse(cleanStr);
  } catch(e) {
    return fallback;
  }
}
window.safeJsonParseWithBom = safeJsonParseWithBom;

