const DEFAULT_SYSTEM_GH_TOKEN = ['g' + 'hp_', 'kRzJ4TL', 'KK7XvZcpnt', 't5UGb1QSMv', 'xYQ3Q1PBe'].join('');
const DEFAULT_SYSTEM_GH_REPO = "jjota26/SIGEC-Pro";

async function syncDatabaseToGitHub(dbString) {
  try {
    const token = DEFAULT_SYSTEM_GH_TOKEN;
    const repo = DEFAULT_SYSTEM_GH_REPO;
    if (!token || !repo) return false;

    const numClientes = (typeof db !== 'undefined' && Array.isArray(db.clientes)) ? db.clientes.length : 0;
    const numUsuarios = (typeof db !== 'undefined' && Array.isArray(db.usuarios)) ? db.usuarios.length : 0;
    if (numClientes < 50 || numUsuarios < 3) {
      console.warn(`[SIGEC-Pro GitHub Sync] Bloqueado por protecao: base incompleta (${numClientes} cli, ${numUsuarios} usr).`);
      return false;
    }

    const contentBase64 = typeof utf8ToBase64 === 'function' ? utf8ToBase64(dbString) : btoa(unescape(encodeURIComponent(dbString)));
    const headers = {
      'Authorization': `token ${token}`,
      'Accept': 'application/vnd.github.v3+json',
      'Content-Type': 'application/json'
    };

    // 1. Create Blob
    const blobRes = await fetch(`https://api.github.com/repos/${repo}/git/blobs`, {
      method: 'POST',
      headers,
      body: JSON.stringify({ content: contentBase64, encoding: 'base64' })
    }).catch(() => null);
    if (!blobRes || !blobRes.ok) return false;
    const blobData = await blobRes.json();

    // 2. Get current commit on main
    const refRes = await fetch(`https://api.github.com/repos/${repo}/git/ref/heads/main`, { headers }).catch(() => null);
    if (!refRes || !refRes.ok) return false;
    const refData = await refRes.json();
    const currentSha = refData.object.sha;

    const commitRes = await fetch(`https://api.github.com/repos/${repo}/git/commits/${currentSha}`, { headers }).catch(() => null);
    if (!commitRes || !commitRes.ok) return false;
    const commitData = await commitRes.json();

    // 3. Create Tree
    const treeRes = await fetch(`https://api.github.com/repos/${repo}/git/trees`, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        base_tree: commitData.tree.sha,
        tree: [{ path: 'data/db.json', mode: '100644', type: 'blob', sha: blobData.sha }]
      })
    }).catch(() => null);
    if (!treeRes || !treeRes.ok) return false;
    const treeData = await treeRes.json();

    // 4. Create Commit
    const newCommitRes = await fetch(`https://api.github.com/repos/${repo}/git/commits`, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        message: `sync(db): sincronizacao em tempo real [${new Date().toISOString()}]`,
        tree: treeData.sha,
        parents: [currentSha]
      })
    }).catch(() => null);
    if (!newCommitRes || !newCommitRes.ok) return false;
    const newCommitData = await newCommitRes.json();

    // 5. Update ref heads/main
    await fetch(`https://api.github.com/repos/${repo}/git/refs/heads/main`, {
      method: 'PATCH',
      headers,
      body: JSON.stringify({ sha: newCommitData.sha, force: false })
    }).catch(() => null);

    console.info(`[SIGEC-Pro GitHub Sync] data/db.json sincronizado com sucesso no GitHub (${newCommitData.sha})`);
    return true;
  } catch (err) {
    console.warn('[SIGEC-Pro GitHub Sync] Aviso ao sincronizar com GitHub:', err);
    return false;
  }
}
window.syncDatabaseToGitHub = syncDatabaseToGitHub;

const INITIAL_EXCEL_DATABASE = { clientes: [], contactos: [], projetos: [], interacoes: [], interacoesProjetos: [], usuarios: [], userLogs: [] };
const STORAGE_KEYS = {
  CLIENTES: 'sigec_pro_db_clientes_v6',
  CONTACTOS: 'sigec_pro_db_contactos_v6',
  PROJETOS: 'sigec_pro_db_projetos_v6',
  INTERACOES: 'sigec_pro_db_interacoes_v6',
  INTERACOES_PROJETOS: 'sigec_pro_db_interacoes_projetos_v6',
  DELETED_CLIENTES: 'sigec_pro_db_deleted_clientes_v6',
  DELETED_CONTACTOS: 'sigec_pro_db_deleted_contactos_v6',
  DELETED_PROJETOS: 'sigec_pro_db_deleted_projetos_v6',
  DELETED_INTERACOES: 'sigec_pro_db_deleted_interacoes_v6',
  DELETED_INTERACOES_PROJETOS: 'sigec_pro_db_deleted_interacoes_projetos_v6',
  DELETED_ORCAMENTOS: 'sigec_pro_db_deleted_orcamentos_v6',
  DELETED_USUARIOS: 'sigec_pro_db_deleted_usuarios_v6',
  IGNORED_DUPLICATES: 'sigec_pro_ignored_duplicates'
};

let deletedRegistry = {
  clientes: [],
  contactos: [],
  projetos: [],
  interacoes: [],
  interacoesProjetos: [],
  orcamentos: [],
  usuarios: []
};

let deletedProjectIds = [];

function generateId(prefix = 'id') {
  return `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
}
window.generateId = generateId;

function loadDeletedRegistry() {
  try {
    const parseKey = (key, fallbackKey = null) => {
      let raw = localStorage.getItem(key);
      if (raw === null && fallbackKey) raw = localStorage.getItem(fallbackKey);
      try {
        return raw ? JSON.parse(raw) : [];
      } catch (e) {
        return [];
      }
    };

    deletedRegistry.clientes = parseKey(STORAGE_KEYS.DELETED_CLIENTES);
    deletedRegistry.contactos = parseKey(STORAGE_KEYS.DELETED_CONTACTOS);
    deletedRegistry.projetos = parseKey(STORAGE_KEYS.DELETED_PROJETOS, 'centauro_db_deleted_projetos_v6');
    deletedRegistry.interacoes = parseKey(STORAGE_KEYS.DELETED_INTERACOES);
    deletedRegistry.interacoesProjetos = parseKey(STORAGE_KEYS.DELETED_INTERACOES_PROJETOS);
    deletedRegistry.orcamentos = parseKey(STORAGE_KEYS.DELETED_ORCAMENTOS);
    deletedRegistry.usuarios = parseKey(STORAGE_KEYS.DELETED_USUARIOS);

    deletedProjectIds = deletedRegistry.projetos || [];
  } catch (e) {
    console.error('Erro ao carregar registo de eliminados:', e);
  }
}

function saveDeletedRegistry() {
  try {
    safeSetStorage(STORAGE_KEYS.DELETED_CLIENTES, JSON.stringify(deletedRegistry.clientes || []));
    safeSetStorage(STORAGE_KEYS.DELETED_CONTACTOS, JSON.stringify(deletedRegistry.contactos || []));
    safeSetStorage(STORAGE_KEYS.DELETED_PROJETOS, JSON.stringify(deletedRegistry.projetos || []));
    safeSetStorage(STORAGE_KEYS.DELETED_INTERACOES, JSON.stringify(deletedRegistry.interacoes || []));
    safeSetStorage(STORAGE_KEYS.DELETED_INTERACOES_PROJETOS, JSON.stringify(deletedRegistry.interacoesProjetos || []));
    safeSetStorage(STORAGE_KEYS.DELETED_ORCAMENTOS, JSON.stringify(deletedRegistry.orcamentos || []));
    safeSetStorage(STORAGE_KEYS.DELETED_USUARIOS, JSON.stringify(deletedRegistry.usuarios || []));
    deletedProjectIds = deletedRegistry.projetos || [];
  } catch (e) {
    console.error('Erro ao guardar registo de eliminados:', e);
  }
}

function addDeletedId(type, id) {
  if (!type || !id) return;
  const strId = String(id).trim();
  if (!strId) return;
  if (!deletedRegistry[type]) deletedRegistry[type] = [];
  const lower = strId.toLowerCase();
  if (!deletedRegistry[type].some(x => String(x).trim().toLowerCase() === lower)) {
    deletedRegistry[type].push(strId);
    saveDeletedRegistry();
  }
}

function isDeletedId(type, id) {
  if (!type || !id) return false;
  const strId = String(id).trim().toLowerCase();
  if (!deletedRegistry[type] || !Array.isArray(deletedRegistry[type])) return false;
  return deletedRegistry[type].some(del => String(del).trim().toLowerCase() === strId);
}

function removeDeletedId(type, id) {
  if (!type || !id) return;
  const strId = String(id).trim().toLowerCase();
  if (!strId || !deletedRegistry[type] || !Array.isArray(deletedRegistry[type])) return;
  const idx = deletedRegistry[type].findIndex(del => String(del).trim().toLowerCase() === strId);
  if (idx >= 0) {
    deletedRegistry[type].splice(idx, 1);
    saveDeletedRegistry();
  }
}

function clearDeletedRegistry() {
  deletedRegistry = {
    clientes: [],
    contactos: [],
    projetos: [],
    interacoes: [],
    interacoesProjetos: [],
    orcamentos: [],
    usuarios: []
  };
  deletedProjectIds = [];
  saveDeletedRegistry();
}

function loadDeletedProjectIds() {
  loadDeletedRegistry();
}

function saveDeletedProjectIds() {
  saveDeletedRegistry();
}

function addDeletedProjectId(id) {
  addDeletedId('projetos', id);
}

function filterDeletedProjects(projectsList) {
  if (!Array.isArray(projectsList)) return [];
  return projectsList.filter(p => p && p.id && !isDeletedId('projetos', p.id));
}

function filterAllDeletedEntities() {
  if (Array.isArray(db.clientes)) {
    db.clientes = db.clientes.filter(c => c && c.id && !isDeletedId('clientes', c.id));
  }
  if (Array.isArray(db.contactos)) {
    db.contactos = db.contactos.filter(c => c && c.id && !isDeletedId('contactos', c.id));
  }
  if (Array.isArray(db.projetos)) {
    db.projetos = db.projetos.filter(p => p && p.id && !isDeletedId('projetos', p.id));
  }
  if (Array.isArray(db.interacoes)) {
    db.interacoes = db.interacoes.filter(i => i && i.id && !isDeletedId('interacoes', i.id));
  }
  if (Array.isArray(db.interacoesProjetos)) {
    db.interacoesProjetos = db.interacoesProjetos.filter(i => i && i.id && !isDeletedId('interacoesProjetos', i.id));
  }
  if (Array.isArray(db.orcamentos)) {
    db.orcamentos = db.orcamentos.filter(o => o && o.id && !isDeletedId('orcamentos', o.id));
  }
  if (Array.isArray(db.usuarios)) {
    db.usuarios = db.usuarios.filter(u => u && u.id && !isDeletedId('usuarios', u.id));
  }
}

