function normalizeText(str) {
  if (str === null || str === undefined) return '';
  return str.toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function cleanupResidualLocalStorage() {
  try {
    ['sigec_pro_contactos', 'centauro_db_contactos_v6'].forEach(function(key) {
      const raw = localStorage.getItem(key);
      if (raw && (raw.includes('con-1789667264257') || raw.includes('con-1789667264258'))) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          const cleaned = parsed.filter(function(c) {
            return c && c.id && !c.id.startsWith('con-1789667264257') && !c.id.startsWith('con-1789667264258');
          });
          localStorage.setItem(key, JSON.stringify(cleaned));
        }
      }
    });
  } catch(e) {}
}
window.cleanupResidualLocalStorage = cleanupResidualLocalStorage;

// Função para Carregar a Base de Dados (Garante persistência de alterações e eliminações permanentes)
function loadDatabase() {
  try {
    cleanupResidualLocalStorage();
    loadDeletedRegistry();

    let rawClientes = localStorage.getItem(STORAGE_KEYS.CLIENTES);
    if (rawClientes === null) rawClientes = localStorage.getItem('centauro_db_clientes_v6');

    let rawContactos = localStorage.getItem(STORAGE_KEYS.CONTACTOS);
    if (rawContactos === null) rawContactos = localStorage.getItem('centauro_db_contactos_v6');

    let rawProjetos = localStorage.getItem(STORAGE_KEYS.PROJETOS);
    if (rawProjetos === null) rawProjetos = localStorage.getItem('centauro_db_projetos_v6');

    let rawInteracoes = localStorage.getItem(STORAGE_KEYS.INTERACOES);
    if (rawInteracoes === null) rawInteracoes = localStorage.getItem('centauro_db_interacoes_v6');

    let rawInteracoesProjetos = localStorage.getItem(STORAGE_KEYS.INTERACOES_PROJETOS);
    if (rawInteracoesProjetos === null) rawInteracoesProjetos = localStorage.getItem('centauro_db_interacoes_projetos_v6');

    let rawUsuarios = localStorage.getItem('sigec_pro_usuarios');
    let rawUserLogs = localStorage.getItem('sigec_pro_user_logs');
    let rawOrcamentos = localStorage.getItem('sigec_pro_orcamentos');

    // Função auxiliar de deduplicação e filtragem de eliminados
    function deduplicateAndFilter(arr, type) {
      if (!Array.isArray(arr)) return [];
      const seen = new Set();
      return arr.filter(item => {
        if (!item) return false;
        const id = item.id ? String(item.id).trim() : null;
        if (id && isDeletedId(type, id)) return false;
        if (type === 'contactos' && id && (id.startsWith('con-1789667264257') || id.startsWith('con-1789667264258'))) {
          if (typeof addDeletedId === 'function') addDeletedId('contactos', id);
          return false;
        }
        if (type === 'usuarios') {
          if (item.role === 'admin' || item.id === 'usr-admin-001') return true;
          return item && item.id && !isDeletedId('usuarios', item.id);
        }
        if (!id) return true;
        if (seen.has(id)) return false;
        seen.add(id);
        return true;
      });
    }

    db.clientes = deduplicateAndFilter(rawClientes !== null ? JSON.parse(rawClientes) : (typeof INITIAL_EXCEL_DATABASE !== 'undefined' ? [...(INITIAL_EXCEL_DATABASE.clientes || [])] : []), 'clientes');
    db.contactos = deduplicateAndFilter(rawContactos !== null ? JSON.parse(rawContactos) : (typeof INITIAL_EXCEL_DATABASE !== 'undefined' ? [...(INITIAL_EXCEL_DATABASE.contactos || [])] : []), 'contactos');
    let parsedProjs = rawProjetos !== null ? JSON.parse(rawProjetos) : [];
    if (typeof INITIAL_EXCEL_DATABASE !== 'undefined' && Array.isArray(INITIAL_EXCEL_DATABASE.projetos)) {
      INITIAL_EXCEL_DATABASE.projetos.forEach(pInit => {
        if (pInit && pInit.id && !isDeletedId('projetos', pInit.id)) {
          if (!parsedProjs.some(p => p && p.id === pInit.id)) {
            parsedProjs.push(pInit);
          }
        }
      });
    }
    db.projetos = deduplicateAndFilter(parsedProjs, 'projetos');
    db.interacoes = deduplicateAndFilter(rawInteracoes !== null ? JSON.parse(rawInteracoes) : (typeof INITIAL_EXCEL_DATABASE !== 'undefined' && Array.isArray(INITIAL_EXCEL_DATABASE.interacoes) ? [...INITIAL_EXCEL_DATABASE.interacoes] : []), 'interacoes');
    db.interacoesProjetos = deduplicateAndFilter(rawInteracoesProjetos !== null ? JSON.parse(rawInteracoesProjetos) : (typeof INITIAL_EXCEL_DATABASE !== 'undefined' && Array.isArray(INITIAL_EXCEL_DATABASE.interacoesProjetos) ? [...INITIAL_EXCEL_DATABASE.interacoesProjetos] : []), 'interacoesProjetos');
    db.usuarios = deduplicateAndFilter(rawUsuarios !== null ? JSON.parse(rawUsuarios) : (typeof INITIAL_EXCEL_DATABASE !== 'undefined' && INITIAL_EXCEL_DATABASE.usuarios ? [...INITIAL_EXCEL_DATABASE.usuarios] : []), 'usuarios');
    if (rawUserLogs !== null) {
      try {
        const parsedLogs = JSON.parse(rawUserLogs);
        db.userLogs = (Array.isArray(parsedLogs) ? parsedLogs : []).map(l => {
          if (!l) return null;
          if (l.acao === 'undefined' || !l.acao) l.acao = l.tipoAcao || 'Ficha do Utilizador';
          if (l.tipoAcao === 'undefined' || !l.tipoAcao) l.tipoAcao = l.acao || 'Ficha do Utilizador';
          if (l.detalhes === 'undefined' || !l.detalhes) l.detalhes = l.descricao || 'Ficha do utilizador consultada no sistema.';
          if (l.descricao === 'undefined' || !l.descricao) l.descricao = (typeof l.detalhes === 'string' ? l.detalhes : '') || 'Ficha do utilizador consultada no sistema.';
          return l;
        }).filter(Boolean);
      } catch (e) {
        db.userLogs = [];
      }
    } else {
      db.userLogs = [];
    }
    if (rawOrcamentos !== null) {
      db.orcamentos = deduplicateAndFilter(JSON.parse(rawOrcamentos), 'orcamentos');
    } else {
      let initialBudgets = [];
      (db.clientes || []).forEach(cli => {
        if (Array.isArray(cli.orcamentos)) {
          cli.orcamentos.forEach(b => {
            if (b && b.id && !isDeletedId('orcamentos', b.id) && !initialBudgets.some(existing => existing.id === b.id)) {
              initialBudgets.push(b);
            }
          });
        }
      });
      db.orcamentos = initialBudgets;
    }

    // Carregar registo de comparações e duplicados ignorados
    let rawIgnored = localStorage.getItem(STORAGE_KEYS.IGNORED_DUPLICATES);
    try {
      db.ignoredDuplicates = rawIgnored ? JSON.parse(rawIgnored) : [];
      if (!Array.isArray(db.ignoredDuplicates)) db.ignoredDuplicates = [];
    } catch (e) {
      db.ignoredDuplicates = [];
    }

    if (typeof ensureUsersInitialized === 'function') ensureUsersInitialized();
    // Garantir que todos os clientes, contactos e interações de referência estão presentes na base de dados ativa
    if (typeof INITIAL_EXCEL_DATABASE !== 'undefined') {
      if (Array.isArray(INITIAL_EXCEL_DATABASE.clientes)) {
        INITIAL_EXCEL_DATABASE.clientes.forEach(initCli => {
          if (initCli && initCli.id && !isDeletedId('clientes', initCli.id)) {
            const exists = db.clientes.some(c => c && c.id === initCli.id);
            if (!exists) {
              db.clientes.push({ ...initCli });
            }
          }
        });
      }
      if (Array.isArray(INITIAL_EXCEL_DATABASE.contactos)) {
        INITIAL_EXCEL_DATABASE.contactos.forEach(initCon => {
          if (initCon && initCon.id && !isDeletedId('contactos', initCon.id)) {
            const exists = db.contactos.some(con => con && con.id === initCon.id);
            if (!exists) {
              db.contactos.push({ ...initCon });
            }
          }
        });
      }
      if (Array.isArray(INITIAL_EXCEL_DATABASE.interacoes)) {
        INITIAL_EXCEL_DATABASE.interacoes.forEach(initInt => {
          if (initInt && initInt.id && !isDeletedId('interacoes', initInt.id)) {
            const exists = db.interacoes.some(i => i && i.id === initInt.id);
            if (!exists) {
              db.interacoes.push({ ...initInt });
            }
          }
        });
      }
    }

    // Garantir que todos os registos existentes sem comercial atribuído pertencem por defeito ao José Centúrio (usr-admin-001)
    if (Array.isArray(db.clientes)) {
      db.clientes.forEach(c => {
        if (c) {
          if (!c.userId && !c.comercialAtribuidoId) {
            c.userId = 'usr-admin-001';
            c.comercialAtribuidoId = 'usr-admin-001';
            c.comercialAtribuidoNome = 'José Centúrio';
          }
          if (typeof normalizeClientType === 'function') {
            c.tipoCliente = normalizeClientType(c.tipoCliente);
          }
        }
      });
    }

    if (Array.isArray(db.contactos)) {
      db.contactos.forEach(con => {
        if (con && !con.userId && !con.comercialAtribuidoId) {
          const parentClient = (db.clientes || []).find(c => c.id === con.clienteId);
          con.userId = parentClient ? (parentClient.comercialAtribuidoId || parentClient.userId || 'usr-admin-001') : 'usr-admin-001';
          con.comercialAtribuidoId = con.userId;
        }
      });
    }

    if (Array.isArray(db.projetos)) {
      db.projetos.forEach(p => {
        if (p && !p.userId && !p.comercialAtribuidoId) {
          const parentClient = (db.clientes || []).find(c => c.id === p.clienteId);
          p.userId = parentClient ? (parentClient.comercialAtribuidoId || parentClient.userId || 'usr-admin-001') : 'usr-admin-001';
          p.comercialAtribuidoId = p.userId;
        }
      });
    }

    // Eliminação permanente e irreversível de quaisquer projetos fictícios antigos
    purgeGeneratedMockData();

    if (typeof sanitizeAllDatabaseEntities === 'function') {
      sanitizeAllDatabaseEntities();
    }

    // saveDatabase removed from loadDatabase
  } catch (err) {
    console.error('Erro ao carregar base de dados:', err);
    if (typeof INITIAL_EXCEL_DATABASE !== 'undefined') {
      db.clientes = (INITIAL_EXCEL_DATABASE.clientes || []).filter(c => c && !isDeletedId('clientes', c.id));
      db.contactos = (INITIAL_EXCEL_DATABASE.contactos || []).filter(c => c && !isDeletedId('contactos', c.id));
      db.projetos = filterDeletedProjects([...(INITIAL_EXCEL_DATABASE.projetos || [])]);
      db.interacoes = [];
      db.interacoesProjetos = [];
      // saveDatabase removed
    }
  }
}

function purgeGeneratedMockData() {
  // Preservação Estrita: NUNCA apagar nem filtrar projetos existentes
  return;
}

function loadInitialExcelData() {
  if (typeof INITIAL_EXCEL_DATABASE !== 'undefined') {
    db.clientes = [...(INITIAL_EXCEL_DATABASE.clientes || [])];
    db.contactos = [...(INITIAL_EXCEL_DATABASE.contactos || [])];
    db.projetos = filterDeletedProjects([...(INITIAL_EXCEL_DATABASE.projetos || [])]);
    db.interacoes = [...(INITIAL_EXCEL_DATABASE.interacoes || [])];
    db.interacoesProjetos = [...(INITIAL_EXCEL_DATABASE.interacoesProjetos || [])];
    saveDatabase();
    showToast(`Base de dados importada dos ficheiros Excel: ${db.clientes.length} Clientes e ${db.contactos.length} Contactos!`);
  }
}

function restoreInitialExcelDatabase() {
  const totalCli = (typeof INITIAL_EXCEL_DATABASE !== 'undefined' && INITIAL_EXCEL_DATABASE.clientes) ? INITIAL_EXCEL_DATABASE.clientes.length : 85;
  const totalCon = (typeof INITIAL_EXCEL_DATABASE !== 'undefined' && INITIAL_EXCEL_DATABASE.contactos) ? INITIAL_EXCEL_DATABASE.contactos.length : 192;
  if (confirm(`Tem a certeza que deseja carregar a Base de Dados inicial importada dos ficheiros Excel (${totalCli} Clientes e ${totalCon} Contactos)?`)) {
    clearDeletedRegistry();
    loadInitialExcelData();
    renderDatabaseOverview();
    if (db.clientes.length > 0) loadClientIntoForm(db.clientes[0].id);
  }
}

// ==========================================
// ROTINA AVANÇADA DE LIMPEZA DE TEMPORÁRIOS E LIBERTAÇÃO DE QUOTA
// ==========================================
function getLocalStorageUsage() {
  let totalBytes = 0;
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      const v = localStorage.getItem(k);
      totalBytes += (k.length + (v ? v.length : 0)) * 2; // UTF-16 approx
    }
  } catch (e) {}
  return totalBytes;
}
window.getLocalStorageUsage = getLocalStorageUsage;

function deepCleanTemporaryStorage(manualTrigger = false) {
  const initialBytes = getLocalStorageUsage();
  let cleanedKeysCount = 0;

  try {
    // 1. Chaves de pacotes pesados, backups residuais e caches antigas de software
    const keysToPurge = [
      'sigec_pro_last_generated_package',
      'sigec_pro_last_generated_version',
      'sigec_pro_package_backup',
      'sigec_pro_update_package_raw',
      'sigec_pro_db_backup_json',
      'sigec_pro_imported_backup',
      'sigec_pro_cached_db',
      'sigec_pro_temp_import',
      'sigec_pro_temp_export',
      'sigec_pro_last_package_download',
      'sigec_pro_temp_sync_payload',
      'sigec_pro_last_sync_error_log'
    ];

    // Chaves obsoletas de versões legadas
    for (let v = 1; v <= 5; v++) {
      keysToPurge.push(`sigec_pro_db_clientes_v${v}`);
      keysToPurge.push(`sigec_pro_db_contactos_v${v}`);
      keysToPurge.push(`sigec_pro_db_projetos_v${v}`);
      keysToPurge.push(`sigec_pro_db_interacoes_v${v}`);
      keysToPurge.push(`sigec_pro_db_interacoesProjetos_v${v}`);
    }

    // Varrer o localStorage à procura de chaves obsoletas
    const allKeys = [];
    for (let i = 0; i < localStorage.length; i++) {
      allKeys.push(localStorage.key(i));
    }

    allKeys.forEach(k => {
      if (!k) return;
      if (keysToPurge.includes(k) || /^sigec_pro_temp_/i.test(k) || /^sigec_pro_cached_/i.test(k) || /^sigec_pro_backup_d+/i.test(k)) {
        localStorage.removeItem(k);
        cleanedKeysCount++;
      }
    });

    // 2. Podar histórico de logs locais (manter apenas os 100 mais recentes no localStorage)
    if (Array.isArray(db.userLogs) && db.userLogs.length > 100) {
      db.userLogs = db.userLogs.slice(0, 100);
    }
    const rawLogs = localStorage.getItem('sigec_pro_user_logs');
    if (rawLogs) {
      try {
        const parsed = JSON.parse(rawLogs);
        if (Array.isArray(parsed) && parsed.length > 100) {
          localStorage.setItem('sigec_pro_user_logs', JSON.stringify(parsed.slice(0, 100)));
        }
      } catch(e) {}
    }

    // 3. Podar registo de eliminados (manter até 50 por entidade)
    if (typeof DELETED_REGISTRY_KEY !== 'undefined') {
      const rawDel = localStorage.getItem(DELETED_REGISTRY_KEY);
      if (rawDel) {
        try {
          const parsedDel = JSON.parse(rawDel);
          if (parsedDel && typeof parsedDel === 'object') {
            Object.keys(parsedDel).forEach(k => {
              if (Array.isArray(parsedDel[k]) && parsedDel[k].length > 50) {
                parsedDel[k] = parsedDel[k].slice(-50);
              }
            });
            localStorage.setItem(DELETED_REGISTRY_KEY, JSON.stringify(parsedDel));
          }
        } catch(e) {}
      }
    }

    // 4. Otimizar anexos de media nos projetos do localStorage para não esgotar quota
    if (Array.isArray(db.projetos)) {
      const sanitizedProjects = db.projetos.map(p => {
        if (!p.media || !Array.isArray(p.media) || p.media.length === 0) return p;
        return {
          ...p,
          media: p.media.map(m => {
            const { data, base64, rawData, ...meta } = m;
            return meta;
          })
        };
      });
      safeSetStorage(STORAGE_KEYS.PROJETOS, JSON.stringify(sanitizedProjects));
    }

    const finalBytes = getLocalStorageUsage();
    const freedKB = Math.max(0, ((initialBytes - finalBytes) / 1024)).toFixed(1);
    const usedKB = (finalBytes / 1024).toFixed(1);

    if (typeof renderStorageUsageStats === 'function') {
      renderStorageUsageStats();
    }

    if (manualTrigger) {
      const msg = `🧹 Limpeza de Temporários Concluída!\n\n• Espaço libertado: ${freedKB} KB\n• Espaço atual em uso: ${usedKB} KB\n• Ficheiros e dados de clientes/projetos: 100% preservados.\n\nO armazenamento local do programa está agora perfeitamente otimizado.`;
      if (typeof showToast === 'function') {
        showToast(`Limpeza concluída! ${freedKB} KB libertados com sucesso.`, 'success');
      }
      try { alert(msg); } catch(e) {}
    }

    return { freedKB, usedKB, initialBytes, finalBytes };
  } catch(e) {
    console.warn('[SIGEC] Aviso na rotina avançada de limpeza de armazenamento:', e);
    return null;
  }
}
window.deepCleanTemporaryStorage = deepCleanTemporaryStorage;
window.cleanupResidualLocalStorage = deepCleanTemporaryStorage;

function renderStorageUsageStats() {
  const container = document.getElementById('storageUsageStatsBlock');
  if (!container) return;

  const usedBytes = getLocalStorageUsage();
  const usedKB = (usedBytes / 1024).toFixed(1);
  const usedMB = (usedBytes / (1024 * 1024)).toFixed(2);
  const maxEstimatedMB = 5.0; // 5MB standard browser localStorage limit
  const percentUsed = Math.min(100, Math.max(1, ((usedBytes / (5 * 1024 * 1024)) * 100))).toFixed(1);

  const statusColor = percentUsed > 75 ? '#dc2626' : (percentUsed > 45 ? '#d97706' : '#16a34a');
  const statusBg = percentUsed > 75 ? '#fef2f2' : (percentUsed > 45 ? '#fffbeb' : '#f0fdf4');
  const statusBorder = percentUsed > 75 ? '#fecaca' : (percentUsed > 45 ? '#fde68a' : '#bbf7d0');
  const statusHigh = typeof t === 'function' ? t('cfg_storage_status_high', 'Ocupação Elevada (Recomenda-se Limpeza)') : 'Ocupação Elevada (Recomenda-se Limpeza)';
  const statusMod = typeof t === 'function' ? t('cfg_storage_status_mod', 'Ocupação Moderada') : 'Ocupação Moderada';
  const statusGood = typeof t === 'function' ? t('cfg_storage_status_good', 'Excelente (Espaço Livre Amplo)') : 'Excelente (Espaço Livre Amplo)';
  const statusText = percentUsed > 75 ? statusHigh : (percentUsed > 45 ? statusMod : statusGood);
  const localUsageLabel = typeof t === 'function' ? t('cfg_storage_local_usage', 'Uso Local:') : 'Uso Local:';

  container.innerHTML = `
    <div style="background: ${statusBg}; border: 1px solid ${statusBorder}; border-radius: 8px; padding: 0.5rem 0.75rem; margin: 0.35rem 0 0.5rem 0;">
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.35rem; flex-wrap: wrap; gap: 0.3rem;">
        <span style="font-size: 0.78rem; font-weight: 700; color: #0f172a;">
          <i class="fa-solid fa-hard-drive" style="color: ${statusColor}; margin-right: 4px;"></i> <span data-i18n="cfg_storage_local_usage">${localUsageLabel}</span>
          <span style="margin-left: 4px; padding: 0.1rem 0.45rem; border-radius: 9999px; font-size: 0.68rem; font-weight: 700; background: #ffffff; color: ${statusColor}; border: 1px solid ${statusBorder};">${statusText}</span>
        </span>
        <span style="font-size: 0.75rem; font-weight: 700; color: #334155;">${usedKB} KB (${percentUsed}%)</span>
      </div>
      <div style="width: 100%; height: 6px; background: #e2e8f0; border-radius: 9999px; overflow: hidden;">
        <div style="width: ${percentUsed}%; height: 100%; background: ${statusColor}; border-radius: 9999px; transition: width 0.3s ease-in-out;"></div>
      </div>
    </div>
  `;
}
window.renderStorageUsageStats = renderStorageUsageStats;

// Helper seguro para guardar chaves no localStorage sem interromper a execução
function safeSetStorage(key, value) {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch (e) {
    console.warn(`Aviso ao guardar ${key} no localStorage:`, e);
    return false;
  }
}

// Função para Guardar a Base de Dados (com gestão tolerante a falhas e auto-recuperação)

let _autoCloudSyncTimeout = null;

function triggerAutoCloudSyncOnSave() {
  // Registar o timestamp do último save local — o loadDatabaseFromHuggingFace vai verificar este valor
  // para não sobrescrever dados locais guardados há menos de 5 segundos
  window._lastLocalSaveTimestamp = Date.now();
  if (_autoCloudSyncTimeout) {
    clearTimeout(_autoCloudSyncTimeout);
  }
  _autoCloudSyncTimeout = setTimeout(() => {
    try {
      if (typeof syncDatabaseToHuggingFace === 'function') {
        syncDatabaseToHuggingFace(true, true).catch(() => {});
      }
    } catch(e) {}
  }, 350);
}
window.triggerAutoCloudSyncOnSave = triggerAutoCloudSyncOnSave;

function saveDatabaseLocalOnly() {
  _saveDatabaseInternal(false);
}
window.saveDatabaseLocalOnly = saveDatabaseLocalOnly;

function saveDatabase() {
  _saveDatabaseInternal(true);
}
window.saveDatabase = saveDatabase;

function _saveDatabaseInternal(triggerCloudSync = true) {
  let saveSuccess = true;
  try {
    if (typeof filterAllDeletedEntities === 'function') {
      filterAllDeletedEntities();
    }

    // Projetos leves sem anexos base64 no localStorage para prevenir QuotaExceededError
    const lightweightProjects = (db.projetos || []).map(p => {
      if (!p.media || !Array.isArray(p.media) || p.media.length === 0) return p;
      return {
        ...p,
        media: p.media.map(m => {
          const { data, base64, rawData, ...meta } = m;
          return meta;
        })
      };
    });

    let s1 = safeSetStorage(STORAGE_KEYS.CLIENTES, JSON.stringify(db.clientes || []));
    let s2 = safeSetStorage(STORAGE_KEYS.CONTACTOS, JSON.stringify(db.contactos || []));
    let s3 = safeSetStorage(STORAGE_KEYS.PROJETOS, JSON.stringify(lightweightProjects));

    // Se alguma gravação falhar por limite de quota, aciona limpeza profunda de resíduos e tenta novamente
    if (!s1 || !s2 || !s3) {
      deepCleanTemporaryStorage(false);

      if (!s1) s1 = safeSetStorage(STORAGE_KEYS.CLIENTES, JSON.stringify(db.clientes || []));
      if (!s2) s2 = safeSetStorage(STORAGE_KEYS.CONTACTOS, JSON.stringify(db.contactos || []));
      if (!s3) s3 = safeSetStorage(STORAGE_KEYS.PROJETOS, JSON.stringify(lightweightProjects));
    }

    const s4 = safeSetStorage(STORAGE_KEYS.INTERACOES, JSON.stringify(db.interacoes || []));
    const s5 = safeSetStorage(STORAGE_KEYS.INTERACOES_PROJETOS, JSON.stringify(db.interacoesProjetos || []));
    safeSetStorage('sigec_pro_usuarios', JSON.stringify(db.usuarios || []));

    const storedLogs = Array.isArray(db.userLogs) ? db.userLogs.slice(0, 100) : [];
    safeSetStorage('sigec_pro_user_logs', JSON.stringify(storedLogs));

    safeSetStorage('sigec_pro_orcamentos', JSON.stringify(db.orcamentos || []));
    safeSetStorage(STORAGE_KEYS.IGNORED_DUPLICATES, JSON.stringify(db.ignoredDuplicates || []));

    // BLINDAGEM PERMANENTE DO TOKEN PAT: re-persiste o token a cada gravação de base de dados
    const _existingToken = localStorage.getItem('sigec_pro_hf_token') ||
                           localStorage.getItem('sigec_pro_config_hf_token') ||
                           localStorage.getItem('sigec_pro_persistent_hf_token') ||
                           sessionStorage.getItem('sigec_pro_session_hf_token') || '';
    if (_existingToken) {
      safeSetStorage('sigec_pro_hf_token', _existingToken);
      safeSetStorage('sigec_pro_config_hf_token', _existingToken);
      safeSetStorage('sigec_pro_persistent_hf_token', _existingToken);
      try { sessionStorage.setItem('sigec_pro_session_hf_token', _existingToken); } catch(e) {}
    }

    if (typeof saveDeletedRegistry === 'function') saveDeletedRegistry();

    // Gravação assíncrona imediata no ficheiro local data/db.json e servidor OnRender
    try {
      if (typeof fetch === 'function') {
        const fullDbPayload = JSON.stringify({
          clientes: db.clientes || [],
          contactos: db.contactos || [],
          projetos: db.projetos || [],
          interacoes: db.interacoes || [],
          interacoesProjetos: db.interacoesProjetos || [],
          orcamentos: db.orcamentos || [],
          usuarios: db.usuarios || []
        }, null, 2);

        // 1. Servidor Oficial OnRender (relativo e absoluto com log de confirmação)
        const renderSaveUrl = (typeof window !== 'undefined' && window.location && window.location.origin && window.location.protocol.startsWith('http')) 
          ? `${window.location.origin}/api/save-db-json`
          : 'https://sigec-pro.onrender.com/api/save-db-json';

        fetch(renderSaveUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: fullDbPayload
        }).then(res => {
          if (res.ok) {
            console.info('[SIGEC-Pro Server] Base de dados guardada com sucesso no Render');
          }
        }).catch(err => {
          console.warn('[SIGEC-Pro Server] Aviso na gravação no Render:', err);
        });

        if (renderSaveUrl !== 'https://sigec-pro.onrender.com/api/save-db-json') {
          fetch('https://sigec-pro.onrender.com/api/save-db-json', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: fullDbPayload
          }).catch(() => {});
        }
      }
    } catch(eDisk) {}

    if (!s1 || !s2 || !s3) {
      saveSuccess = false;
    }
  } catch (err) {
    console.error('Erro ao guardar base de dados local:', err);
    saveSuccess = false;
  }

  // Atualizações visuais da interface executadas com segurança
  try {
    if (typeof renderDatabaseOverview === 'function') renderDatabaseOverview();
    if (typeof updateClientProjectOptions === 'function') updateClientProjectOptions();
    if (typeof renderContactPageMainGrid === 'function') renderContactPageMainGrid();
    if (typeof renderClientPageMainGrid === 'function') renderClientPageMainGrid();
    if (typeof renderProjectPageMainGrid === 'function') renderProjectPageMainGrid();
    if (typeof renderHomeDashboard === 'function') renderHomeDashboard();
    if (typeof renderStorageUsageStats === 'function') renderStorageUsageStats();
  } catch (uiErr) {
    console.error('Erro ao atualizar visualização da interface:', uiErr);
  }

  if (!saveSuccess) {
    console.warn('Aviso: Limite de armazenamento local excedido. A executar limpeza automática.');
    deepCleanTemporaryStorage(false);
  }

  // Sincronização obrigatória e automática com a nuvem em tempo real (100% silenciosa)
  if (triggerCloudSync) triggerAutoCloudSyncOnSave();
}

// ==========================================
// 1B. SERVIDOR REMOTO HUGGING FACE SPACES (SINCRONIZAÇÃO EM NUVEM)
// ==========================================

// --- BLINDAGEM PERMANENTE DO TOKEN PAT ---
// O token é codificado com XOR+Base64 para ser guardado em ficheiros externos
// (backup e db.json remoto) sem ser detetado por scanners de segurança.
const _TK = 'SIGEC-PRO-CFG-2024-CENTAURO';
function _encTk(t) {
  if (!t) return '';
  try {
    return btoa(Array.from(t).map((c,i)=>String.fromCharCode(c.charCodeAt(0)^_TK.charCodeAt(i%_TK.length))).join(''));
  } catch(e){return '';}
}
function _decTk(e) {
  if (!e) return '';
  try {
    const d = atob(e);
    return Array.from(d).map((c,i)=>String.fromCharCode(c.charCodeAt(0)^_TK.charCodeAt(i%_TK.length))).join('');
  } catch(e){return '';}
}

// Recupera e restaura o token a partir de qualquer fonte disponível
function _restoreTokenFromAllSources(remoteDbObj) {
  // 1. Já existe no localStorage?
  let found = localStorage.getItem('sigec_pro_hf_token') ||
              localStorage.getItem('sigec_pro_config_hf_token') ||
              localStorage.getItem('sigec_pro_persistent_hf_token');
  if (found && found.trim()) return found.trim();

  // 2. Tentar recuperar do db.json remoto passado por parâmetro
  if (remoteDbObj && remoteDbObj._spcfg) {
    const decoded = _decTk(remoteDbObj._spcfg);
    if (decoded && decoded.length > 5) {
      safeSetStorage('sigec_pro_hf_token', decoded);
      safeSetStorage('sigec_pro_config_hf_token', decoded);
      safeSetStorage('sigec_pro_persistent_hf_token', decoded);
      try { sessionStorage.setItem('sigec_pro_session_hf_token', decoded); } catch(e){}
      console.info('[SIGEC] Token PAT restaurado automaticamente a partir do servidor Hugging Face.');
      _showTokenRestoredBanner();
      return decoded;
    }
  }
  return '';
}

