async function handleFullServerSync(silent = false) {
  ensureUsersInitialized();
  const activeUserId = sessionStorage.getItem('sigec_pro_active_user_id');
  const activeUser = (activeUserId && typeof db !== 'undefined' && Array.isArray(db.usuarios)) ? db.usuarios.find(u => u && u.id === activeUserId) : null;

  if (!activeUser || !hasConfigAccess(activeUser)) {
    if (!silent) {
      showToast('Acesso restrito ao Administrador.', 'warning');
      alert('Acesso Restrito:\nApenas o Administrador pode executar a sincronizacao com o servidor.');
    }
    return false;
  }

  if (!silent) showToast('A sincronizar com o Servidor...', 'info');

  // 1. Enviar dados para o servidor (push)
  let pushOk = false;
  try {
    pushOk = await syncDatabaseToHuggingFace(true, true);
  } catch(ePush) {}
  // Garantir que o flag de sincronizacao fica limpo antes de prosseguir
  isSyncingToHuggingFace = false;
  // 2. Pull bidirecional: receber dados do servidor (force=false para respeitar salvaguardas)
  // O flag isSyncingToHuggingFace ja foi limpo acima - o pull pode correr sem bloqueio
  let loadOk = false;
  try {
    loadOk = await loadDatabaseFromHuggingFace(true, false);
  } catch(eLoad) {}

  // 3. Notificacao de resultado — sempre visivel
  if (!silent) {
    const numCli = (db.clientes || []).length;
    const numCnt = (db.contactos || []).length;
    const numPrj = (db.projetos || []).length;
    if (pushOk || loadOk) {
      showToast('Sincronizacao bidirecional concluida com sucesso!', 'success');
      alert('Sincronizacao Concluida com Sucesso!\n\nDados sincronizados com o servidor:\n- ' + numCli + ' Clientes\n- ' + numCnt + ' Contactos\n- ' + numPrj + ' Projetos');
    } else {
      showToast('Sincronizacao concluida (armazenamento local).', 'info');
      alert('Sincronizacao Concluida!\n\nDados guardados no armazenamento local.\nVerifique a ligacao a Internet.');
    }
  }
  if (typeof renderHuggingFaceSettingsForm === 'function') renderHuggingFaceSettingsForm();
  return pushOk || loadOk;
}
window.handleFullServerSync = handleFullServerSync;

let isSyncingToHuggingFace = false;

async function syncDatabaseToHuggingFace(silent = false, force = false) {
  const cfg = getHuggingFaceConfig();
  const token = (cfg.token || DEFAULT_SYSTEM_HF_TOKEN).trim();
  const space = (cfg.space || DEFAULT_SYSTEM_HF_SPACE || "josecenturio/SIGEC-Pro").trim();
  let pathInSpace = (cfg.path || DEFAULT_SYSTEM_HF_PATH || "data/db.json").trim().replace(/^\/+/, '');

  if (isSyncingToHuggingFace && !force) {
    let waitCount = 0;
    while (isSyncingToHuggingFace && waitCount < 15) {
      await new Promise(r => setTimeout(r, 200));
      waitCount++;
    }
  }

  // BLINDAGEM CONTRA REGRESSÃO DE DADOS:
  // Nunca enviar à nuvem se a base local estiver incompleta (mínimo 50 clientes e 3 utilizadores)
  const numClientes = (typeof db !== 'undefined' && Array.isArray(db.clientes)) ? db.clientes.length : 0;
  const numUsuarios = (typeof db !== 'undefined' && Array.isArray(db.usuarios)) ? db.usuarios.length : 0;
  if (numClientes < 50 || numUsuarios < 3) {
    console.warn(`[SIGEC-Pro Sync Shield] Envio para Hugging Face bloqueado para proteção: base local incompleta (${numClientes} clientes, ${numUsuarios} utilizadores).`);
    return false;
  }

  isSyncingToHuggingFace = true;

  try {
    const dbPayload = {
      ...db,
      _spcfg: _encTk(token),
      _deletedRegistry: (typeof deletedRegistry !== 'undefined' ? deletedRegistry : null)
    };
    const dbString = JSON.stringify(dbPayload, null, 2);

    let pushSuccess = false;

    // PRIORIDADE 1: Gravação no Servidor Oficial OnRender (Web)
    try {
      const renderUrl = (typeof window !== 'undefined' && window.location && window.location.origin && window.location.protocol.startsWith('http'))
        ? `${window.location.origin}/api/save-db-json`
        : 'https://sigec-pro.onrender.com/api/save-db-json';
      const rRes = await fetch(renderUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: dbString
      }).catch(() => null);
      if (rRes && rRes.ok) {
        pushSuccess = true;
      }
    } catch(eRender) {}

    // PRIORIDADE 2: Commit direto via Web API Hugging Face (Redundância em Nuvem)
    if (token) {
      const contentBase64 = typeof utf8ToBase64 === 'function' ? utf8ToBase64(dbString) : btoa(unescape(encodeURIComponent(dbString)));
      
      // 1. Gravar no DATASET (https://huggingface.co/datasets/josecenturio/SIGEC-Pro/tree/main/Programa%20SIGEC-Pro/data/db.json)
      try {
        const datasetPayload = {
          summary: `[SIGEC-Pro] Sincronização de dados Dataset - ${new Date().toISOString()}`,
          files: [
            { path: 'Programa SIGEC-Pro/data/db.json', content: contentBase64, encoding: 'base64' },
            { path: 'data/db.json', content: contentBase64, encoding: 'base64' }
          ]
        };

        const resDataset = await fetch(`https://huggingface.co/api/datasets/${space}/commit/main`, {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(datasetPayload)
        }).catch(() => null);

        if (resDataset && (resDataset.ok || resDataset.status === 200 || resDataset.status === 201)) {
          pushSuccess = true;
        }
      } catch(eDs) {}

      // 2. Gravar no SPACE (https://huggingface.co/spaces/josecenturio/SIGEC-Pro/tree/main/data/db.json)
      try {
        const spacePayload = {
          summary: `[SIGEC-Pro] Sincronização de dados Space - ${new Date().toISOString()}`,
          files: [
            { path: 'data/db.json', content: contentBase64, encoding: 'base64' },
            { path: 'Programa SIGEC-Pro/data/db.json', content: contentBase64, encoding: 'base64' }
          ]
        };

        const resSpace = await fetch(`https://huggingface.co/api/spaces/${space}/commit/main`, {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(spacePayload)
        }).catch(() => null);

                // 3. Sincronizacao em tempo real no GITHUB (jjota26/SIGEC-Pro/data/db.json)
        try {
          await syncDatabaseToGitHub(dbString);
        } catch(eGh) {}

        if (resSpace && (resSpace.ok || resSpace.status === 200 || resSpace.status === 201)) {
          pushSuccess = true;
        }
      } catch(eSp) {}
    }

    if (pushSuccess) {
      console.info('[SIGEC-Pro] Sincronização com Hugging Face (Dataset e Space) concluída com sucesso!');
      if (!silent) {
        showToast('Base de dados sincronizada com o Servidor Hugging Face!', 'success');
      }
      isSyncingToHuggingFace = false;
      return true;
    } else {
      if (!silent) {
        alert('Não foi possível sincronizar com o Servidor Hugging Face. Verifique a ligação à internet.');
      }
      isSyncingToHuggingFace = false;
      return false;
    }
  } catch (err) {
    console.error('[SIGEC-Pro] Erro ao sincronizar com o Hugging Face:', err);
    if (!silent) alert('Erro de ligação ao Servidor Hugging Face: ' + err.message);
    isSyncingToHuggingFace = false;
    return false;
  }
}
window.syncDatabaseToHuggingFace = syncDatabaseToHuggingFace;
window.syncDatabaseToHuggingFace = syncDatabaseToHuggingFace;

function mergeCloudDatabaseSafely(cloudData) {
  if (!cloudData || typeof cloudData !== 'object') return false;
  
  if (typeof loadDeletedRegistry === 'function') {
    loadDeletedRegistry();
  }

  // 1. Sincronização e integração bidirecional do Registo de Eliminados da Nuvem
  if (cloudData._deletedRegistry && typeof cloudData._deletedRegistry === 'object') {
    let anyDeletedMerged = false;
    Object.keys(cloudData._deletedRegistry).forEach(type => {
      const cloudList = cloudData._deletedRegistry[type];
      if (Array.isArray(cloudList) && cloudList.length > 0) {
        if (!deletedRegistry[type]) deletedRegistry[type] = [];
        cloudList.forEach(delId => {
          if (delId) {
            // Se for objeto, extrair id ou ignorar
            const rawId = (typeof delId === 'object' && delId !== null) ? (delId.id || delId.email || '') : String(delId);
            const strId = String(rawId).trim();
            const lower = strId.toLowerCase();
            if (!strId) return;

            // REGRA ABSOLUTA: utilizadores legítimos existentes NUNCA podem ser marcados como eliminados
            if (type === 'usuarios') {
              const inCloudUsers = Array.isArray(cloudData.usuarios) && cloudData.usuarios.some(u => u && (u.id === strId || (u.email && u.email.toLowerCase() === lower)));
              const inLocalUsers = Array.isArray(db.usuarios) && db.usuarios.some(u => u && (u.id === strId || (u.email && u.email.toLowerCase() === lower)));
              if (inCloudUsers || inLocalUsers || strId === 'usr-admin-001' || lower === 'jmcenturio@alegria-activity.com' || strId === 'usr-1789862031944' || lower === 'jjota26@gmail.com' || strId === 'usr-1789972905110' || lower === 'victoria@alegria-activity.com') {
                return;
              }
            }

            if (!deletedRegistry[type].some(x => String(x).trim().toLowerCase() === lower)) {
              deletedRegistry[type].push(strId);
              anyDeletedMerged = true;
            }
          }
        });
      }
    });
    if (anyDeletedMerged && typeof saveDeletedRegistry === 'function') {
      saveDeletedRegistry();
    }
  }

  let hasLocalNewerChanges = false;
  let hasRemoteChangesApplied = false;

  const mergeEntityArray = (localArrayName, idProp = 'id') => {
    if (!Array.isArray(cloudData[localArrayName])) return;
    if (!Array.isArray(db[localArrayName])) db[localArrayName] = [];

    let localArr = db[localArrayName];
    const cloudArr = cloudData[localArrayName];

    // A. Purga imediata de qualquer item local que conste no registo de eliminados
    const preCount = localArr.length;
    localArr = localArr.filter(item => {
      if (!item) return false;
      const id = item[idProp] ? String(item[idProp]).trim() : null;
      if (localArrayName === 'usuarios') {
        if (item.id === 'usr-admin-001' || item.role === 'admin') return true;
        // Preservar sempre qualquer utilizador que venha na lista da nuvem
        if (cloudArr.some(c => c && (c.id === item.id || (c.email && item.email && c.email.toLowerCase().trim() === item.email.toLowerCase().trim())))) {
          return true;
        }
      }
      if (id && typeof isDeletedId === 'function' && isDeletedId(localArrayName, id)) {
        return false;
      }
      return true;
    });
    if (localArr.length !== preCount) {
      db[localArrayName] = localArr;
      hasRemoteChangesApplied = true;
    }

    const localMap = new Map();
    localArr.forEach((item, index) => {
      if (item && item[idProp]) {
        localMap.set(String(item[idProp]).trim(), { item, index });
      }
    });

    // B. Inserção e atualização dos itens vindos da nuvem
    cloudArr.forEach(cloudItem => {
      if (!cloudItem || !cloudItem[idProp]) return;
      const id = String(cloudItem[idProp]).trim();

      // Se foi apagado (localmente ou na nuvem), ignorar
      if (localArrayName !== 'usuarios' && typeof isDeletedId === 'function' && isDeletedId(localArrayName, id)) return;
      if (localArrayName === 'contactos' && (id.startsWith('con-1789667264257') || id.startsWith('con-1789667264258'))) return;

      if (!localMap.has(id)) {
        // Novo item vindo da nuvem
        localArr.push(cloudItem);
        hasRemoteChangesApplied = true;
        if (localArrayName === 'usuarios' && typeof removeDeletedId === 'function') {
          removeDeletedId('usuarios', id);
          if (cloudItem.email) removeDeletedId('usuarios', cloudItem.email);
        }
      } else {
        const { item: localItem, index } = localMap.get(id);
        const localTs = new Date(localItem.updatedAt || localItem.createdAt || 0).getTime();
        const cloudTs = new Date(cloudItem.updatedAt || cloudItem.createdAt || 0).getTime();

        // Regra especial e prioritária para Utilizadores: prevalência temporal estrita e blindagem contra reversão
        if (localArrayName === 'usuarios') {
          // Se a versão local é mais recente que a versão da nuvem, a versão local PREVALECE ABSOLUTAMENTE!
          if (localTs > cloudTs) {
            hasLocalNewerChanges = true;
            return;
          }

          // Apenas se a versão da nuvem for estritamente mais recente que a versão local
          if (cloudTs > localTs) {
            localArr[index] = { ...localItem, ...cloudItem };
            hasRemoteChangesApplied = true;

            // EFEITO IMEDIATO PARA O UTILIZADOR COM SESSÃO ATIVA NESTE COMPUTADOR
            const currentActiveUserId = typeof sessionStorage !== 'undefined' ? sessionStorage.getItem('sigec_pro_active_user_id') : null;
            if (currentActiveUserId && currentActiveUserId === cloudItem.id) {
              // 1. Se a conta foi desativada pelo Administrador, terminar sessão imediatamente
              if (cloudItem.active === false && cloudItem.role !== 'admin') {
                alert('⚠️ A sua conta de utilizador foi desativada pelo Administrador do Sistema.\nA sua sessão foi terminada.');
                sessionStorage.removeItem('sigec_pro_authenticated');
                sessionStorage.removeItem('sigec_pro_active_user_id');
                window.location.reload();
                return;
              }

              // 2. Se o idioma foi alterado, aplicar de imediato
              if (cloudItem.idioma && typeof applyUserLanguage === 'function') {
                applyUserLanguage(cloudItem.idioma);
              }

              // 3. Atualizar emblema de utilizador, cargo e permissões
              if (typeof updateHeaderActiveUserBadge === 'function') {
                updateHeaderActiveUserBadge();
              }
              if (typeof applyUserPermissions === 'function') {
                applyUserPermissions();
              }
            }
            return;
          }

          // Se os timestamps são iguais, preservar a versão local sem alterações
          return;
        }

        if (cloudTs > localTs) {
          // Versão da nuvem é mais recente
          localArr[index] = { ...localItem, ...cloudItem };
          hasRemoteChangesApplied = true;
        } else if (localTs > cloudTs) {
          // Versão local é mais recente: marcar para envio à nuvem
          hasLocalNewerChanges = true;
        }
      }
    });

    // C. Purgar itens locais que foram removidos na nuvem com blindagem absoluta
    const now = Date.now();
    const finalClean = localArr.filter(localItem => {
      if (!localItem || !localItem[idProp]) return false;
      const id = String(localItem[idProp]).trim();
      const inCloud = cloudArr.some(c => c && String(c[idProp]).trim() === id);
      if (inCloud) return true;

      // REGRA DE OURO DA PRESERVAÇÃO ABSOLUTA DE DADOS:
      // Um item local NUNCA é purgado automaticamente por mera ausência na nuvem!
      // Só é descartado se constar explicitamente no registo de eliminados (ação humana deliberada).
      if (typeof isDeletedId === 'function' && isDeletedId(localArrayName, id)) {
        return false;
      }

      // Se não consta na nuvem e não foi apagado pelo utilizador, é um registo local legítimo: preservar e marcar para envio
      hasLocalNewerChanges = true;
      return true;
    });

    db[localArrayName] = finalClean;
  };

  mergeEntityArray('clientes');
  mergeEntityArray('contactos');
  mergeEntityArray('projetos');
  mergeEntityArray('orcamentos');
  mergeEntityArray('interacoes');
  mergeEntityArray('interacoesProjetos');
  
  if (Array.isArray(cloudData.usuarios) && cloudData.usuarios.length > 0) {
    mergeEntityArray('usuarios');
  }

  // Sincronização e propagação automática de configurações centrais (SMTP, alertas, app password)
  if (cloudData.config && typeof cloudData.config === 'object') {
    db.config = db.config || {};
    let configUpdated = false;
    if (cloudData.config.smtpPass && cloudData.config.smtpPass !== db.config.smtpPass) {
      db.config.smtpPass = cloudData.config.smtpPass;
      localStorage.setItem('sigec_pro_smtp_pass', cloudData.config.smtpPass);
      configUpdated = true;
    }
    if (cloudData.config.emailNotifyAddress && cloudData.config.emailNotifyAddress !== db.config.emailNotifyAddress) {
      db.config.emailNotifyAddress = cloudData.config.emailNotifyAddress;
      localStorage.setItem('sigec_pro_admin_notify_email', cloudData.config.emailNotifyAddress);
      configUpdated = true;
    }
    if (cloudData.config.smtpHost && cloudData.config.smtpHost !== db.config.smtpHost) {
      db.config.smtpHost = cloudData.config.smtpHost;
      localStorage.setItem('sigec_pro_smtp_host', cloudData.config.smtpHost);
      configUpdated = true;
    }
    if (cloudData.config.smtpPort && cloudData.config.smtpPort !== db.config.smtpPort) {
      db.config.smtpPort = cloudData.config.smtpPort;
      localStorage.setItem('sigec_pro_smtp_port', cloudData.config.smtpPort);
      configUpdated = true;
    }
    if (cloudData.config.smtpUser && cloudData.config.smtpUser !== db.config.smtpUser) {
      db.config.smtpUser = cloudData.config.smtpUser;
      localStorage.setItem('sigec_pro_smtp_user', cloudData.config.smtpUser);
      configUpdated = true;
    }
    if (configUpdated) {
      hasRemoteChangesApplied = true;
      if (typeof renderEmailNotifySettingsUI === 'function') {
        renderEmailNotifySettingsUI();
      }
    }
  }

  // Sincronização bidirecional do Registo de Duplicados Decididos / Ignorados
  if (Array.isArray(cloudData.ignoredDuplicates)) {
    if (!Array.isArray(db.ignoredDuplicates)) db.ignoredDuplicates = [];
    const localIgnoredSet = new Set(db.ignoredDuplicates);
    let anyDupMerged = false;

    cloudData.ignoredDuplicates.forEach(pairKey => {
      if (pairKey && !localIgnoredSet.has(pairKey)) {
        db.ignoredDuplicates.push(pairKey);
        localIgnoredSet.add(pairKey);
        anyDupMerged = true;
      }
    });

    try {
      const stored = localStorage.getItem('sigec_pro_dup_ignored');
      if (stored) {
        const arr = JSON.parse(stored);
        if (Array.isArray(arr)) {
          arr.forEach(pairKey => {
            if (pairKey && !localIgnoredSet.has(pairKey)) {
              db.ignoredDuplicates.push(pairKey);
              localIgnoredSet.add(pairKey);
              anyDupMerged = true;
            }
          });
        }
      }
      localStorage.setItem('sigec_pro_dup_ignored', JSON.stringify(db.ignoredDuplicates));
    } catch (e) {}

    if (anyDupMerged) {
      hasRemoteChangesApplied = true;
    }
  } else if (Array.isArray(db.ignoredDuplicates) && db.ignoredDuplicates.length > 0) {
    hasLocalNewerChanges = true;
  }

  // Se foram aplicadas alterações remotas, persistir no armazenamento local e re-renderizar a interface
  if (hasRemoteChangesApplied) {
    if (typeof sanitizeAllDatabaseEntities === 'function') {
      sanitizeAllDatabaseEntities();
    }
    if (typeof saveDatabaseLocalOnly === 'function') {
      saveDatabaseLocalOnly();
    }
    if (typeof refreshActivePanel === 'function') {
      refreshActivePanel();
    }
    try {
      if (typeof renderClientPageMainGrid === 'function') renderClientPageMainGrid();
      if (typeof renderContactPageMainGrid === 'function') renderContactPageMainGrid();
      if (typeof renderProjectPageMainGrid === 'function') renderProjectPageMainGrid();
      if (typeof renderHomeDashboard === 'function') renderHomeDashboard();
      if (typeof renderDatabaseOverview === 'function') renderDatabaseOverview();
      if (typeof renderUserManagementGrid === 'function') renderUserManagementGrid();
      if (typeof renderUserSelectOptions === 'function') renderUserSelectOptions();
      if (typeof updateHeaderActiveUserBadge === 'function') updateHeaderActiveUserBadge();
      if (typeof scanAllDuplicates === 'function') setTimeout(() => { try { scanAllDuplicates(); } catch(e){} }, 0);
      if (typeof updateBadgeCounters === 'function') updateBadgeCounters();
    } catch(uiSyncErr) {}
  }

  // Se o cliente local tem alterações mais recentes que a nuvem, sincronizar para a nuvem
  // Nota: sync automatico removido do merge para evitar ciclos

  return true;
}
window.mergeCloudDatabaseSafely = mergeCloudDatabaseSafely;

async function loadDatabaseFromHuggingFace(silent = false, force = false) {
  const _LOCAL_SAVE_GUARD_MS = 5000; // 5 segundos de salvaguarda com merge estrito por prevalência temporal
  if (!force && silent && window._lastLocalSaveTimestamp && (Date.now() - window._lastLocalSaveTimestamp) < _LOCAL_SAVE_GUARD_MS) {
    return false;
  }
  if (isSyncingToHuggingFace && !force) {
    return false;
  }

  const cfg = getHuggingFaceConfig();
  const token = (cfg.token || DEFAULT_SYSTEM_HF_TOKEN || "").trim();
  const space = (cfg.space || DEFAULT_SYSTEM_HF_SPACE || "josecenturio/SIGEC-Pro").trim();

  try {
    let rawText = null;

    // Prioridade de leitura: Servidor OnRender -> Space Estático público (CORS livre) -> Raw Space -> Raw Dataset
    const dbEndpoints = [
      `/data/db.json?_t=${Date.now()}_${Math.random()}`,
      `https://sigec-pro.onrender.com/data/db.json?_t=${Date.now()}_${Math.random()}`,
      `https://josecenturio-sigec-pro.static.hf.space/data/db.json?_t=${Date.now()}_${Math.random()}`,
      `https://huggingface.co/spaces/${space}/raw/main/data/db.json?_t=${Date.now()}_${Math.random()}`,
      `https://huggingface.co/spaces/${space}/raw/main/Programa%20SIGEC-Pro/data/db.json?_t=${Date.now()}_${Math.random()}`,
      `https://huggingface.co/datasets/${space}/raw/main/Programa%20SIGEC-Pro/data/db.json?_t=${Date.now()}_${Math.random()}`
    ];

    const headers = { 'Cache-Control': 'no-cache, no-store' };
    if (token) headers['Authorization'] = `Bearer ${token}`;

    for (const ep of dbEndpoints) {
      try {
        const res = await fetch(ep, { headers: headers, cache: 'no-store' }).catch(() => null);
        if (res && res.ok) {
          const text = await res.text();
          if (text && text.trim().startsWith('{') && (text.includes('clientes') || text.includes('contactos') || text.includes('usuarios'))) {
            rawText = text;
            break;
          }
        }
      } catch (eEp) {}
    }

    if (!rawText) return false;

    const cloudData = JSON.parse(rawText);
    if (!cloudData || typeof cloudData !== 'object') return false;

    // Harmonizar e mesclar dados com segurança absoluta à prova de perdas
    mergeCloudDatabaseSafely(cloudData);

    updateCloudSyncStatusBadge(true);
    if (typeof refreshActivePanel === 'function') {
      refreshActivePanel();
    }
    return true;
  } catch(err) {
    console.warn('[SIGEC-Pro] Aviso no loadDatabaseFromHuggingFace:', err);
    return false;
  }
}
window.loadDatabaseFromHuggingFace = loadDatabaseFromHuggingFace;

async function syncRegisteredUsersFromHuggingFace(silent = false) {
  ensureUsersInitialized();
  loadDeletedRegistry();

  const syncButtons = document.querySelectorAll('button[onclick*="syncRegisteredUsers"]');
  syncButtons.forEach(btn => {
    btn.disabled = true;
    btn.dataset.origHtml = btn.innerHTML;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> <span>A sincronizar...</span>';
  });

  try {
    if (!silent) {
      showToast('A sincronizar registos com o Servidor Hugging Face...', 'info');
    }

    const success = await loadDatabaseFromHuggingFace(true, true);

    // Envio assíncrono em segundo plano para não bloquear a interface
    syncDatabaseToHuggingFace(true, true).catch(() => {});

    syncButtons.forEach(btn => {
      btn.disabled = false;
      if (btn.dataset.origHtml) btn.innerHTML = btn.dataset.origHtml;
    });

    if (typeof renderUserManagementGrid === 'function') renderUserManagementGrid();
    if (typeof renderUserSelectOptions === 'function') renderUserSelectOptions();
    if (typeof checkPendingNewUsersNotification === 'function') checkPendingNewUsersNotification();
    if (typeof updateCloudSyncStatusBadge === 'function') updateCloudSyncStatusBadge(true);

    const userCount = (db.usuarios || []).length;
    const clientCount = (db.clientes || []).length;
    const contactCount = (db.contactos || []).length;
    const projectCount = (db.projetos || []).length;

    if (!silent) {
      showToast('Registos sincronizados com o Servidor Hugging Face!', 'success');
      alert(`✅ Sincronização Concluída com Sucesso!\n\nDados Atualizados e Harmonizados com o Servidor:\n- ${clientCount} Clientes\n- ${contactCount} Contactos\n- ${projectCount} Projetos\n- ${userCount} Utilizador(es) Registado(s)`);
    }
    return true;
  } catch (e) {
    syncButtons.forEach(btn => {
      btn.disabled = false;
      if (btn.dataset.origHtml) btn.innerHTML = btn.dataset.origHtml;
    });
    console.error('Erro no syncRegisteredUsersFromHuggingFace:', e);
    if (!silent) {
      showToast('Registos sincronizados com a base de dados local.', 'success');
      alert(`✅ Sincronização Concluída!\n\nRegistos atualizados a partir do armazenamento local.`);
    }
    return true;
  }
}
window.syncRegisteredUsersFromHuggingFace = syncRegisteredUsersFromHuggingFace;

window.syncRegisteredUsersFromHuggingFace = syncRegisteredUsersFromHuggingFace;

