// Função que detecta o painel ativo e re-renderiza apenas esse painel após sincronização cloud
function refreshActivePanel() {
  try {
    // Detetar secção ativa pelo atributo data-section ou pelo elemento visível
    var activeSec = null;
    var secEls = document.querySelectorAll('[data-section]');
    secEls.forEach(function(el) {
      if (el && el.style && el.style.display !== 'none' && !el.hidden) {
        activeSec = el.getAttribute('data-section');
      }
    });
    // Fallback: verificar nav-links ativos
    if (!activeSec) {
      var activeNav = document.querySelector('.nav-link.active, .sidebar-link.active, [data-nav].active');
      if (activeNav) activeSec = activeNav.getAttribute('data-section') || activeNav.getAttribute('data-nav') || activeNav.getAttribute('href');
    }

    // Renderizar o painel correto
    if (activeSec) {
      var s = (activeSec || '').toLowerCase().replace('#','');
      if ((s.indexOf('client') !== -1) && typeof renderClientPageMainGrid === 'function') {
        renderClientPageMainGrid();
      } else if ((s.indexOf('contact') !== -1) && typeof renderContactPageMainGrid === 'function') {
        renderContactPageMainGrid();
      } else if ((s.indexOf('proj') !== -1) && typeof renderProjectPageMainGrid === 'function') {
        renderProjectPageMainGrid();
      } else if ((s.indexOf('orcam') !== -1 || s.indexOf('budget') !== -1) && typeof renderOrcamentosGrid === 'function') {
        renderOrcamentosGrid();
      } else if ((s.indexOf('user') !== -1 || s.indexOf('utiliz') !== -1) && typeof renderUserManagementGrid === 'function') {
        renderUserManagementGrid();
      }
    } else {
      // Se não conseguiu detetar, renderizar todos os painéis que existam
      if (typeof renderClientPageMainGrid === 'function') renderClientPageMainGrid();
      if (typeof renderContactPageMainGrid === 'function') renderContactPageMainGrid();
      if (typeof renderProjectPageMainGrid === 'function') renderProjectPageMainGrid();
    }
  } catch(eRefresh) {
    console.warn('[SIGEC-Pro] refreshActivePanel erro:', eRefresh);
  }
}
window.refreshActivePanel = refreshActivePanel;


