let clientInteractionsSortOrder = 'desc';
function toggleClientInteractionsSort() {
  clientInteractionsSortOrder = (clientInteractionsSortOrder === 'desc' ? 'asc' : 'desc');
  const textEl = document.getElementById('textSortClientInteractions');
  const iconEl = document.getElementById('iconSortClientInteractions');
  if (textEl) textEl.textContent = (clientInteractionsSortOrder === 'desc' ? 'Mais recente' : 'Mais antigo');
  if (iconEl) iconEl.className = (clientInteractionsSortOrder === 'desc' ? 'fa-solid fa-arrow-down-wide-short' : 'fa-solid fa-arrow-up-wide-short');
  if (currentClientId && typeof refreshClientSubLists === 'function') {
    refreshClientSubLists(currentClientId);
  }
}
window.toggleClientInteractionsSort = toggleClientInteractionsSort;

let contactPersonInteractionsSortOrder = 'desc';
function toggleContactPersonInteractionsSort() {
  contactPersonInteractionsSortOrder = (contactPersonInteractionsSortOrder === 'desc' ? 'asc' : 'desc');
  const textEl = document.getElementById('textSortContactInteractions');
  const iconEl = document.getElementById('iconSortContactInteractions');
  if (textEl) textEl.textContent = (contactPersonInteractionsSortOrder === 'desc' ? 'Mais recente' : 'Mais antigo');
  if (iconEl) iconEl.className = (contactPersonInteractionsSortOrder === 'desc' ? 'fa-solid fa-arrow-down-wide-short' : 'fa-solid fa-arrow-up-wide-short');
  
  const targetContactId = (typeof currentContactIdForModal !== 'undefined' && currentContactIdForModal) 
    ? currentContactIdForModal 
    : document.getElementById('contactId')?.value;
  if (targetContactId) {
    const targetCIdStr = String(targetContactId).trim();
    const inters = (db.interacoes || []).filter(i => i && String(i.contactoId || '').trim() === targetCIdStr);
    renderContactPersonInteractionsGrid(inters);
  }
}
window.toggleContactPersonInteractionsSort = toggleContactPersonInteractionsSort;

function getInteractionContactPersonName(item) {
  if (!item) return '';

  const activeDb = (typeof db !== 'undefined' && db && typeof db === 'object') ? db : ((typeof window !== 'undefined' && window.db && typeof window.db === 'object') ? window.db : {});

  // 1. Prioridade direta: Contacto associado via contactoId / contactId
  const cId = item.contactoId || item.contactId || item.contacto_id;
  if (cId && Array.isArray(activeDb.contactos)) {
    const con = activeDb.contactos.find(c => c && String(c.id).trim() === String(cId).trim());
    if (con) {
      const nome = (con.nome || '').trim();
      const apelido = (con.apelido || '').trim();
      const fullName = [nome, apelido].filter(Boolean).join(' ');
      if (fullName) {
        return (typeof sanitizeUtf8String === 'function') ? sanitizeUtf8String(fullName) : fullName;
      }
    }
  }

  // 2. Se o próprio objeto já possui o nome do contacto guardado
  if (item.contactoNome && typeof item.contactoNome === 'string' && item.contactoNome.trim()) {
    return (typeof sanitizeUtf8String === 'function') ? sanitizeUtf8String(item.contactoNome.trim()) : item.contactoNome.trim();
  }
  if (item.contactName && typeof item.contactName === 'string' && item.contactName.trim()) {
    return (typeof sanitizeUtf8String === 'function') ? sanitizeUtf8String(item.contactName.trim()) : item.contactName.trim();
  }
  if (item.interlocutor && typeof item.interlocutor === 'string' && item.interlocutor.trim()) {
    return (typeof sanitizeUtf8String === 'function') ? sanitizeUtf8String(item.interlocutor.trim()) : item.interlocutor.trim();
  }

  // 3. Se estiver no modal/contexto de um contacto específico aberto
  const curCId = (typeof currentContactIdForModal !== 'undefined' && currentContactIdForModal) 
    ? currentContactIdForModal 
    : (typeof document !== 'undefined' && document.getElementById('contactId')?.value);
  if (curCId && Array.isArray(activeDb.contactos)) {
    const con = activeDb.contactos.find(c => c && String(c.id).trim() === String(curCId).trim());
    if (con) {
      const nome = (con.nome || '').trim();
      const apelido = (con.apelido || '').trim();
      const fullName = [nome, apelido].filter(Boolean).join(' ');
      if (fullName) {
        return (typeof sanitizeUtf8String === 'function') ? sanitizeUtf8String(fullName) : fullName;
      }
    }
  }

  // O nome do Usuário/operador NÃO deve aparecer nos registos.
  // Sempre que o registo seja feito na página do cliente ou sem contacto associado, não aparece nada sob a data.
  return '';
}
window.getInteractionContactPersonName = getInteractionContactPersonName;
window.getInteractionAuthorName = getInteractionContactPersonName;

function renderContactPersonInteractionsGrid(interactions) {
  const grid = document.getElementById('contactPersonInteractionsGrid');
  if (!grid) return;
  grid.innerHTML = '';

  const quickDateInput = document.getElementById('quickContactInteractionData');
  if (quickDateInput && !quickDateInput.value) {
    const now = new Date();
    now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
    quickDateInput.value = now.toISOString().slice(0, 16);
  }

  if (!interactions || interactions.length === 0) {
    grid.innerHTML = '<span class="empty-state">Nenhum contacto/interação registada com este contacto.</span>';
    return;
  }

  const isAsc = (typeof contactPersonInteractionsSortOrder !== 'undefined' && contactPersonInteractionsSortOrder === 'asc');
  const sorted = [...interactions].sort((a, b) => isAsc ? (new Date(a.data || 0) - new Date(b.data || 0)) : (new Date(b.data || 0) - new Date(a.data || 0)));

  sorted.forEach(item => {
    const formattedDate = item.data ? new Date(item.data).toLocaleString('pt-PT', { dateStyle: 'short', timeStyle: 'short' }) : '-';
    const contactName = getInteractionContactPersonName(item);
    const authorHtml = contactName 
      ? `<span class="interaction-author-name" title="${escapeHtml(contactName)}"><i class="fa-solid fa-user"></i> ${escapeHtml(contactName)}</span>` 
      : '';

    const card = document.createElement('div');
    card.className = 'interaction-card';
    card.innerHTML = `
      <div class="contact-card-actions">
        <button type="button" class="action-icon-btn" onclick="openContactPersonInteractionModalForEdit('${item.id}')" title="Editar Registo">
          <i class="fa-solid fa-pen-to-square"></i>
        </button>
        <button type="button" class="action-icon-btn danger" onclick="deleteContactPersonInteractionInline('${item.id}')" title="Apagar Registo">
          <i class="fa-solid fa-trash"></i>
        </button>
      </div>
      <div class="interaction-card-row">
        <div class="interaction-card-date">
          <span class="interaction-date-text"><i class="fa-regular fa-calendar-days"></i> ${formattedDate}</span>
          ${authorHtml}
        </div>
        <div class="interaction-card-content">${escapeHtml(item.descricao || '')}</div>
      </div>
    `;
    grid.appendChild(card);
  });
}
window.renderContactPersonInteractionsGrid = renderContactPersonInteractionsGrid;

function addQuickContactInteraction() {
  const targetContactId = (typeof currentContactIdForModal !== 'undefined' && currentContactIdForModal) 
    ? currentContactIdForModal 
    : document.getElementById('contactId')?.value;

  if (!targetContactId) {
    showToast('Guarde ou selecione um Contacto primeiro!', 'danger');
    return;
  }

  const dateVal = document.getElementById('quickContactInteractionData')?.value;
  const textEl = document.getElementById('quickContactInteractionText');
  const textVal = textEl ? textEl.value.trim() : '';

  if (!textVal) {
    showToast('Escreva o texto do contacto efetuado.', 'danger');
    return;
  }

  const id = generateId('cpi');
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  const finalDate = dateVal || now.toISOString().slice(0, 16);

  if (!db.interacoes) db.interacoes = [];

  const targetCIdStr = String(targetContactId).trim();
  const contact = (db.contactos || []).find(c => c && String(c.id).trim() === targetCIdStr);
  const contactFullName = contact ? [contact.nome, contact.apelido].filter(Boolean).join(' ') : '';
  const clienteId = contact ? contact.clienteId : currentClientId;
  const clientObj = clienteId ? (db.clientes || []).find(c => c && String(c.id).trim() === String(clienteId).trim()) : null;
  const subTabIndex = (contact && contact.subTabIndex !== undefined && contact.subTabIndex !== null) ? Number(contact.subTabIndex) : null;
  const separadorId = (contact && contact.separadorId) ? contact.separadorId : ((clientObj && Array.isArray(clientObj.separadores) && subTabIndex !== null && clientObj.separadores[subTabIndex]) ? clientObj.separadores[subTabIndex].id : null);

  const activeUser = typeof getActiveLoggedInUser === 'function' ? getActiveLoggedInUser() : null;
  const authorId = activeUser ? activeUser.id : (contact?.comercialAtribuidoId || contact?.userId || clientObj?.comercialAtribuidoId || clientObj?.userId || 'usr-admin-001');
  const authorName = activeUser ? activeUser.nome : (contact?.comercialAtribuidoNome || clientObj?.comercialAtribuidoNome || 'José Centúrio');

  const intObj = {
    id,
    contactoId: targetCIdStr,
    contactoNome: contactFullName,
    clienteId: clienteId || null,
    separadorId: separadorId || null,
    subTabIndex: subTabIndex,
    data: finalDate,
    descricao: textVal,
    userId: authorId,
    userName: authorName,
    createdAt: new Date().toISOString()
  };

  db.interacoes.push(intObj);
  saveDatabase();

  if (textEl) {
    textEl.value = '';
    textEl.style.height = 'auto';
  }

  const inters = (db.interacoes || []).filter(i => i && String(i.contactoId || '').trim() === targetCIdStr);
  renderContactPersonInteractionsGrid(inters);
  if (typeof renderContactPageMainGrid === 'function') renderContactPageMainGrid();
  if (typeof renderHomeDashboard === 'function') renderHomeDashboard();
  if (typeof renderConsultasUserData === 'function') renderConsultasUserData();
  if (clienteId && typeof refreshClientSubLists === 'function') refreshClientSubLists(clienteId);
  if (typeof syncDatabaseToHuggingFace === 'function') {
    syncDatabaseToHuggingFace(true, true).catch(() => {});
  }
  showToast('Registo de contacto adicionado com sucesso!');
}
window.addQuickContactInteraction = addQuickContactInteraction;

function deleteContactPersonInteractionInline(id) {
  if (confirm('Tem a certeza que deseja apagar este registo de contacto?')) {
    const cleanId = String(id).trim();
    addDeletedId('interacoes', cleanId);
    db.interacoes = (db.interacoes || []).filter(i => i && String(i.id).trim() !== cleanId);
    saveDatabase();
    
    const targetContactId = (typeof currentContactIdForModal !== 'undefined' && currentContactIdForModal) 
      ? currentContactIdForModal 
      : document.getElementById('contactId')?.value;
      
    if (targetContactId) {
      const targetCIdStr = String(targetContactId).trim();
      const inters = (db.interacoes || []).filter(i => i && String(i.contactoId || '').trim() === targetCIdStr);
      renderContactPersonInteractionsGrid(inters);
    }
    if (typeof renderContactPageMainGrid === 'function') renderContactPageMainGrid();
    if (typeof renderHomeDashboard === 'function') renderHomeDashboard();
    if (typeof renderConsultasUserData === 'function') renderConsultasUserData();
    if (typeof syncDatabaseToHuggingFace === 'function') {
      syncDatabaseToHuggingFace(true, true).catch(() => {});
    }
    showToast('Registo de contacto apagado.', 'danger');
  }
}
window.deleteContactPersonInteractionInline = deleteContactPersonInteractionInline;

let projectInteractionsSortOrder = 'desc';
