function openCurrentFileInNewTab() {
  if (!currentViewerFileContext || !currentViewerFileContext.item) {
    showToast('Nenhum ficheiro selecionado para abrir.', 'danger');
    return;
  }
  const item = currentViewerFileContext.item;
  const targetProjectId = (currentViewerFileContext.projectId) || currentProjectId;

  // Abrir no visualizador interno (modal do programa)
  const modal = document.getElementById('mediaViewerModal');
  const titleEl = document.getElementById('mediaViewerTitle');
  const container = document.getElementById('mediaViewerContainer');
  const info = document.getElementById('mediaViewerInfo');
  const btnDownload = document.getElementById('btnDownloadCurrentMedia');
  const btnDelete = document.getElementById('btnDeleteCurrentMedia');

  if (!modal || !container) {
    // Fallback: tentar descarregar
    triggerBrowserFileDownload(item.dataUrl, item.name, item.mimeType);
    return;
  }

  const ext = (item.name.split('.').pop() || '').toLowerCase();
  const mime = (item.mimeType || '').toLowerCase();
  const docMeta = getDocFileType(item.name, mime);
  const icon = docMeta.icon || 'fa-file';
  const color = docMeta.color || '#64748b';

  if (titleEl) {
    titleEl.innerHTML = `<i class="fa-solid ${icon}" style="color: ${color};"></i> ${escapeHtml(item.name)}`;
  }
  if (info) {
    const sizeKB = item.size ? `${(item.size / 1024).toFixed(1)} KB` : '';
    const dateStr = item.date ? new Date(item.date).toLocaleString('pt-PT') : '';
    info.textContent = [sizeKB, dateStr ? `Adicionado em: ${dateStr}` : ''].filter(Boolean).join(' | ');
  }

  if (btnDownload) {
    btnDownload.onclick = function () {
      triggerBrowserFileDownload(item.dataUrl, item.name, item.mimeType);
    };
  }
  if (btnDelete) {
    // Esconder botão de apagar quando aberto via "Abrir Ficheiro" (contexto de documento)
    btnDelete.style.display = currentViewerFileContext.isMedia ? 'inline-flex' : 'none';
  }

  renderFileContentInViewer(item, container, targetProjectId);
  modal.classList.add('active');
}
window.openCurrentFileInNewTab = openCurrentFileInNewTab;

function openMediaViewer(mediaId, optionalProjectId = null) {
  let item = null;
  const targetProjectId = optionalProjectId || currentProjectId;
  if (targetProjectId) {
    const project = (db.projetos || []).find(p => String(p.id) === String(targetProjectId));
    if (project && Array.isArray(project.media)) {
      item = project.media.find(m => String(m.id) === String(mediaId));
    }
  }
  if (!item) {
    for (const p of (db.projetos || [])) {
      if (Array.isArray(p.media)) {
        const found = p.media.find(m => String(m.id) === String(mediaId));
        if (found) { item = found; break; }
      }
    }
  }
  if (!item) return;

  currentViewerFileContext = { item, projectId: targetProjectId, isMedia: true };

  const modal = document.getElementById('mediaViewerModal');
  const title = document.getElementById('mediaViewerTitle');
  const container = document.getElementById('mediaViewerContainer');
  const info = document.getElementById('mediaViewerInfo');
  const btnDownload = document.getElementById('btnDownloadCurrentMedia');
  const btnDelete = document.getElementById('btnDeleteCurrentMedia');

  const isVideo = item.type === 'video' || (item.mimeType && item.mimeType.startsWith('video/'));
  if (title) title.innerHTML = `<i class="fa-solid ${isVideo ? 'fa-video' : 'fa-image'}" style="color: ${isVideo ? '#8b5cf6' : '#06b6d4'};"></i> ${escapeHtml(item.name)}`;
  if (info) info.textContent = `Tamanho: ${(item.size / 1024).toFixed(1)} KB | Adicionado em: ${new Date(item.date).toLocaleString('pt-PT')}`;

  if (btnDownload) {
    btnDownload.onclick = function() {
      downloadMediaItem(item.id, targetProjectId);
    };
  }

  if (btnDelete) {
    btnDelete.style.display = 'inline-flex';
    btnDelete.onclick = function() {
      deleteMediaItem(item.id, targetProjectId);
    };
  }

  if (container) {
    renderFileContentInViewer(item, container, targetProjectId);
  }

  if (modal) modal.classList.add('active');
}
window.openMediaViewer = openMediaViewer;

function closeMediaViewerModal() {
  const modal = document.getElementById('mediaViewerModal');
  const container = document.getElementById('mediaViewerContainer');
  if (container) container.innerHTML = '';
  currentViewerFileContext = null;
  if (modal) modal.classList.remove('active');
}
window.closeMediaViewerModal = closeMediaViewerModal;

function downloadMediaItem(mediaId, optionalProjectId = null) {
  let item = null;
  if (currentViewerFileContext && currentViewerFileContext.item && String(currentViewerFileContext.item.id) === String(mediaId)) {
    item = currentViewerFileContext.item;
  }
  const targetProjectId = optionalProjectId || currentProjectId;
  if (!item && targetProjectId) {
    const project = (db.projetos || []).find(p => String(p.id) === String(targetProjectId));
    if (project && Array.isArray(project.media)) {
      item = project.media.find(m => String(m.id) === String(mediaId));
    }
  }
  if (!item) {
    for (const p of (db.projetos || [])) {
      if (Array.isArray(p.media)) {
        const found = p.media.find(m => String(m.id) === String(mediaId));
        if (found) { item = found; break; }
      }
    }
  }
  if (!item && currentViewerFileContext && currentViewerFileContext.item) {
    item = currentViewerFileContext.item;
  }
  if (!item) {
    showToast('Ficheiro de média não encontrado para descarregar.', 'warning');
    return;
  }
  triggerBrowserFileDownload(item.dataUrl, item.name, item.mimeType);
}
window.downloadMediaItem = downloadMediaItem;

function deleteMediaItem(mediaId, optionalProjectId = null) {
  const targetProjectId = optionalProjectId || currentProjectId;
  if (!targetProjectId) return;
  const project = (db.projetos || []).find(p => String(p.id) === String(targetProjectId));
  if (!project || !Array.isArray(project.media)) return;

  const index = project.media.findIndex(m => String(m.id) === String(mediaId));
  if (index === -1) return;

  const mediaName = project.media[index].name;
  if (confirm(`Tem a certeza que deseja eliminar o ficheiro "${mediaName}"?`)) {
    project.media.splice(index, 1);
    saveDatabase();
    if (currentProjectId === targetProjectId) renderProjectMediaGrid(targetProjectId);
    closeMediaViewerModal();
    showToast(`Ficheiro "${mediaName}" eliminado da galeria.`, 'danger');
  }
}
window.deleteMediaItem = deleteMediaItem;

function exportProjectMediaZip() {
  if (!currentProjectId) {
    showToast('Selecione ou guarde um projeto primeiro!', 'danger');
    return;
  }
  const project = (db.projetos || []).find(p => String(p.id) === String(currentProjectId));
  if (!project || !Array.isArray(project.media) || project.media.length === 0) {
    showToast('Este projeto não possui fotos nem vídeos para exportar.', 'danger');
    return;
  }

  project.media.forEach(item => {
    downloadMediaItem(item.id);
  });
  showToast(`A descarregar ${project.media.length} ficheiro(s) do projeto...`);
}
window.exportProjectMediaZip = exportProjectMediaZip;

function openBudgetImgInViewer(imgKey) {
  const input = document.getElementById(imgKey);
  const dataUrl = input ? input.value : '';
  if (!dataUrl) {
    showToast('Nenhuma imagem carregada nesta secção.', 'info');
    return;
  }
  const labelMap = {
    budgetImg_logoCliente: '1. Logótipo do Cliente',
    budgetImg_ext1: '2. Foto Exterior 1 (Experiência)',
    budgetImg_ext2: '3. Foto Exterior 2 (Experiência)',
    budgetImg_veiculo: '4. Veículo Base / Chassi',
    budgetImg_acesso: '5. Acessibilidade & Toldo',
    budgetImg_planta: '6. Planta 2D / 3D Interior',
    budgetImg_mobiliario: '7. Mobiliário & Acabamentos',
    budgetImg_starlink1: '8. Sistema Starlink & Antenas',
    budgetImg_bateria: '9. Bateria de Lítio & Inversor',
    budgetImg_painel: '10. Painéis Solares & Energia',
    budgetImg_gerador: '11. Gerador Insonorizado / Clima',
    budgetImg_iso: '12. Certificação ISO 9001 / Bureau Veritas'
  };
  const label = labelMap[imgKey] || imgKey;
  const item = {
    id: imgKey,
    name: label,
    type: 'image',
    mimeType: 'image/png',
    dataUrl: dataUrl,
    size: Math.round(dataUrl.length * 0.75),
    date: new Date().toISOString()
  };
  currentViewerFileContext = { item, projectId: null, isMedia: true };

  const modal = document.getElementById('mediaViewerModal');
  const title = document.getElementById('mediaViewerTitle');
  const container = document.getElementById('mediaViewerContainer');
  const info = document.getElementById('mediaViewerInfo');
  const btnDownload = document.getElementById('btnDownloadCurrentMedia');
  const btnDelete = document.getElementById('btnDeleteCurrentMedia');

  if (title) title.innerHTML = `<i class="fa-solid fa-image" style="color: #06b6d4;"></i> ${escapeHtml(item.name)}`;
  if (info) info.textContent = `Tamanho aproximado: ${(item.size / 1024).toFixed(1)} KB`;

  if (btnDownload) {
    btnDownload.onclick = function() {
      triggerBrowserFileDownload(item.dataUrl, label.replace(/[^a-zA-Z0-9_-]/g, '_') + '.png', 'image/png');
    };
  }

  if (btnDelete) {
    btnDelete.style.display = 'inline-flex';
    btnDelete.onclick = function() {
      if (confirm(`Deseja remover a imagem de "${label}"?`)) {
        removeBudgetImg(imgKey);
        closeMediaViewerModal();
        showToast('Imagem removida com sucesso.');
      }
    };
  }

  if (container) {
    renderFileContentInViewer(item, container, null);
  }

  if (modal) modal.classList.add('active');
}
window.openBudgetImgInViewer = openBudgetImgInViewer;

