window.renderProjectDocsGrid = renderProjectDocsGrid;

function openDocViewer(docId, optionalProjectId = null) {
  let item = null;
  const targetProjectId = optionalProjectId || currentProjectId;
  if (targetProjectId) {
    const project = (db.projetos || []).find(p => String(p.id) === String(targetProjectId));
    if (project) {
      if (Array.isArray(project.orcamentos)) {
        item = project.orcamentos.find(d => String(d.id) === String(docId));
      }
      if (!item && Array.isArray(project.documents)) {
        item = project.documents.find(d => String(d.id) === String(docId));
      }
    }
  }
  if (!item) {
    for (const p of (db.projetos || [])) {
      if (Array.isArray(p.orcamentos)) {
        const found = p.orcamentos.find(d => String(d.id) === String(docId));
        if (found) { item = found; break; }
      }
      if (Array.isArray(p.documents)) {
        const found = p.documents.find(d => String(d.id) === String(docId));
        if (found) { item = found; break; }
      }
    }
  }
  if (!item) {
    for (const c of (db.clientes || [])) {
      if (Array.isArray(c.documents)) {
        const found = c.documents.find(d => String(d.id) === String(docId));
        if (found) { item = found; break; }
      }
    }
  }
  if (!item) return;

  currentViewerFileContext = { item, projectId: targetProjectId, isMedia: false };

  const modal = document.getElementById('mediaViewerModal');
  const title = document.getElementById('mediaViewerTitle');
  const container = document.getElementById('mediaViewerContainer');
  const info = document.getElementById('mediaViewerInfo');
  const btnDownload = document.getElementById('btnDownloadCurrentMedia');
  const btnDelete = document.getElementById('btnDeleteCurrentMedia');

  const docMeta = getDocFileType(item.name, item.mimeType || '');
  if (title) title.innerHTML = `<i class="fa-solid ${docMeta.icon}" style="color: ${docMeta.color};"></i> ${escapeHtml(item.name)}`;
  if (info) info.textContent = `Tamanho: ${(item.size / 1024).toFixed(1)} KB | Tipo: ${docMeta.label} | Adicionado em: ${new Date(item.date).toLocaleString('pt-PT')}`;

  if (btnDownload) {
    btnDownload.onclick = function() {
      downloadDocItem(item.id, targetProjectId);
    };
  }

  if (btnDelete) {
    btnDelete.style.display = 'inline-flex';
    btnDelete.onclick = function() {
      deleteDocItem(item.id, targetProjectId);
    };
  }

  if (container) {
    renderFileContentInViewer(item, container, targetProjectId);
  }

  if (modal) modal.classList.add('active');
}
window.openDocViewer = openDocViewer;

function downloadDocItem(docId, optionalProjectId = null) {
  let item = null;
  if (currentViewerFileContext && currentViewerFileContext.item && String(currentViewerFileContext.item.id) === String(docId)) {
    item = currentViewerFileContext.item;
  }
  const targetProjectId = optionalProjectId || currentProjectId;
  if (!item && targetProjectId) {
    const project = (db.projetos || []).find(p => String(p.id) === String(targetProjectId));
    if (project) {
      if (Array.isArray(project.orcamentos)) {
        item = project.orcamentos.find(d => String(d.id) === String(docId));
      }
      if (!item && Array.isArray(project.documents)) {
        item = project.documents.find(d => String(d.id) === String(docId));
      }
    }
  }
  if (!item) {
    for (const p of (db.projetos || [])) {
      if (Array.isArray(p.orcamentos)) {
        const found = p.orcamentos.find(d => String(d.id) === String(docId));
        if (found) { item = found; break; }
      }
      if (Array.isArray(p.documents)) {
        const found = p.documents.find(d => String(d.id) === String(docId));
        if (found) { item = found; break; }
      }
    }
  }
  if (!item) {
    for (const c of (db.clientes || [])) {
      if (Array.isArray(c.documents)) {
        const found = c.documents.find(d => String(d.id) === String(docId));
        if (found) { item = found; break; }
      }
    }
  }
  if (!item && currentViewerFileContext && currentViewerFileContext.item) {
    item = currentViewerFileContext.item;
  }

  if (!item) {
    showToast('Documento não encontrado para descarregar.', 'warning');
    return;
  }

  triggerBrowserFileDownload(item.dataUrl, item.name, item.mimeType);
}
window.downloadDocItem = downloadDocItem;

function deleteDocItem(docId, optionalProjectId = null) {
  const targetProjectId = optionalProjectId || currentProjectId;
  let targetProject = null;
  let targetIndex = -1;
  let targetArrayName = 'documents';

  if (targetProjectId) {
    const project = (db.projetos || []).find(p => String(p.id) === String(targetProjectId));
    if (project) {
      if (Array.isArray(project.orcamentos)) {
        const idx = project.orcamentos.findIndex(d => String(d.id) === String(docId));
        if (idx !== -1) {
          targetProject = project;
          targetIndex = idx;
          targetArrayName = 'orcamentos';
        }
      }
      if (targetIndex === -1 && Array.isArray(project.documents)) {
        const idx = project.documents.findIndex(d => String(d.id) === String(docId));
        if (idx !== -1) {
          targetProject = project;
          targetIndex = idx;
          targetArrayName = 'documents';
        }
      }
    }
  }

  if (!targetProject) {
    for (const p of (db.projetos || [])) {
      if (Array.isArray(p.orcamentos)) {
        const idx = p.orcamentos.findIndex(d => String(d.id) === String(docId));
        if (idx !== -1) {
          targetProject = p;
          targetIndex = idx;
          targetArrayName = 'orcamentos';
          break;
        }
      }
      if (Array.isArray(p.documents)) {
        const idx = p.documents.findIndex(d => String(d.id) === String(docId));
        if (idx !== -1) {
          targetProject = p;
          targetIndex = idx;
          targetArrayName = 'documents';
          break;
        }
      }
    }
  }

  if (!targetProject || targetIndex === -1) {
    showToast('Documento não encontrado para eliminação.', 'warning');
    return;
  }

  const docName = targetProject[targetArrayName][targetIndex].name;
  if (confirm(`Tem a certeza que deseja eliminar o documento "${docName}"?`)) {
    targetProject[targetArrayName].splice(targetIndex, 1);
    saveDatabase();
    if (currentProjectId) {
      renderProjectOrcamentosGrid(currentProjectId);
      renderProjectDocsGrid(currentProjectId);
    }
    if (currentClientId) refreshClientSubLists(currentClientId);
    closeMediaViewerModal();
    showToast(`Documento "${docName}" eliminado com sucesso.`, 'danger');
  }
}
window.deleteDocItem = deleteDocItem;

function exportProjectDocsAll() {
  if (!currentProjectId) {
    showToast('Selecione ou guarde um projeto primeiro!', 'danger');
    return;
  }
  const project = db.projetos.find(p => p.id === currentProjectId);
  if (!project || !project.documents || project.documents.length === 0) {
    showToast('Este projeto não possui documentos para exportar.', 'danger');
    return;
  }

  project.documents.forEach(item => {
    downloadDocItem(item.id);
  });
  showToast(`A descarregar ${project.documents.length} documento(s) do projeto...`);
}

