function triggerDatabaseImport() {
  const input = document.getElementById('fullDatabaseImportInput');
  if (input) input.click();
}

let activeImportCategory = null;

function triggerCategoryImport(category) {
  activeImportCategory = category;
  const input = document.getElementById('categoryImportInput');
  if (input) input.click();
}

