// ==========================================
// ==========================================
// ==========================================
// 21. GESTÃO DE VERSÕES E ATUALIZAÇÕES DO SISTEMA (SINCRONIZAÇÃO MULTI-COMPUTADOR INFALÍVEL)
// ==========================================

let pendingUpdateData = null;

function parseVersionNumbers(verStr) {
  if (!verStr || typeof verStr !== 'string') return [0, 0, 0];
  const cleaned = verStr.replace(/[^0-9.]/g, '');
  const parts = cleaned.split('.').map(n => parseInt(n, 10) || 0);
  while (parts.length < 3) parts.push(0);
  return parts;
}
window.parseVersionNumbers = parseVersionNumbers;

function isNewerVersion(remoteVer, currentVer) {
  const r = parseVersionNumbers(remoteVer);
  const c = parseVersionNumbers(currentVer);
  
  for (let i = 0; i < Math.max(r.length, c.length); i++) {
    const rVal = r[i] || 0;
    const cVal = c[i] || 0;
    if (rVal > cVal) return true;
    if (rVal < cVal) return false;
  }
  return false;
}
window.isNewerVersion = isNewerVersion;

function parseVersionNumber(versionStr) {
  if (!versionStr) return 0;
  const parts = parseVersionNumbers(versionStr);
  return parts[0] * 1000000 + parts[1] * 1000 + parts[2];
}
window.parseVersionNumber = parseVersionNumber;

function getNextSequentialVersion(lastVersionStr) {
  const match = String(lastVersionStr || '').match(/SIGEC_V?([0-9]+(?:\.[0-9]+)*)/i) || String(lastVersionStr || '').match(/([0-9]+(?:\.[0-9]+)*)/);
  if (!match) return 'SIGEC_V1.7.37';
  
  const parts = match[1].split('.').map(p => parseInt(p, 10) || 0);
  if (parts.length === 1) {
    parts[0] += 1;
  } else {
    parts[parts.length - 1] += 1;
  }
  return `SIGEC_V${parts.join('.')}`;
}
window.getNextSequentialVersion = getNextSequentialVersion;

function getInstalledVersion() {
  let ver = 'SIGEC_V1.7.37';
  
  if (typeof localStorage !== 'undefined') {
    const saved = localStorage.getItem('sigec_pro_installed_version');
    if (saved && typeof saved === 'string' && saved.trim() && parseVersionNumber(saved) >= parseVersionNumber('SIGEC_V1.7.37')) {
      ver = saved.trim();
    } else {
      try {
        localStorage.setItem('sigec_pro_installed_version', 'SIGEC_V1.7.37');
      } catch (e) {}
    }
  }
  
  if (typeof db !== 'undefined' && db && db.config && db.config.versaoSoftware) {
    const dbVer = db.config.versaoSoftware.trim();
    if (dbVer && typeof parseVersionNumber === 'function' && parseVersionNumber(dbVer) >= parseVersionNumber(ver)) {
      ver = dbVer;
    }
  }

  if (typeof window !== 'undefined' && Array.isArray(window.SIGEC_AVAILABLE_UPDATES) && window.SIGEC_AVAILABLE_UPDATES.length > 0) {
    const latestPkg = window.SIGEC_AVAILABLE_UPDATES[window.SIGEC_AVAILABLE_UPDATES.length - 1];
    const latestPkgVer = latestPkg ? (latestPkg.version || latestPkg.packageName) : null;
    if (latestPkgVer && typeof parseVersionNumber === 'function' && parseVersionNumber(latestPkgVer) >= parseVersionNumber(ver)) {
      ver = latestPkgVer;
    }
  }

  window.CURRENT_SYSTEM_VERSION = ver;
  CURRENT_SYSTEM_VERSION = ver;
  return ver;
}
window.getInstalledVersion = getInstalledVersion;

function updateInstalledVersionUI() {
  const fullVer = getInstalledVersion();
  const cleanVer = fullVer.replace(/^SIGEC_?/i, '');
  const displayVer = cleanVer.startsWith('V') ? cleanVer : `V${cleanVer}`;

  const targetBadges = [
    'installedVersionBadge',
    'cfgInstalledVersionBadge',
    'userSettingsInstalledVersionBadge',
    'appVersionPill',
    'headerAppVersionPill'
  ];

  targetBadges.forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.textContent = displayVer;
    }
  });

  if (typeof document !== 'undefined' && document.querySelectorAll) {
    document.querySelectorAll('.current-installed-version-badge').forEach(el => {
      el.textContent = displayVer;
    });
  }
}
window.updateInstalledVersionUI = updateInstalledVersionUI;

async function generateUpdatePackage() {
  showToast('As atualizações do SIGEC-Pro são sincronizadas automaticamente através da Nuvem (Render / PWA).', 'info');
}
window.generateUpdatePackage = generateUpdatePackage;

async function checkAndInstallUpdate(silentIfNoUpdate = false) {
  const currentVersion = getInstalledVersion();
  const displayVer = (currentVersion || "SIGEC_V1.7.24").replace(/_/g, ' ').replace(/^SIGEC /, 'SIGEC-Pro ');
  
  if (!silentIfNoUpdate) {
    showToast('A verificar atualizações no servidor Hugging Face...', 'info');
  }

  let registryLoaded = false;

  const loadRegistryViaScript = (srcUrl) => {
    return new Promise((resolve) => {
      try {
        const s = document.createElement('script');
        s.src = srcUrl;
        s.async = true;
        s.onload = () => {
          try { s.remove(); } catch(e){}
          resolve(true);
        };
        s.onerror = () => {
          try { s.remove(); } catch(e){}
          resolve(false);
        };
        document.head.appendChild(s);
        setTimeout(() => resolve(false), 6000);
      } catch(e) {
        resolve(false);
      }
    });
  };

  try {
    const cfg = typeof getHuggingFaceConfig === 'function' ? getHuggingFaceConfig() : {};
    const space = (cfg.space || DEFAULT_SYSTEM_HF_SPACE || "josecenturio/SIGEC-Pro").trim();
    const token = (cfg.token || DEFAULT_SYSTEM_HF_TOKEN || "").trim();

    // Prioridade 1: Pasta exata do Dataset Hugging Face solicitada pelo utilizador
    const scriptUrls = [
      `https://huggingface.co/datasets/${space}/raw/main/Programa%20SIGEC-Pro/Atualiza%C3%A7%C3%A3o/updates_registry.js?_t=${Date.now()}_${Math.random()}`,
      `https://huggingface.co/datasets/${space}/raw/main/Programa%20SIGEC-Pro/Atualizacao/updates_registry.js?_t=${Date.now()}_${Math.random()}`,
      `https://huggingface.co/spaces/${space}/raw/main/Atualizacao/updates_registry.js?_t=${Date.now()}_${Math.random()}`,
      `https://josecenturio-sigec-pro.static.hf.space/Atualizacao/updates_registry.js?_t=${Date.now()}_${Math.random()}`,
      `Atualizacao/updates_registry.js?_t=${Date.now()}`,
      `Atualização/updates_registry.js?_t=${Date.now()}`
    ];

    for (const url of scriptUrls) {
      const ok = await loadRegistryViaScript(url);
      if (ok && Array.isArray(window.SIGEC_AVAILABLE_UPDATES) && window.SIGEC_AVAILABLE_UPDATES.length > 0) {
        registryLoaded = true;
        break;
      }
    }

    if (!registryLoaded) {
      const fetchEndpoints = [
        `https://huggingface.co/datasets/${space}/raw/main/Programa%20SIGEC-Pro/Atualiza%C3%A7%C3%A3o/updates_registry.js?_t=${Date.now()}`,
        `https://huggingface.co/datasets/${space}/raw/main/Programa%20SIGEC-Pro/Atualizacao/updates_registry.js?_t=${Date.now()}`,
        `https://huggingface.co/spaces/${space}/raw/main/Atualizacao/updates_registry.js?_t=${Date.now()}`,
        `https://josecenturio-sigec-pro.static.hf.space/Atualizacao/updates_registry.js?_t=${Date.now()}`,
        `Atualizacao/updates_registry.js?_t=${Date.now()}`
      ];

      for (const ep of fetchEndpoints) {
        try {
          const headers = { 'Cache-Control': 'no-cache, no-store' };
          if (token && ep.includes('huggingface.co')) headers['Authorization'] = `Bearer ${token}`;
          const resp = await fetch(ep, { headers: headers, cache: 'no-store' });
          if (resp && resp.ok) {
            const jsCode = await resp.text();
            if (jsCode.includes('SIGEC_AVAILABLE_UPDATES')) {
              const func = new Function(jsCode);
              func();
              if (Array.isArray(window.SIGEC_AVAILABLE_UPDATES) && window.SIGEC_AVAILABLE_UPDATES.length > 0) {
                registryLoaded = true;
                break;
              }
            }
          }
        } catch(eFetch) {}
      }
    }

    const available = window.SIGEC_AVAILABLE_UPDATES || [];
    let latestUpdate = null;
    let latestVer = currentVersion;

    if (Array.isArray(available) && available.length > 0) {
      available.forEach(u => {
        const v = u.version || u.packageName;
        if (v && isNewerVersion(v, latestVer)) {
          latestVer = v;
          latestUpdate = u;
        }
      });
    }

    if (latestUpdate && isNewerVersion(latestVer, currentVersion)) {
      pendingUpdateData = latestUpdate;
      updateSoftwareModalUI(latestUpdate, 'huggingface');
      const modal = document.getElementById('updateConfirmationModal');
      if (modal) modal.classList.add('active');
    } else {
      updateInstalledVersionUI();
      if (!silentIfNoUpdate) {
        showToast(`O seu SIGEC-Pro está atualizado (${displayVer})!`, 'success');
        alert(`✅ O seu SIGEC-Pro está Atualizado!\n\nVersão Instalada: ${displayVer}\n\nNão existem novas atualizações pendentes no servidor.`);
      }
    }
  } catch (err) {
    console.error('Erro ao verificar atualizações:', err);
    updateInstalledVersionUI();
    if (!silentIfNoUpdate) {
      showToast(`O seu SIGEC-Pro está atualizado (${displayVer})!`, 'success');
      alert(`✅ O seu SIGEC-Pro está Atualizado!\n\nVersão Instalada: ${displayVer}\n\nNão existem novas atualizações pendentes no servidor.`);
    }
  }
}
window.checkAndInstallUpdate = checkAndInstallUpdate;

function updateSoftwareModalUI(pkgData, source) {
  if (!pkgData) return;
  const fileName = pkgData.fileName || (pkgData.packageName ? `${pkgData.packageName}.sigecpkg` : 'Atualizacao_SIGEC-Pro.sigecpkg');
  const ver = pkgData.version || pkgData.packageName || 'SIGEC_V1.7.13';
  const dataCriacao = pkgData.dataHoraCriacao || (pkgData.createdAt ? new Date(pkgData.createdAt).toLocaleString('pt-PT') : 'Recente');

  const fNameEl = document.getElementById('updateRestoreFileName');
  const fVerEl = document.getElementById('updateRestoreFileVersion');
  const fDateEl = document.getElementById('updateRestoreFileDate');
  const badgeEl = document.getElementById('updateRestoreSourceBadge');

  if (fNameEl) fNameEl.textContent = fileName;
  if (fVerEl) fVerEl.textContent = ver;
  if (fDateEl) fDateEl.textContent = dataCriacao;
  if (badgeEl) {
    if (source === 'local') {
      badgeEl.innerHTML = '<i class="fa-solid fa-hard-drive"></i> Ficheiro Local do Computador (.sigecpkg)';
      badgeEl.style.background = '#e0f2fe';
      badgeEl.style.color = '#0369a1';
      badgeEl.style.borderColor = '#bae6fd';
    } else {
      badgeEl.innerHTML = '<i class="fa-solid fa-cloud-check"></i> Servidor Hugging Face (Nuvem)';
      badgeEl.style.background = '#dcfce7';
      badgeEl.style.color = '#15803d';
      badgeEl.style.borderColor = '#86efac';
    }
  }
}
window.updateSoftwareModalUI = updateSoftwareModalUI;

function handleSystemUpdateFileSelect(event) {
  // Atualizações locais por ficheiro descontinuadas em favor do modelo Nuvem / PWA
}
window.handleSystemUpdateFileSelect = handleSystemUpdateFileSelect;

function closeUpdateConfirmationModal() {
  const modal = document.getElementById('updateConfirmationModal');
  if (modal) modal.classList.remove('active');
  pendingUpdateData = null;
}
window.closeUpdateConfirmationModal = closeUpdateConfirmationModal;

function triggerLocalUpdateFileSelect() {
  showToast('As atualizações do SIGEC-Pro são sincronizadas automaticamente através da Nuvem.', 'info');
}
window.triggerLocalUpdateFileSelect = triggerLocalUpdateFileSelect;

async function resolveSystemUpdateConfirm(shouldInstall) {
  const modal = document.getElementById('updateConfirmationModal');
  if (modal) modal.classList.remove('active');

  if (!shouldInstall) {
    showToast('Instalação da atualização cancelada.', 'info');
    pendingUpdateData = null;
    return;
  }

  if (!pendingUpdateData) {
    showToast('Erro: Não foi possível obter os dados da atualização.', 'danger');
    return;
  }

  try {
    showToast('A descarregar e aplicar nova versão a partir do Servidor Hugging Face...', 'info');
    const data = pendingUpdateData;
    const fileVersion = data.version || data.packageName || 'SIGEC_V1.7.24';

    // 1. Atualização via Web / Cache PWA
    console.info('[SIGEC-Pro] Atualização de software aplicada com sucesso para a versão:', fileVersion);

    // 2. Grava a nova versão no LocalStorage e no db.json
    localStorage.setItem('sigec_pro_installed_version', fileVersion);
    CURRENT_SYSTEM_VERSION = fileVersion;
    window.CURRENT_SYSTEM_VERSION = fileVersion;

    if (typeof db !== 'undefined' && db) {
      if (!db.config) db.config = {};
      db.config.versaoSoftware = fileVersion;
      if (typeof saveDatabase === 'function') saveDatabase();
    }

    updateInstalledVersionUI();
    pendingUpdateData = null;

    if (typeof logUserActivity === 'function') {
      logUserActivity('Atualização de Software', `Versão de software "${fileVersion}" instalada com sucesso.`);
    }

    showToast(`Atualização ${fileVersion} instalada com sucesso!`, 'success');
    alert(`✅ Atualização ${fileVersion} Concluída com Sucesso!\n\nO software do sistema e todos os seus ficheiros foram atualizados para a versão ${fileVersion}.\n\n🔒 Preservação Absoluta de Dados (AGENTS.md):\nTodos os seus registos existentes (${db.clientes ? db.clientes.length : 0} Clientes, ${db.contactos ? db.contactos.length : 0} Contactos, ${db.projetos ? db.projetos.length : 0} Projetos) foram 100% PRESERVADOS e mantidos intactos.\n\nA aplicação irá agora recarregar para aplicar o novo software.`);

    setTimeout(() => {
      window.location.reload();
    }, 600);
  } catch (err) {
    console.error('Erro ao instalar atualização:', err);
    showToast('Erro na instalação da atualização.', 'danger');
    alert(`Erro na Atualização:\nOcorreu um erro ao instalar a atualização: ${err.message}`);
  }
}
window.resolveSystemUpdateConfirm = resolveSystemUpdateConfirm;

