function getSelectedBudgetCliName() {
  const selectEl = document.getElementById('budgetHeaderCliente');
  if (!selectEl) return 'Cliente';
  const val = (selectEl.value || '').trim();
  if (!val) return 'Cliente';
  const matched = (db.clientes || []).find(c => String(c.id).trim() === val);
  if (matched && matched.nome) return matched.nome;
  if (selectEl.options && selectEl.selectedIndex >= 0) {
    const text = selectEl.options[selectEl.selectedIndex].text;
    if (text && !text.startsWith('--')) return text;
  }
  return val;
}
window.getSelectedBudgetCliName = getSelectedBudgetCliName;

function populateBudgetClientsSelect(selectedClientId = null) {
  const select = document.getElementById('budgetHeaderCliente');
  if (!select) return;
  
  let rawClients = (typeof getUserScopedItems === 'function') 
    ? getUserScopedItems(Array.isArray(db.clientes) ? db.clientes : []) 
    : (db.clientes || []);
  
  if (!rawClients || rawClients.length === 0) {
    rawClients = db.clientes || [];
  }

  const clients = [...rawClients].filter(c => c && c.nome).sort((a, b) => (a.nome || '').localeCompare(b.nome || '', 'pt', { sensitivity: 'base' }));
  
  const currentVal = selectedClientId || select.value || '';

  let optionsHtml = '<option value="" style="color: #64748b;">-- Selecione o Cliente --</option>';
  clients.forEach(cli => {
    const isSelected = currentVal ? (String(cli.id).trim() === String(currentVal).trim()) : false;
    optionsHtml += `<option value="${cli.id}" ${isSelected ? 'selected' : ''} style="color: #0f172a;">${escapeHtml(cli.nome)}</option>`;
  });
  select.innerHTML = optionsHtml;

  if (currentVal) {
    select.value = currentVal;
  }
}
window.populateBudgetClientsSelect = populateBudgetClientsSelect;

function handleBudgetClientSelect(clientId) {
  if (!clientId) return;
  const client = (db.clientes || []).find(c => String(c.id).trim() === String(clientId).trim());
  if (client) {
    syncBudgetRefFromClient(client.nome);
  }
}
window.handleBudgetClientSelect = handleBudgetClientSelect;

function populateBudgetClientsDatalist() {
  const dl = document.getElementById('budgetClientsDatalist');
  if (!dl) return;
  dl.innerHTML = '';
  const sortedClients = [...(db.clientes || [])].filter(c => c && c.nome).sort((a, b) => (a.nome || '').localeCompare(b.nome || '', 'pt', { sensitivity: 'base' }));
  sortedClients.forEach(cli => {
    const opt = document.createElement('option');
    opt.value = cli.nome;
    dl.appendChild(opt);
  });
}
window.populateBudgetClientsDatalist = populateBudgetClientsDatalist;


function handleBudgetClientInput(val) {
  const hiddenId = document.getElementById('budgetHeaderClienteId');
  const inputNorm = (typeof normalizeText === 'function' ? normalizeText(val) : (val || '').toLowerCase()).trim();

  let matched = null;
  if (inputNorm) {
    matched = (db.clientes || []).find(c => c && (typeof normalizeText === 'function' ? normalizeText(c.nome) : (c.nome || '').toLowerCase()).trim() === inputNorm);
    if (!matched) {
      matched = (db.clientes || []).find(c => c && Array.isArray(c.separadores) && c.separadores.some(s => s && (typeof normalizeText === 'function' ? normalizeText(s.nome) : (s.nome || '').toLowerCase()).trim() === inputNorm));
    }
  }

  if (hiddenId) {
    hiddenId.value = matched ? matched.id : '';
  }

  syncBudgetRefFromClient(val);
}
window.handleBudgetClientInput = handleBudgetClientInput;

function syncBudgetRefFromClient(clientName) {
  const refInput = document.getElementById('budgetHeaderRefCliente');
  if (!refInput) return;
  const cleanRef = (clientName || '').split(/[\s\(\[\-]/)[0] || 'Cliente';
  if (!refInput.value || refInput.value === 'BCN' || refInput.value === 'Cliente' || refInput.value.startsWith('BCN-')) {
    refInput.value = cleanRef + '-' + new Date().getFullYear();
  }
}
window.syncBudgetRefFromClient = syncBudgetRefFromClient;

function calculateBudgetGrandTotal() {
  let total = 0;
  const priceInputs = document.querySelectorAll('.budget-input-price');
  priceInputs.forEach(input => {
    const val = parseFloat(input.value) || 0;
    total += val;
  });
  return total;
}
window.calculateBudgetGrandTotal = calculateBudgetGrandTotal;

function recalculateBudgetTotal() {
  const total = calculateBudgetGrandTotal();
  const display = document.getElementById('budgetGrandTotalDisplay');
  if (display) {
    display.textContent = total.toLocaleString('pt-PT', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
  }
}
window.recalculateBudgetTotal = recalculateBudgetTotal;

function clearBudgetForm() {
  window._currentEditingBudgetId = null;
  window._pendingNewBudgetSeparador = null;
  const numEl = document.getElementById('budgetHeaderNum');
  const refEl = document.getElementById('budgetHeaderRefCliente');
  const cliEl = document.getElementById('budgetHeaderCliente');
  const dataEl = document.getElementById('budgetHeaderData');
  const estadoEl = document.getElementById('budgetHeaderEstado');
  const modelInp = document.getElementById('budgetModelPresetInput');

  if (numEl) numEl.value = '';
  if (refEl) refEl.value = '';
  populateBudgetClientsSelect('');
  if (cliEl) cliEl.value = '';
  if (dataEl) dataEl.value = '';
  if (estadoEl) estadoEl.value = 'Em avaliação';
  if (modelInp) modelInp.value = '';

  const descInputs = document.querySelectorAll('.budget-input-desc');
  descInputs.forEach(inp => inp.value = '');

  const priceInputs = document.querySelectorAll('.budget-input-price');
  priceInputs.forEach(inp => inp.value = '');

  const nameInputs = document.querySelectorAll('.budget-input-item-name');
  nameInputs.forEach(inp => inp.value = '');

  // Remover quadros dinâmicos adicionais criados pelo utilizador para voltar ao padrão
  const dynamicCards = document.querySelectorAll('.budget-dynamic-topic-card');
  dynamicCards.forEach(c => c.remove());

  // Remover linhas dinâmicas adicionais
  const dynamicRows = document.querySelectorAll('.budget-dynamic-row');
  dynamicRows.forEach(r => r.remove());

  // Limpar imagens
  restoreBudgetImagesData({});

  recalculateBudgetTotal();
  if (typeof showToast === 'function') {
    showToast('Todos os campos do orçamento foram limpos com sucesso.', 'info');
  }
}
window.clearBudgetForm = clearBudgetForm;
window.newBudgetForm = clearBudgetForm;

function populateBudgetModelPresetDatalist() {
  const dl = document.getElementById('budgetModelPresetDatalist');
  if (!dl) return;
  dl.innerHTML = '';

  const addedValues = new Set();

  // 1. Modelos Base Padrão
  const standardPresets = [
    'Camião 12T (Unidade Móvel Bancária/Atendimento)',
    'Furgão 5T (Unidade Móvel Compacta)',
    'SmartBus / Autocarro Tecnológico',
    'Semirreboque Extensível 13,80m'
  ];

  standardPresets.forEach(preset => {
    if (!addedValues.has(preset)) {
      addedValues.add(preset);
      const opt = document.createElement('option');
      opt.value = preset;
      dl.appendChild(opt);
    }
  });

  // 2. Orçamentos Efetuados e Modelos Personalizados Guardados
  const allBudgets = [];
  (db.clientes || []).forEach(cli => {
    if (Array.isArray(cli.orcamentos)) {
      cli.orcamentos.forEach(b => {
        if (!allBudgets.some(existing => existing.id === b.id)) {
          allBudgets.push(b);
        }
      });
    }
  });

  if (Array.isArray(db.orcamentos)) {
    db.orcamentos.forEach(b => {
      if (!allBudgets.some(existing => existing.id === b.id)) {
        allBudgets.push(b);
      }
    });
  }

  allBudgets.forEach(b => {
    if (b.modeloBase && !addedValues.has(b.modeloBase)) {
      addedValues.add(b.modeloBase);
      const opt = document.createElement('option');
      opt.value = b.modeloBase;
      dl.appendChild(opt);
    }

    const budgetLabel = `${b.numero || 'ORC'} - ${b.referencia || b.clienteNome || 'Orçamento'}`;
    if (!addedValues.has(budgetLabel)) {
      addedValues.add(budgetLabel);
      const opt = document.createElement('option');
      opt.value = budgetLabel;
      dl.appendChild(opt);
    }
  });
}
window.populateBudgetModelPresetDatalist = populateBudgetModelPresetDatalist;

function handleBudgetModelInput(val) {
  if (!val) return;
  const valLower = val.toLowerCase().trim();

  // 1. Verificar se corresponde a um orçamento efetuado para carregar os seus dados
  const allBudgets = [];
  (db.clientes || []).forEach(cli => {
    if (Array.isArray(cli.orcamentos)) {
      cli.orcamentos.forEach(b => {
        if (!allBudgets.some(existing => existing.id === b.id)) {
          allBudgets.push(b);
        }
      });
    }
  });
  if (Array.isArray(db.orcamentos)) {
    db.orcamentos.forEach(b => {
      if (!allBudgets.some(existing => existing.id === b.id)) {
        allBudgets.push(b);
      }
    });
  }

  const foundBudget = allBudgets.find(b => {
    const label = `${b.numero || 'ORC'} - ${b.referencia || b.clienteNome || 'Orçamento'}`.toLowerCase();
    return label === valLower || (b.numero && b.numero.toLowerCase() === valLower);
  });

  if (foundBudget) {
    loadSavedBudgetIntoForm(foundBudget.id);
    return;
  }

  // 2. Verificar se corresponde a modelos padrão
  if (valLower.includes('camião') || valLower.includes('camiao') || valLower === 'camiao') {
    applyBudgetModelPreset('camiao');
  } else if (valLower.includes('furgão') || valLower.includes('furgao') || valLower === 'furgao') {
    applyBudgetModelPreset('furgao');
  } else if (valLower.includes('smartbus') || valLower.includes('autocarro')) {
    applyBudgetModelPreset('smartbus');
  } else if (valLower.includes('semirreboque') || valLower.includes('reboque')) {
    applyBudgetModelPreset('semirreboque');
  }
}
window.handleBudgetModelInput = handleBudgetModelInput;

