// MOTOR MULTICANAL DE DISPARO DE EMAIL (UNIVERSAL: WEB, NUVEM E DESKTOP)
async function dispatchDirectEmail(targetEmail, subject, fields = {}) {
  if (!targetEmail || typeof targetEmail !== 'string') return { success: false, message: 'Email de destino inválido' };

  const cleanEmail = targetEmail.trim();
  if (!cleanEmail || !cleanEmail.includes('@')) return { success: false, message: 'Formato de email inválido' };

  const nowStr = new Date().toLocaleString('pt-PT');
  const settings = typeof getEmailNotifySettings === 'function' ? getEmailNotifySettings() : {
    smtpHost: 'smtp.gmail.com',
    smtpPort: '587',
    smtpUser: '',
    smtpPass: ''
  };

  const textSummary = Object.entries(fields)
    .filter(([k, v]) => !k.startsWith('_') && typeof v !== 'object' && v !== null && v !== undefined && String(v).trim() !== '')
    .map(([k, v]) => `${k}: ${v}`)
    .join('\n');

  const emailHtml = typeof generateEmailHTMLTemplate === 'function' 
    ? generateEmailHTMLTemplate(subject, fields)
    : '<div style="font-family: sans-serif; padding: 20px;"><h2>' + subject + '</h2><pre>' + textSummary + '</pre></div>';

  const emailBody = 'Notificação SIGEC-Pro - José Centúrio\n' +
    '===========================================\n\n' +
    'Data/Hora: ' + nowStr + '\n' +
    'Destinatário: ' + cleanEmail + '\n\n' +
    'Detalhes:\n' +
    '-------------------------------------------\n' +
    textSummary + '\n\n' +
    'Mensagem enviada automaticamente pelo sistema SIGEC-Pro.';

  console.info('[SIGEC-Pro] A despachar notificação por email para ' + cleanEmail + ' (' + subject + ')...');

  let sentOk = false;
  let statusMessage = '';

  // ------------------------------------------------------------------------
  // CANAL 1: Servidor Render Cloud Web Service Node.js (Porta 443 HTTPS)
  // Processa o envio no servidor sem restrições de CORS e com conexão direta ao Google
  // ------------------------------------------------------------------------
  const endpointsToTry = [
    'https://sigec-pro.onrender.com/api/send-email',
    '/api/send-email'
  ];

  const bridgePayload = {
    smtpHost: settings.smtpHost || 'smtp.gmail.com',
    smtpPort: parseInt(settings.smtpPort, 10) || 587,
    smtpUser: settings.smtpUser || DEFAULT_SYSTEM_SMTP_USER,
    smtpPass: settings.smtpPass || DEFAULT_SYSTEM_SMTP_PASS,
    webhookUrl: (settings.webhookUrl || '').trim(),
    senderName: 'SIGEC-Pro • Sistema Integrado de Clientes & Projetos',
    from: 'no-reply@sigec-pro.com',
    replyTo: 'no-reply@sigec-pro.com',
    to: cleanEmail,
    subject: subject || '[SIGEC-Pro] Notificação do Sistema',
    body: emailHtml,
    html: emailHtml
  };

  for (const ep of endpointsToTry) {
    try {
      console.info('[SIGEC-Pro] A tentar disparo de email via endpoint:', ep);
      const resp = await fetch(ep, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(bridgePayload)
      });
      if (resp && resp.ok) {
        const data = await resp.json();
        if (data && (data.success === true || data.status === 'success')) {
          sentOk = true;
          statusMessage = 'Email enviado com sucesso via servidor na nuvem!';
          console.info('[SIGEC-Pro] Disparo concluído com sucesso via:', ep);
          break;
        } else if (data && data.message) {
          statusMessage = data.message;
        }
      }
    } catch(eEp) {}
  }

  // ------------------------------------------------------------------------
  // CANAL 2: Fallback direto via Google Apps Script Webhook (no-cors)
  // ------------------------------------------------------------------------
  const webhookUrl = (settings.webhookUrl || '').trim();
  if (!sentOk && webhookUrl && webhookUrl.startsWith('https://')) {
    try {
      console.info('[SIGEC-Pro] A despachar email via Google Apps Script direto (no-cors)...');
      await fetch(webhookUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({
          to: cleanEmail,
          name: 'SIGEC-Pro • Sistema Integrado de Clientes & Projetos',
          senderName: 'SIGEC-Pro • Sistema Integrado de Clientes & Projetos',
          from: 'no-reply@sigec-pro.com',
          replyTo: 'no-reply@sigec-pro.com',
          subject: subject || '[SIGEC-Pro] Notificação do Sistema',
          html: emailHtml,
          body: textSummary
        })
      });
      sentOk = true;
      statusMessage = 'Email enviado com sucesso via Google Workspace Gateway!';
    } catch(errG) {
      console.warn('[SIGEC-Pro] Aviso no Webhook Google:', errG);
    }
  }

  // ------------------------------------------------------------------------
  // CANAL 2: Registo Central de Auditoria e Logs do Sistema
  // ------------------------------------------------------------------------
  try {
    if (typeof db !== 'undefined') {
      if (!Array.isArray(db.userLogs)) db.userLogs = [];
      db.userLogs.unshift({
        id: 'log-' + Date.now() + '-' + Math.floor(Math.random() * 10000),
        timestamp: new Date().toISOString(),
        categoria: 'Email / Notificação',
        acao: 'Notificação por Email',
        tipoAcao: 'Notificação por Email',
        descricao: 'Notificação para ' + cleanEmail + ' ("' + subject + '"). Estado: ' + (sentOk ? 'Enviado' : 'Registado no Sistema'),
        detalhes: {
          destinatario: cleanEmail,
          assunto: subject,
          estado: sentOk ? 'Enviado com Sucesso via SMTP' : 'Registado no Sistema',
          mensagem: statusMessage || (sentOk ? 'Disparo concluído com sucesso' : 'Notificação registada internamente'),
          resumo: textSummary
        }
      });
      if (db.userLogs.length > 300) db.userLogs = db.userLogs.slice(0, 300);
      if (typeof safeSetStorage === 'function') {
        safeSetStorage('sigec_pro_user_logs', JSON.stringify(db.userLogs.slice(0, 100)));
      }
    }
  } catch(eLog) {}

  return { success: sentOk, message: statusMessage || (sentOk ? 'Notificação enviada com sucesso' : 'Serviço SMTP desktop indisponível ou palavra-passe em falta') };
}
window.dispatchDirectEmail = dispatchDirectEmail;

function toggleSmtpPassVisibility() {
  const passEl = document.getElementById('cfgSmtpPass');
  const iconEl = document.getElementById('toggleSmtpPassIcon');
  if (!passEl) return;
  if (passEl.type === 'password') {
    passEl.type = 'text';
    if (iconEl) {
      iconEl.classList.remove('fa-eye');
      iconEl.classList.add('fa-eye-slash');
    }
  } else {
    passEl.type = 'password';
    if (iconEl) {
      iconEl.classList.remove('fa-eye-slash');
      iconEl.classList.add('fa-eye');
    }
  }
}
window.toggleSmtpPassVisibility = toggleSmtpPassVisibility;

async function sendNewUserRegistrationEmailNotification(userData, isTest = false) {
  const settings = getEmailNotifySettings();
  if (!settings.enabled && !isTest) return false;
  const targetEmail = (settings.email || '').trim();
  if (!targetEmail) return false;

  const userName = userData.nome || 'Novo Utilizador';
  const userEmail = userData.email || 'Não especificado';
  const userCargo = userData.cargo || 'Não especificado';
  const userIdioma = userData.idioma || 'Português';
  const userRole = userData.role === 'admin' ? 'Administrador' : 'Utilizador Padrão';
  const userPin = userData.pin || '••••••••';
  const nowStr = new Date().toLocaleString('pt-PT');
  const userAgent = typeof navigator !== 'undefined' ? navigator.userAgent : 'Navegador Web';
  const deviceInfo = /Mobile|Android|iPhone/i.test(userAgent) ? 'Dispositivo Móvel' : 'Computador';

  const issueTitle = isTest 
    ? '[SIGEC-Pro Teste] Confirmação de Notificação por Email - ' + nowStr
    : '[SIGEC-Pro Alerta] Novo Utilizador Registado: ' + userName + ' (Pendente de Aprovação)';

  const emailFields = {
    Assunto: issueTitle,
    'Nome do Utilizador': userName,
    'Email': userEmail,
    'Cargo / Função': userCargo,
    'Idioma': userIdioma,
    'Palavra-Passe / PIN': userPin,
    'Perfil Atribuído': userRole,
    'Estado da Conta': isTest ? 'Ativo (Teste de Notificação)' : 'Pendente de Ativação pelo Administrador',
    'Data e Hora do Registo': nowStr,
    'Dispositivo': deviceInfo,
    'Instruções para o Administrador': isTest 
      ? 'Este é um email de teste para validar o canal SMTP e a receção de alertas no sistema SIGEC-Pro.' 
      : 'Aceda ao separador Configuração > Gestão de Utilizadores no programa SIGEC-Pro para aprovar e ativar o acesso deste utilizador.',
    'Sistema': 'SIGEC-Pro • Sistema Integrado de Clientes & Projetos',
    empresa: 'SIGEC-Pro • Sistema Integrado de Clientes & Projetos'
  };

  const res = await dispatchDirectEmail(targetEmail, issueTitle, emailFields);

  if (typeof logUserActivity === 'function') {
    logUserActivity('Notificação por Email', 'Alerta de registo emitido para ' + targetEmail + ' (' + userName + ').');
  }

  return res;
}
window.sendNewUserRegistrationEmailNotification = sendNewUserRegistrationEmailNotification;

async function sendTestEmailNotification() {
  handleSaveEmailNotifySettings(false);
  const settings = getEmailNotifySettings();
  const targetEmail = (settings.email || '').trim();

  if (!targetEmail) {
    showToast('Por favor insira um email de destino válido nas definições.', 'warning');
    return;
  }

  if (!settings.smtpPass) {
    showToast('⚠️ O campo "Palavra-Passe / App Password" está vazio. Introduza a palavra-passe de aplicação para autenticação SMTP.', 'warning', 7000);
  }

  showToast('A enviar email de teste via SMTP para ' + targetEmail + '...', 'info');

  const res = await sendNewUserRegistrationEmailNotification({
    nome: 'José Centúrio (Teste de Notificação)',
    email: targetEmail,
    cargo: 'Administrador do Sistema',
    idioma: 'Português',
    role: 'admin',
    pin: 'Admin#2026'
  }, true);

  if (res && res.success) {
    showToast('✅ Email de teste enviado com sucesso para ' + targetEmail + '!', 'success', 6000);
    alert('✅ Teste de Envio Concluído com Sucesso!\n\nA notificação por email foi enviada para ' + targetEmail + ' com o formato oficial do SIGEC-Pro.\n\nPor favor, verifique a sua Caixa de Entrada.');
  } else {
    const errorDetail = res && res.message ? res.message : 'Falha no envio';
    showToast('Aviso de Envio: ' + errorDetail, 'warning', 8000);

    const isWebBrowser = typeof window !== 'undefined' && (window.location.protocol === 'https:' || !window.location.host.includes('127.0.0.1'));
    if (isWebBrowser) {
      const openGmail = confirm(
        'ℹ️ Informação sobre o Envio Web (' + window.location.hostname + '):\n\n' +
        'O envio automático silencioso em segundo plano funciona através do executável "SIGEC-Pro.exe" no seu computador.\n\n' +
        'Nos navegadores web (Chrome/Edge/Render), o navegador restringe ligações directas a servidores de email por segurança.\n\n' +
        'Deseja abrir o Gmail agora com este email de teste já preenchido para envio imediato?'
      );
      if (openGmail) {
        const testSub = encodeURIComponent('[SIGEC-Pro Teste] Confirmação de Notificação por Email');
        const testBody = encodeURIComponent(
          'Email de Teste do Sistema SIGEC-Pro\n' +
          '====================================\n\n' +
          'Destinatário: ' + targetEmail + '\n' +
          'Remetente: ' + (settings.smtpUser || '') + '\n' +
          'Data/Hora: ' + new Date().toLocaleString('pt-PT') + '\n\n' +
          'Este email confirma a configuração correta do sistema SIGEC-Pro.\n\n' +
          'SIGEC-Pro • Sistema Integrado de Clientes & Projetos\n' +
          'Propriedade Exclusiva de José Centúrio'
        );
        window.open('https://mail.google.com/mail/?view=cm&fs=1&to=' + encodeURIComponent(targetEmail) + '&su=' + testSub + '&body=' + testBody, '_blank');
      }
    } else {
      alert('ℹ️ Informação sobre o Envio SMTP:\n\n' + errorDetail + '\n\nCertifique-se de que:\n1. O programa está aberto através do SIGEC-Pro.exe.\n2. O campo "Palavra-Passe / App Password" tem a palavra-passe de aplicação do Google Workspace.');
    }
  }
}
window.sendTestEmailNotification = sendTestEmailNotification;

