// ==========================================
// ALERTA VISUAL DE NOVOS REGISTOS PENDENTES NO PROGRAMA
// ==========================================
let _adminPendingWatcherInterval = null;
let _dismissedPendingAlertIds = new Set();

function checkPendingNewUsersNotification() {
  ensureUsersInitialized();
  const isAuth = typeof sessionStorage !== 'undefined' && sessionStorage.getItem('sigec_pro_authenticated') === 'true';
  const activeUserId = isAuth ? sessionStorage.getItem('sigec_pro_active_user_id') : null;
  let activeUser = (activeUserId && typeof db !== 'undefined' && Array.isArray(db.usuarios)) ? db.usuarios.find(u => u && u.id === activeUserId) : null;
  if (!activeUser || !hasConfigAccess(activeUser)) {
    dismissPendingUserBanner();
    return;
  }

  const pendingUsers = (db.usuarios || []).filter(u => u && u.role !== 'admin' && u.active === false);
  const navBtnConfig = document.getElementById('navBtnConfiguracao') || (typeof document !== 'undefined' && document.querySelector('.nav-btn[data-tab="tab-database"]'));
  if (navBtnConfig) {
    let badge = (typeof navBtnConfig.querySelector === 'function') ? navBtnConfig.querySelector('.nav-pending-badge') : null;
    if (pendingUsers.length > 0) {
      if (!badge) {
        badge = document.createElement('span');
        badge.className = 'nav-pending-badge';
        badge.style.cssText = 'display: inline-flex; align-items: center; justify-content: center; background: #ef4444; color: #ffffff; font-size: 0.7rem; font-weight: 700; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 9px; margin-left: 6px; vertical-align: middle; animation: pulse 2s infinite;';
        navBtnConfig.appendChild(badge);
      }
      badge.textContent = pendingUsers.length;
    } else if (badge) {
      badge.remove();
    }
  }

  const unacknowledged = pendingUsers.filter(u => !_dismissedPendingAlertIds.has(u.id));
  if (unacknowledged.length > 0) {
    showAdminPendingUserBanner(unacknowledged);
  } else {
    dismissPendingUserBanner();
  }
}
window.checkPendingNewUsersNotification = checkPendingNewUsersNotification;

function showAdminPendingUserBanner(unacknowledged) {
  let container = document.getElementById('sigec_admin_pending_users_banner');
  if (!container) {
    container = document.createElement('div');
    container.id = 'sigec_admin_pending_users_banner';
    container.style.cssText = 'position: fixed; top: 75px; right: 20px; z-index: 99999; max-width: 440px; width: calc(100vw - 40px); background: #ffffff; border: 2px solid #f59e0b; border-radius: 12px; box-shadow: 0 12px 36px rgba(0,0,0,0.2); padding: 1.1rem; font-family: inherit; animation: slideInRight 0.3s cubic-bezier(0.16, 1, 0.3, 1);';
    document.body.appendChild(container);
  }

  const count = unacknowledged.length;
  let usersListHtml = unacknowledged.slice(0, 3).map(u => `
    <div style="background: #fffbeb; border: 1px solid #fde68a; border-radius: 8px; padding: 0.65rem 0.75rem; margin-bottom: 0.5rem; display: flex; flex-direction: column; gap: 0.4rem;">
      <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 0.5rem;">
        <div>
          <strong style="color: #0f172a; font-size: 0.88rem; display: block;">${u.nome || 'Novo Utilizador'}</strong>
          <span style="font-size: 0.78rem; color: #64748b;"><i class="fa-regular fa-envelope"></i> ${u.email || ''}</span>
          <div style="font-size: 0.75rem; color: #b45309; font-weight: 600; margin-top: 2px;">
            <i class="fa-solid fa-briefcase"></i> ${u.cargo || 'Utilizador'} | <i class="fa-solid fa-language"></i> ${u.idioma || 'Português'}
          </div>
        </div>
      </div>
      <div style="display: flex; gap: 0.4rem; justify-content: flex-end; flex-wrap: wrap; margin-top: 2px;">
        <button type="button" class="btn btn-sm" onclick="sendDirectUserConfirmationMail('${u.id}')" title="Enviar dados de acesso por email" style="background: #0284c7; color: #ffffff; border: none; font-weight: 700; font-size: 0.78rem; padding: 0.35rem 0.65rem; border-radius: 6px; cursor: pointer; display: inline-flex; align-items: center; gap: 0.3rem; box-shadow: 0 1px 3px rgba(2,132,199,0.3);">
          <i class="fa-solid fa-paper-plane"></i> Enviar Email
        </button>
        <button type="button" class="btn btn-sm" onclick="quickApproveUser('${u.id}')" style="background: #16a34a; color: #ffffff; border: none; font-weight: 700; font-size: 0.78rem; padding: 0.35rem 0.75rem; border-radius: 6px; cursor: pointer; display: inline-flex; align-items: center; gap: 0.35rem; box-shadow: 0 1px 3px rgba(22,163,74,0.3);">
          <i class="fa-solid fa-user-check"></i> ⚡ Dar de Alta Agora
        </button>
        <button type="button" class="btn btn-sm" onclick="openUserActivityLogFlow('${u.id}')" style="background: #eff6ff; color: #1d4ed8; border: 1px solid #bfdbfe; font-weight: 600; font-size: 0.78rem; padding: 0.35rem 0.6rem; border-radius: 6px; cursor: pointer; display: inline-flex; align-items: center; gap: 0.3rem;">
          <i class="fa-solid fa-address-card"></i> Ver Ficha
        </button>
      </div>
    </div>
  `).join('');

  if (unacknowledged.length > 3) {
    usersListHtml += `<div style="text-align: center; font-size: 0.78rem; color: #64748b; margin-bottom: 0.5rem;">+ ${unacknowledged.length - 3} outro(s) utilizador(es) pendente(s)</div>`;
  }

  container.innerHTML = `
    <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.75rem; border-bottom: 1px solid #fef3c7; padding-bottom: 0.5rem;">
      <div style="display: flex; align-items: center; gap: 0.5rem;">
        <div style="width: 32px; height: 32px; border-radius: 50%; background: #fef3c7; color: #d97706; display: flex; align-items: center; justify-content: center; font-size: 1rem;">
          <i class="fa-solid fa-bell fa-shake"></i>
        </div>
        <div>
          <h4 style="margin: 0; font-size: 0.92rem; color: #92400e; font-weight: 700;">Novo(s) Registo(s) de Utilizador</h4>
          <span style="font-size: 0.72rem; color: #b45309;">${count} pedido(s) a aguardar ativação do Administrador</span>
        </div>
      </div>
      <button type="button" onclick="dismissPendingUserBanner()" title="Fechar alerta" style="background: none; border: none; font-size: 1.25rem; color: #94a3b8; cursor: pointer; padding: 0 4px; line-height: 1;">&times;</button>
    </div>

    ${usersListHtml}

    <div style="display: flex; gap: 0.5rem; justify-content: space-between; align-items: center; margin-top: 0.5rem;">
      <button type="button" class="btn btn-sm" onclick="if(typeof switchTab==='function'){switchTab('tab-database');} dismissPendingUserBanner();" style="background: #f8fafc; color: #334155; border: 1px solid #cbd5e1; font-size: 0.75rem; padding: 0.35rem 0.65rem; border-radius: 6px; cursor: pointer; flex: 1; justify-content: center;">
        <i class="fa-solid fa-users-gear"></i> Gestão de Utilizadores
      </button>
      <button type="button" class="btn btn-sm" onclick="dismissPendingUserBanner()" style="background: transparent; color: #64748b; border: none; font-size: 0.75rem; padding: 0.35rem 0.65rem; cursor: pointer;">
        Dispensar
      </button>
    </div>
  `;
}
window.showAdminPendingUserBanner = showAdminPendingUserBanner;

function dismissPendingUserBanner() {
  const container = document.getElementById('sigec_admin_pending_users_banner');
  if (container) container.remove();
  const pendingUsers = (db.usuarios || []).filter(u => u && u.role !== 'admin' && u.active === false);
  pendingUsers.forEach(u => _dismissedPendingAlertIds.add(u.id));
}
window.dismissPendingUserBanner = dismissPendingUserBanner;

async function quickApproveUser(userId) {
  ensureUsersInitialized();
  const user = db.usuarios.find(u => u && u.id === userId);
  if (!user) return;

  user.active = true;
  _dismissedPendingAlertIds.delete(userId);
  safeSetStorage('sigec_pro_usuarios', JSON.stringify(db.usuarios || []));
  saveDatabase();

  if (typeof renderUserManagementGrid === 'function') renderUserManagementGrid();
  if (typeof renderUserSelectOptions === 'function') renderUserSelectOptions();
  if (typeof checkPendingNewUsersNotification === 'function') checkPendingNewUsersNotification();

  // Envio imediato do email de ativação no idioma do utilizador
  if (typeof sendUserAccountActivatedEmail === 'function') {
    sendUserAccountActivatedEmail(user).catch(() => {});
  }

  // Sincronização em tempo real para o servidor Hugging Face
  if (typeof syncDatabaseToHuggingFace === 'function') {
    syncDatabaseToHuggingFace(true, true).catch(() => {});
  }

  logUserActivity('Gestão de Utilizadores', 'Utilizador ' + user.nome + ' (' + user.email + ') foi dado de alta e ativado de imediato pelo Administrador.');
  showToast('✅ Utilizador "' + user.nome + '" dado de alta e ativado com sucesso! Foi enviado email de confirmação.', 'success');
}
window.quickApproveUser = quickApproveUser;

function sendDirectUserConfirmationMail(userId) {
  ensureUsersInitialized();
  const user = (db.usuarios || []).find(u => u && u.id === userId);
  if (!user || !user.email) {
    showToast('Utilizador não encontrado ou sem email registado.', 'warning');
    return;
  }

  const userName = user.nome || 'Utilizador';
  const userEmail = user.email.trim();
  const userCargo = user.cargo || 'Não especificado';
  const userPin = user.pin || '••••••••';
  const userLang = user.idioma || 'Português';
  const nowStr = new Date().toLocaleString('pt-PT');

  const subject = `[SIGEC-Pro] Confirmação do seu Registo de Utilizador`;
  const body = `Estimado(a) ${userName},\n\n` +
    `O seu registo no sistema SIGEC-Pro foi submetido com sucesso.\n\n` +
    `Dados da sua conta:\n` +
    `- Nome Completo: ${userName}\n` +
    `- Email de Acesso: ${userEmail}\n` +
    `- Cargo / Função: ${userCargo}\n` +
    `- Idioma Configurado: ${userLang}\n` +
    `- Palavra-Passe / PIN de Acesso: ${userPin}\n` +
    `- Estado da Conta: ${user.active ? 'Ativo' : 'Pendente de Ativação pelo Administrador'}\n` +
    `- Data e Hora de Registo: ${nowStr}\n\n` +
    `Instruções Importantes:\n` +
    `O seu acesso está associado ao sistema SIGEC-Pro. Poderá iniciar sessão com o seu email e palavra-passe.\n\n` +
    `SIGEC-Pro • Sistema Integrado de Clientes & Projetos\n` +
    `Propriedade Exclusiva de José Centúrio`;

  // 1. Tentar despacho direto via SMTP local se disponível
  if (typeof sendUserRegistrationConfirmationEmail === 'function') {
    sendUserRegistrationConfirmationEmail(user).catch(() => {});
  }

  // 2. Abrir envio assistido no Gmail ou cliente de email pré-preenchido
  const encSub = encodeURIComponent(subject);
  const encBody = encodeURIComponent(body);
  const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(userEmail)}&su=${encSub}&body=${encBody}`;
  const mailtoUrl = `mailto:${encodeURIComponent(userEmail)}?subject=${encSub}&body=${encBody}`;

  try {
    const win = window.open(gmailUrl, '_blank');
    if (!win || win.closed || typeof win.closed === 'undefined') {
      window.location.href = mailtoUrl;
    }
  } catch(e) {
    window.location.href = mailtoUrl;
  }
  showToast(`A preparar envio de email para ${userEmail}...`, 'info');
}
window.sendDirectUserConfirmationMail = sendDirectUserConfirmationMail;

function startAdminPendingUserWatcher() {
  if (_adminPendingWatcherInterval) {
    clearInterval(_adminPendingWatcherInterval);
    _adminPendingWatcherInterval = null;
  }

  const isAuth = typeof sessionStorage !== 'undefined' && sessionStorage.getItem('sigec_pro_authenticated') === 'true';
  const activeUserId = isAuth ? sessionStorage.getItem('sigec_pro_active_user_id') : null;
  let activeUser = (activeUserId && typeof db !== 'undefined' && Array.isArray(db.usuarios)) ? db.usuarios.find(u => u && u.id === activeUserId) : null;
  if (!activeUser || !hasConfigAccess(activeUser)) return;

  // Verificação periódica de novos utilizadores pendentes na memória sem downloads pesados
  _adminPendingWatcherInterval = setInterval(() => {
    try {
      const isStillAuth = typeof sessionStorage !== 'undefined' && sessionStorage.getItem('sigec_pro_authenticated') === 'true';
      if (!isStillAuth) {
        clearInterval(_adminPendingWatcherInterval);
        return;
      }
      checkPendingNewUsersNotification();
    } catch (e) {}
  }, 60000);
}
window.startAdminPendingUserWatcher = startAdminPendingUserWatcher;

