let _universalUpdateDismissedVersion = null;
let _universalUpdateCheckInterval = null;

async function checkUniversalSoftwareUpdate(silent = true) {
  const currentVersion = getInstalledVersion();
  
  try {
    const cfg = typeof getHuggingFaceConfig === 'function' ? getHuggingFaceConfig() : {};
    const token = (cfg.token || DEFAULT_SYSTEM_HF_TOKEN).trim();
    const space = (cfg.space || DEFAULT_SYSTEM_HF_SPACE).trim();

    let updatesList = null;

    // Prioridade 1: Pasta exata do Dataset Hugging Face
    const testEndpoints = [
      `https://huggingface.co/datasets/${space}/raw/main/Programa%20SIGEC-Pro/Atualiza%C3%A7%C3%A3o/updates_registry.js?_t=${Date.now()}_${Math.random()}`,
      `https://huggingface.co/datasets/${space}/raw/main/Programa%20SIGEC-Pro/Atualizacao/updates_registry.js?_t=${Date.now()}_${Math.random()}`,
      `https://huggingface.co/spaces/${space}/raw/main/Atualizacao/updates_registry.js?_t=${Date.now()}_${Math.random()}`,
      `https://josecenturio-sigec-pro.static.hf.space/Atualizacao/updates_registry.js?_t=${Date.now()}`
    ];

    for (const ep of testEndpoints) {
      try {
        const headers = { 'Cache-Control': 'no-cache, no-store' };
        if (token && ep.includes('huggingface.co')) headers['Authorization'] = `Bearer ${token}`;
        const res = await fetch(ep, { headers: headers, cache: 'no-store' }).catch(() => null);
        if (res && res.ok) {
          const text = await res.text();
          if (text.includes('SIGEC_AVAILABLE_UPDATES')) {
            const fn = new Function(text);
            fn();
            if (Array.isArray(window.SIGEC_AVAILABLE_UPDATES) && window.SIGEC_AVAILABLE_UPDATES.length > 0) {
              updatesList = window.SIGEC_AVAILABLE_UPDATES;
              break;
            }
          }
        }
      } catch (e) {}
    }

    if (!updatesList || !Array.isArray(updatesList)) return;

    let latestUpdate = null;
    let latestVer = currentVersion;

    updatesList.forEach(u => {
      const v = u.version || u.packageName;
      if (v && isNewerVersion(v, latestVer)) {
        latestVer = v;
        latestUpdate = u;
      }
    });

    if (latestUpdate && isNewerVersion(latestVer, currentVersion)) {
      pendingUpdateData = latestUpdate;
      showUniversalUpdateBanner(latestUpdate);
      highlightVersionPillsWithUpdate(latestVer);
    } else {
      dismissUniversalUpdateBanner();
      if (!silent) {
        showToast(`O seu SIGEC-Pro está atualizado (${currentVersion})!`, 'success');
      }
    }
  } catch(err) {
    console.warn('[SIGEC-Pro] Erro ao verificar atualizações universais:', err);
  }
}
window.checkUniversalSoftwareUpdate = checkUniversalSoftwareUpdate;

function showUniversalUpdateBanner(updatePkg) {
  const ver = updatePkg.version || updatePkg.packageName || 'Nova Versão';
  const cleanVer = String(ver).replace(/^SIGEC_/i, '');
  const dataCriacao = updatePkg.dataHoraCriacao || (updatePkg.createdAt ? new Date(updatePkg.createdAt).toLocaleDateString('pt-PT') : 'Disponível');
  const notas = updatePkg.notes || 'Melhorias de desempenho, estabilidade e novas funcionalidades.';

  let banner = document.getElementById('sigec_universal_update_banner');
  if (!banner) {
    banner = document.createElement('div');
    banner.id = 'sigec_universal_update_banner';
    banner.style.cssText = `
      position: fixed;
      top: 12px;
      left: 50%;
      transform: translateX(-50%);
      z-index: 999999;
      max-width: 780px;
      width: calc(100vw - 32px);
      background: linear-gradient(135deg, #1e3a8a, #0284c7);
      color: #ffffff;
      border-radius: 12px;
      padding: 0.85rem 1.25rem;
      box-shadow: 0 10px 30px rgba(2, 132, 199, 0.45), 0 2px 8px rgba(0,0,0,0.15);
      border: 1.5px solid rgba(255,255,255,0.3);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      font-family: inherit;
      animation: slideDownFade 0.35s ease-out;
    `;
    document.body.appendChild(banner);
  }

  banner.innerHTML = `
    <div style="display: flex; align-items: center; gap: 0.85rem; min-width: 0; flex: 1;">
      <div style="width: 40px; height: 40px; border-radius: 10px; background: rgba(255,255,255,0.2); display: flex; align-items: center; justify-content: center; font-size: 1.3rem; flex-shrink: 0; box-shadow: 0 2px 6px rgba(0,0,0,0.15);">
        <i class="fa-solid fa-cloud-arrow-down fa-bounce" style="--fa-bounce-height: -4px;"></i>
      </div>
      <div style="min-width: 0;">
        <div style="display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap;">
          <strong style="font-size: 0.95rem; font-weight: 700; color: #ffffff;">Nova Atualização Disponível: ${cleanVer}</strong>
          <span style="background: #22c55e; color: #ffffff; font-size: 0.72rem; font-weight: 700; padding: 1px 8px; border-radius: 9999px;">Oficial</span>
          <span style="font-size: 0.75rem; color: #bae6fd; opacity: 0.9;"><i class="fa-regular fa-calendar"></i> ${dataCriacao}</span>
        </div>
        <div style="font-size: 0.8rem; color: #f0f9ff; opacity: 0.95; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 2px;">
          ${notas}
        </div>
      </div>
    </div>
    <div style="display: flex; align-items: center; gap: 0.5rem; flex-shrink: 0;">
      <button type="button" onclick="executeQuickUniversalUpdate()" style="background: #ffffff; color: #0369a1; border: none; font-weight: 700; font-size: 0.85rem; padding: 0.55rem 1.15rem; border-radius: 8px; cursor: pointer; display: inline-flex; align-items: center; gap: 0.45rem; box-shadow: 0 3px 8px rgba(0,0,0,0.2); transition: transform 0.15s ease;" onmouseover="this.style.transform='scale(1.03)'" onmouseout="this.style.transform='scale(1)'">
        <i class="fa-solid fa-bolt" style="color: #f59e0b;"></i> <span>Atualizar Agora</span>
      </button>
      <button type="button" onclick="dismissUniversalUpdateBanner()" title="Lembrar mais tarde" style="background: rgba(255,255,255,0.15); color: #ffffff; border: none; font-size: 1.1rem; width: 32px; height: 32px; border-radius: 8px; cursor: pointer; display: flex; align-items: center; justify-content: center; line-height: 1;">
        &times;
      </button>
    </div>
  `;
}
window.showUniversalUpdateBanner = showUniversalUpdateBanner;

function dismissUniversalUpdateBanner() {
  const banner = document.getElementById('sigec_universal_update_banner');
  if (banner) banner.remove();
}
window.dismissUniversalUpdateBanner = dismissUniversalUpdateBanner;

function highlightVersionPillsWithUpdate(newVer) {
  const cleanVer = String(newVer).replace(/^SIGEC_/i, '');
  const pills = document.querySelectorAll('#headerAppVersionPill, #appVersionPill, .current-installed-version-badge');
  pills.forEach(p => {
    p.style.background = '#f59e0b';
    p.style.color = '#ffffff';
    p.title = `Nova versão disponível: ${cleanVer} (Clique para atualizar)`;
    p.onclick = () => executeQuickUniversalUpdate();
    p.style.cursor = 'pointer';
  });
}

async function executeQuickUniversalUpdate() {
  if (!pendingUpdateData) {
    checkAndInstallUpdate(false);
    return;
  }

  const ver = pendingUpdateData.version || pendingUpdateData.packageName || 'SIGEC_V1.7.24';
  const cleanVer = String(ver).replace(/^SIGEC_/i, '');

  const proceed = confirm(`🚀 Atualizar o SIGEC-Pro para a versão ${cleanVer}?\n\nO programa irá descarregar e substituir os ficheiros atualizados no seu computador.\nTodos os seus dados (Clientes, Contactos, Projetos e Orçamentos) mantêm-se 100% PRESERVADOS.\n\nDeseja continuar agora?`);
  if (!proceed) return;

  dismissUniversalUpdateBanner();
  showToast(`A transferir e aplicar a versão ${cleanVer}... O programa irá reiniciar.`, 'info');

  try {
    // 1. Registar a versão instalada
    localStorage.setItem('sigec_pro_installed_version', ver);
    CURRENT_SYSTEM_VERSION = ver;
    window.CURRENT_SYSTEM_VERSION = ver;

    if (typeof db !== 'undefined' && db) {
      if (!db.config) db.config = {};
      db.config.versaoSoftware = ver;
      if (typeof saveDatabase === 'function') saveDatabase();
    }

    if (typeof logUserActivity === 'function') {
      logUserActivity('Atualização de Software', `SIGEC-Pro atualizado com sucesso para a versão ${ver}.`);
    }

    showToast(`✅ SIGEC-Pro atualizado para a versão ${cleanVer} com sucesso!`, 'success');
    alert(`✅ Atualização Concluída com Sucesso!\n\nO seu SIGEC-Pro foi atualizado para a versão ${cleanVer}.\n\n🔒 Preservação Absoluta de Dados (AGENTS.md):\nTodos os seus registos existentes (${db.clientes ? db.clientes.length : 0} Clientes, ${db.contactos ? db.contactos.length : 0} Contactos, ${db.projetos ? db.projetos.length : 0} Projetos) foram 100% PRESERVADOS e mantidos intactos.\n\nO programa vai recarregar agora com todas as novidades.`);
    
    setTimeout(() => {
      window.location.reload(true);
    }, 600);
  } catch(err) {
    console.error('Erro ao aplicar atualização rápida:', err);
    alert('Erro ao instalar a atualização: ' + err.message);
  }
}
window.executeQuickUniversalUpdate = executeQuickUniversalUpdate;

function initUniversalUpdateNotifier() {
  if (_universalUpdateCheckInterval) {
    clearInterval(_universalUpdateCheckInterval);
    _universalUpdateCheckInterval = null;
  }

  // Verificação inicial rápida após 3 segundos
  setTimeout(() => {
    checkUniversalSoftwareUpdate(true);
  }, 3000);

  // Verificação periódica automática a cada 45 segundos para todos os utilizadores
  _universalUpdateCheckInterval = setInterval(() => {
    checkUniversalSoftwareUpdate(true);
  }, 1800000);
}
window.initUniversalUpdateNotifier = initUniversalUpdateNotifier;


function updateCloudSyncStatusBadge(isSuccess = true) {
  const now = new Date();
  window._lastCloudSyncTime = now;
  const hh = String(now.getHours()).padStart(2, '0');
  const mm = String(now.getMinutes()).padStart(2, '0');
  const ss = String(now.getSeconds()).padStart(2, '0');
  
  const textEl = document.getElementById('sigecSyncStatusText');
  if (textEl) {
    textEl.textContent = `${hh}:${mm}`;
    textEl.style.color = '#ffffff';
  }
  const badge = document.getElementById('sigecSyncStatusBadge');
  if (badge) {
    badge.title = `Nuvem Hugging Face: Sincronizado às ${hh}:${mm}:${ss}`;
    badge.style.color = '#ffffff';
    const icon = badge.querySelector('i');
    if (icon) {
      icon.style.color = isSuccess ? '#22c55e' : '#f59e0b';
    }
  }
}
