function toggleHfTokenVisibility() {
  const tokenEl = document.getElementById('hfPersonalToken') || document.getElementById('githubPersonalToken');
  const iconEl = document.getElementById('toggleHfTokenIcon') || document.getElementById('toggleHuggingFaceTokenIcon');
  if (!tokenEl) return;
  if (tokenEl.type === 'password') {
    tokenEl.type = 'text';
    if (iconEl) {
      iconEl.classList.remove('fa-eye');
      iconEl.classList.add('fa-eye-slash');
    }
  } else {
    tokenEl.type = 'password';
    if (iconEl) {
      iconEl.classList.remove('fa-eye-slash');
      iconEl.classList.add('fa-eye');
    }
  }
}
