function getCountryFlagEmoji(cc, countryName) {
  if (cc && cc.length === 2) {
    try {
      const codePoints = cc.toUpperCase().split('').map(c => 127397 + c.charCodeAt(0));
      return String.fromCodePoint(...codePoints);
    } catch (e) {}
  }
  const c = (countryName || '').toLowerCase();
  if (c.includes('portugal')) return '🇵🇹';
  if (c.includes('espanha') || c.includes('españa') || c.includes('spain')) return '🇪🇸';
  if (c.includes('brasil') || c.includes('brazil')) return '🇧🇷';
  if (c.includes('chile')) return '🇨🇱';
  if (c.includes('frança') || c.includes('france')) return '🇫🇷';
  if (c.includes('alemanha') || c.includes('germany')) return '🇩🇪';
  if (c.includes('itália') || c.includes('italy')) return '🇮🇹';
  if (c.includes('reino unido') || c.includes('united kingdom') || c.includes('uk')) return '🇬🇧';
  if (c.includes('estados unidos') || c.includes('usa')) return '🇺🇸';
  if (c.includes('méxico') || c.includes('mexico')) return '🇲🇽';
  if (c.includes('angola')) return '🇦🇴';
  if (c.includes('moçambique') || c.includes('mozambique')) return '🇲🇿';
  if (c.includes('cabo verde')) return '🇨🇻';
  if (c.includes('china') || c.includes('macau')) return '🇲🇴';
  if (c.includes('timor')) return '🇹🇱';
  return '🌐';
}
window.getCountryFlagEmoji = getCountryFlagEmoji;

function splitSmartAddressLines(direcao1, direcao2, numero) {
  let d1 = (direcao1 || '').trim();
  let d2 = (direcao2 || '').trim();
  let num = (numero || '').trim();

  // Padrões de Zona Secundária (Polígonos, Parques, Edifícios, etc.)
  const secondaryPatterns = [
    /\(?\s*(Pol[íi]gono\s+Industrial\s+[^,\)\-]+)\s*\)?/i,
    /\(?\s*(Zona\s+Industrial\s+[^,\)\-]+)\s*\)?/i,
    /\(?\s*(Parque\s+(?:Empresarial|Tecnol[óo]gico|de\s+Neg[óo]cios|Industrial)\s+[^,\)\-]+)\s*\)?/i,
    /\(?\s*(Centro\s+Empresarial\s+[^,\)\-]+)\s*\)?/i,
    /\(?\s*(Edif[íi]cio\s+[^,\)\-]+)\s*\)?/i,
    /\(?\s*(Torre\s+[A-Za-z0-9\s]+)\s*\)?/i,
    /\(?\s*(Bloco\s+[A-Za-z0-9\s]+)\s*\)?/i,
    /\(?\s*(Lote\s+[A-Za-z0-9\s]+)\s*\)?/i,
    /\(?\s*(Urbaniza[çc][ãa]o\s+[^,\)\-]+)\s*\)?/i
  ];

  if (!d2) {
    for (const pat of secondaryPatterns) {
      const match = d1.match(pat);
      if (match) {
        d2 = match[1].trim();
        d1 = d1.replace(match[0], '').replace(/^[\s,\-\/]+|[\s,\-\/]+$/g, '').trim();
        break;
      }
    }
  }

  // Extrair número se não foi fornecido
  if (!num) {
    const numMatch = d1.match(/,\s*(?:n\.?[ºo]?\s*)?(\d+[A-Za-z]?)\s*$/i) || d1.match(/\s+n\.?[ºo]?\s*(\d+[A-Za-z]?)\s*$/i);
    if (numMatch) {
      num = numMatch[1];
      d1 = d1.slice(0, numMatch.index).trim();
    }
  }

  return { direcao1: d1, direcao2: d2, numero: num };
}
window.splitSmartAddressLines = splitSmartAddressLines;


