function normalizeSearchTerm(str) {
  if (!str) return '';
  return str.toString()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function cleanCompanySearchName(str) {
  if (!str) return '';
  return str
    .replace(/\b(s\.?l\.?u?\.?|s\.?a\.?u?\.?|lda\.?|unipessoal|limitada|sociedad an[oó]nima|sociedad limitada|ltd\.?|gmbh|inc\.?|llc|corp\.?)\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function resolveEntityFromLocalDirectory(entityName, ministerio, targetPais) {
  const normName = normalizeSearchTerm(entityName);
  const normClean = normalizeSearchTerm(cleanCompanySearchName(entityName));
  const normMin = normalizeSearchTerm(ministerio);

  const rawParts = (entityName || '').split(/[\/\-\|]/).map(s => s.trim()).filter(Boolean);
  const searchCandidates = [];
  if (rawParts.length > 1) {
    searchCandidates.push(normalizeSearchTerm(rawParts[rawParts.length - 1]));
    searchCandidates.push(normalizeSearchTerm(cleanCompanySearchName(rawParts[rawParts.length - 1])));
    searchCandidates.push(normalizeSearchTerm(rawParts[0]));
  }
  if (normClean && normClean !== normName) searchCandidates.push(normClean);
  if (normName) searchCandidates.push(normName);

  function matchAlias(target, alias) {
    if (!target || !alias) return false;
    const t = normalizeSearchTerm(target);
    const a = normalizeSearchTerm(alias);
    if (!t || !a) return false;
    if (t === a) return true;
    if (a.length <= 4) {
      return t.split(/\s+/).includes(a);
    }
    return t.includes(a) || a.includes(t);
  }

  // Pass 1: Busca nos candidatos da entidade
  for (const cand of searchCandidates) {
    if (!cand || cand.length < 2) continue;
    for (const item of SIGEC_PT_INSTITUTIONAL_DIRECTORY) {
      for (const alias of item.aliases) {
        if (matchAlias(cand, alias)) {
          return item;
        }
      }
    }
  }

  // Pass 2: Busca no ministério
  if (normMin && normMin.length >= 3) {
    for (const item of SIGEC_PT_INSTITUTIONAL_DIRECTORY) {
      for (const alias of item.aliases) {
        if (matchAlias(normMin, alias)) {
          return item;
        }
      }
    }
  }

  return null;
}


function cleanCompanySearchName(rawName) {
  if (!rawName || typeof rawName !== 'string') return '';
  let cleaned = rawName.trim();
  cleaned = cleaned.replace(/\s*\([A-Z0-9\s\.\-]+\)$/i, '');
  cleaned = cleaned.replace(/\b(S\.L\.U\.?|S\.L\.?|S\.A\.U\.?|S\.A\.?|S\.C\.P\.?|S\.C\.?|S\.A\.R\.L\.?|S\.A\.S\.?|Lda\.?|Limitada|Sociedade An[oó]nima|GmbH|AG|Ltd\.?|Limited|Inc\.?|Incorporated|LLC|Corp\.?|Corporation)\b/gi, '');
  cleaned = cleaned.replace(/\b(Sucursal em Portugal|Sucursal Portugal|Sucursal de Espa[ñn]a)\b/gi, '');
  cleaned = cleaned.replace(/\s{2,}/g, ' ').trim();
  return cleaned;
}

function resolveAllEntitiesFromLocalDirectory(query, ministerio, targetCountry) {
  if (!query || typeof query !== 'string' || query.trim().length < 2) return [];
  const rawParts = query.split(/[\/\-\|]/).map(p => p.trim()).filter(p => p.length > 2);
  const cleanedQuery = cleanCompanySearchName(query);

  const searchCandidates = [
    query.trim(),
    cleanedQuery,
    ...rawParts
  ].filter(Boolean);

  const normMin = (ministerio || '').trim();

  function matchAlias(target, alias) {
    if (!target || !alias) return false;
    const t = normalizeSearchTerm(target);
    const a = normalizeSearchTerm(alias);
    if (!t || !a) return false;
    if (t === a) return true;
    if (a.length <= 4) {
      return t.split(/\s+/).includes(a);
    }
    return t.includes(a) || a.includes(t);
  }

  const results = [];
  const seenKeys = new Set();

  for (const cand of searchCandidates) {
    if (!cand || cand.length < 2) continue;
    for (const item of SIGEC_PT_INSTITUTIONAL_DIRECTORY) {
      for (const alias of item.aliases) {
        if (matchAlias(cand, alias)) {
          const key = ((item.pais || '') + '|' + (item.localidade || '') + '|' + (item.direcao1 || '')).toLowerCase();
          if (!seenKeys.has(key)) {
            seenKeys.add(key);
            results.push(item);
          }
          break;
        }
      }
    }
  }

  // Busca secundária por ministério
  if (normMin && normMin.length >= 3) {
    for (const item of SIGEC_PT_INSTITUTIONAL_DIRECTORY) {
      for (const alias of item.aliases) {
        if (matchAlias(normMin, alias)) {
          const key = ((item.pais || '') + '|' + (item.localidade || '') + '|' + (item.direcao1 || '')).toLowerCase();
          if (!seenKeys.has(key)) {
            seenKeys.add(key);
            results.push(item);
          }
          break;
        }
      }
    }
  }

  return results;
}

function resolveEntityFromLocalDirectory(query, ministerio, targetCountry) {
  const matches = resolveAllEntitiesFromLocalDirectory(query, ministerio, targetCountry);
  return matches.length > 0 ? matches[0] : null;
}

async function resolveEntityCandidatesFromNominatim(query, targetCountry) {
  // ─── Versão filtrada: só aceita nós OSM do tipo escritório/empresa ───
  if (!query || typeof query !== 'string' || query.trim().length < 2) return [];
  const rawParts = query.split(/[\/\-\|]/).map(p => p.trim()).filter(p => p.length > 2);
  const cleanedQuery = cleanCompanySearchName(query);

  const baseCandidates = [];
  if (rawParts.length > 1) {
    baseCandidates.push(cleanCompanySearchName(rawParts[rawParts.length - 1]));
    baseCandidates.push(rawParts[rawParts.length - 1]);
    baseCandidates.push(cleanCompanySearchName(rawParts[0]));
  }
  if (cleanedQuery && cleanedQuery !== query) baseCandidates.push(cleanedQuery);
  baseCandidates.push(query.trim());

  const countryParam = (targetCountry || '').trim();
  const candidates = [];
  const seenKeys = new Set();

  for (const cand of baseCandidates) {
    if (!cand || cand.length < 2) continue;
    const urlsToTry = [];
    if (countryParam && countryParam.toLowerCase() !== 'portugal') {
      urlsToTry.push('https://nominatim.openstreetmap.org/search?q=' + encodeURIComponent(cand + ', ' + countryParam) + '&format=json&addressdetails=1&extratags=1&limit=8');
    }
    urlsToTry.push('https://nominatim.openstreetmap.org/search?q=' + encodeURIComponent(cand) + '&format=json&addressdetails=1&extratags=1&limit=8');
    if (!countryParam || countryParam.toLowerCase() === 'portugal') {
      urlsToTry.push('https://nominatim.openstreetmap.org/search?q=' + encodeURIComponent(cand + ', Portugal') + '&format=json&addressdetails=1&extratags=1&limit=8');
    }

    for (const url of urlsToTry) {
      try {
        const resp = await fetch(url, { headers: { 'Accept-Language': 'pt,es,fr,en;q=0.9' } });
        if (!resp.ok) continue;
        const json = await resp.json();
        if (!Array.isArray(json) || json.length === 0) continue;

        for (const item of json) {
          if (!item || !item.address) continue;

          // ── FILTRO: só aceitar resultados do tipo "escritório / empresa" ──
          const tags = item.extratags || {};
          const isOfficeType = (
            item.class === 'office' ||
            item.type === 'office' ||
            item.type === 'company' ||
            item.type === 'commercial' ||
            item.type === 'government' ||
            tags.office ||
            tags['amenity'] === 'company' ||
            tags['building'] === 'commercial' ||
            tags['building'] === 'office' ||
            tags.wikidata
          );
          if (!isOfficeType) continue;
          // ─────────────────────────────────────────────────────────────────

          const addr = item.address;
          const street = addr.road || addr.pedestrian || addr.street || addr.neighbourhood || addr.suburb || (item.display_name ? item.display_name.split(',')[0] : '') || '';
          const city = addr.city || addr.town || addr.municipality || addr.village || addr.county || addr.state || '';
          const postcode = addr.postcode || '';
          const detectedCountry = addr.country || countryParam || 'Portugal';
          const detectedCountryCode = (addr.country_code || '').toLowerCase();
          if (!street && !postcode && !city) continue;

          const key = (detectedCountry + '|' + city + '|' + street).toLowerCase();
          if (seenKeys.has(key)) continue;
          seenKeys.add(key);

          let phone = tags['contact:phone'] || tags.phone || tags['phone:mobile'] || addr.phone || '';
          let website = tags['contact:website'] || tags.website || tags.url || '';

          if (tags.wikidata && (!website || !phone) && candidates.length < 2) {
            try {
              const wResp = await fetch('https://www.wikidata.org/wiki/Special:EntityData/' + tags.wikidata + '.json');
              if (wResp.ok) {
                const wData = await wResp.json();
                const ec = wData?.entities?.[tags.wikidata]?.claims;
                if (!website && ec?.P856?.[0]?.mainsnak?.datavalue?.value) website = ec.P856[0].mainsnak.datavalue.value;
                if (!phone && ec?.P1329?.[0]?.mainsnak?.datavalue?.value) phone = ec.P1329[0].mainsnak.datavalue.value;
              }
            } catch(_) {}
          }

          candidates.push({
            nome: item.name || query,
            direcao1: street,
            direcao2: '',
            numero: addr.house_number || '',
            andar: '',
            codigoPostal: postcode,
            localidade: city,
            pais: detectedCountry,
            countryCode: detectedCountryCode,
            flag: getCountryFlagEmoji(detectedCountryCode, detectedCountry),
            telefone: phone,
            website: website,
            fonteUrl: 'https://www.openstreetmap.org/' + (item.osm_type || 'node') + '/' + (item.osm_id || ''),
            provider: 'OpenStreetMap (Sede Verificada)'
          });
          if (candidates.length >= 6) break;
        }
      } catch(_) {}
      if (candidates.length >= 6) break;
    }
    if (candidates.length >= 6) break;
  }
  return candidates;
}

// ─── Wikidata (Wikipedia) — fonte principal de dados reais de empresas ───────
async function resolveEntityCandidatesFromWikidata(query, targetCountry) {
  if (!query || typeof query !== 'string' || query.trim().length < 2) return [];

  const candidates = [];
  try {
    // ── PASSO 1: pesquisa por nome → IDs de entidades ──────────────────────
    const searchUrl = 'https://www.wikidata.org/w/api.php?action=wbsearchentities' +
      '&search=' + encodeURIComponent(query.trim()) +
      '&language=pt&type=item&format=json&origin=*&limit=8';

    const sResp = await fetch(searchUrl);
    if (!sResp.ok) return [];
    const sData = await sResp.json();
    const searchResults = sData?.search || [];
    if (!searchResults.length) {
      // Tentar também em inglês
      const searchUrlEn = 'https://www.wikidata.org/w/api.php?action=wbsearchentities' +
        '&search=' + encodeURIComponent(cleanCompanySearchName(query) || query.trim()) +
        '&language=en&type=item&format=json&origin=*&limit=8';
      const sRespEn = await fetch(searchUrlEn);
      if (sRespEn.ok) {
        const sDataEn = await sRespEn.json();
        (sDataEn?.search || []).forEach(r => { if (!searchResults.find(x => x.id === r.id)) searchResults.push(r); });
      }
    }
    if (!searchResults.length) return [];

    // ── PASSO 2: obter claims/labels de todas as entidades de uma vez ──────
    const ids = searchResults.map(r => r.id).join('|');
    const entUrl = 'https://www.wikidata.org/w/api.php?action=wbgetentities' +
      '&ids=' + encodeURIComponent(ids) +
      '&props=claims|labels|descriptions&languages=pt|en|es|fr&format=json&origin=*';

    const eResp = await fetch(entUrl);
    if (!eResp.ok) return [];
    const eData = await eResp.json();
    const entities = eData?.entities || {};

    // IDs secundários que precisamos de resolver (país P17, cidade-sede P159)
    const secondaryIds = new Set();
    for (const [, ent] of Object.entries(entities)) {
      const cl = ent.claims || {};
      const getQid = (prop) => cl?.[prop]?.[0]?.mainsnak?.datavalue?.value?.id;
      const pid17  = getQid('P17');  // país
      const pid159 = getQid('P159'); // cidade da sede
      if (pid17)  secondaryIds.add(pid17);
      if (pid159) secondaryIds.add(pid159);
    }

    // ── PASSO 3: resolver IDs secundários (país, cidade) num único pedido ──
    const secondaryEntities = {};
    if (secondaryIds.size > 0) {
      try {
        const secUrl = 'https://www.wikidata.org/w/api.php?action=wbgetentities' +
          '&ids=' + encodeURIComponent([...secondaryIds].join('|')) +
          '&props=claims|labels&languages=pt|en&format=json&origin=*';
        const secResp = await fetch(secUrl);
        if (secResp.ok) {
          const secData = await secResp.json();
          Object.assign(secondaryEntities, secData?.entities || {});
        }
      } catch(_) {}
    }

    function getLabel(ent, fallback) {
      if (!ent || !ent.labels) return fallback || '';
      return ent.labels?.pt?.value || ent.labels?.en?.value || ent.labels?.es?.value || fallback || '';
    }

    function getClaimStr(claims, prop) {
      const snak = claims?.[prop]?.[0]?.mainsnak?.datavalue?.value;
      if (!snak) return '';
      if (typeof snak === 'string') return snak;
      if (snak?.text) return snak.text;
      return '';
    }

    function getClaimQid(claims, prop) {
      return claims?.[prop]?.[0]?.mainsnak?.datavalue?.value?.id || '';
    }

    // ── PASSO 4: construir candidatos ──────────────────────────────────────
    for (const [qid, ent] of Object.entries(entities)) {
      if (!ent || ent.missing) continue;
      const cl = ent.claims || {};

      // Só entidades com pelo menos morada ou website
      const website   = getClaimStr(cl, 'P856');
      const phone     = getClaimStr(cl, 'P1329');
      const streetRaw = getClaimStr(cl, 'P6375'); // endereço em formato texto
      const postcode  = getClaimStr(cl, 'P281');
      const countryQid= getClaimQid(cl, 'P17');
      const hqQid     = getClaimQid(cl, 'P159');

      const countryEnt = countryQid ? secondaryEntities[countryQid] : null;
      const hqEnt      = hqQid ? secondaryEntities[hqQid] : null;

      const countryName = getLabel(countryEnt, '');
      const hqCity      = getLabel(hqEnt, '');

      // Código ISO do país (P297 nas claims do país)
      const countryIso  = countryEnt ? (getClaimStr(countryEnt.claims || {}, 'P297') || '').toLowerCase() : '';

      // Filtrar por país se especificado
      if (targetCountry && targetCountry.trim() && countryName && !countryName.toLowerCase().includes(targetCountry.trim().toLowerCase())) {
        // permitir mesmo assim se não houver pais preenchido no Wikidata
        if (countryName) continue;
      }

      const entityLabel = getLabel(ent, query);

      if (!streetRaw && !postcode && !hqCity && !website) continue;

      // Separar número de rua do nome da rua
      let direcao1 = streetRaw || '';
      let numero   = '';
      const numMatch = streetRaw.match(/^(.*?),?\s+(\d+[A-Za-z]?)\s*$/);
      if (numMatch) { direcao1 = numMatch[1].trim(); numero = numMatch[2]; }

      const pais = countryName || targetCountry || '';
      const fonteUrl = 'https://www.wikidata.org/wiki/' + qid;

      candidates.push({
        nome:        entityLabel,
        direcao1:    direcao1,
        direcao2:    '',
        numero:      numero,
        andar:       '',
        codigoPostal:postcode,
        localidade:  hqCity,
        pais:        pais,
        countryCode: countryIso,
        flag:        getCountryFlagEmoji(countryIso, pais),
        telefone:    phone,
        website:     website,
        fonteUrl:    fonteUrl,
        provider:    '🌐 Wikipedia / Wikidata (Verificado)'
      });

      if (candidates.length >= 6) break;
    }
  } catch(err) {
    console.warn('Wikidata resolver erro:', err);
  }
  return candidates;
}

// ─── OpenCorporates — registo de empresas de 140+ países ────────────────────
async function resolveEntityCandidatesFromOpenCorporates(query, targetCountry) {
  if (!query || query.trim().length < 2) return [];
  const candidates = [];
  try {
    // Mapa de países para códigos de jurisdição OpenCorporates
    const countryToJurisdiction = {
      'portugal': 'pt', 'espanha': 'es', 'spain': 'es',
      'france': 'fr', 'franca': 'fr', 'frança': 'fr',
      'germany': 'de', 'alemanha': 'de',
      'united kingdom': 'gb', 'reino unido': 'gb',
      'italy': 'it', 'itália': 'it', 'italia': 'it',
      'netherlands': 'nl', 'países baixos': 'nl',
      'belgium': 'be', 'bélgica': 'be',
      'brazil': 'br', 'brasil': 'br',
      'usa': 'us', 'estados unidos': 'us', 'united states': 'us',
      'canada': 'ca', 'canadá': 'ca',
      'australia': 'au', 'austrália': 'au',
      'switzerland': 'ch', 'suíça': 'ch', 'suica': 'ch',
      'austria': 'at', 'áustria': 'at',
      'ireland': 'ie', 'irlanda': 'ie',
      'luxembourg': 'lu', 'luxemburgo': 'lu',
      'denmark': 'dk', 'dinamarca': 'dk',
      'sweden': 'se', 'suécia': 'se',
      'norway': 'no', 'noruega': 'no',
      'finland': 'fi', 'finlândia': 'fi',
      'poland': 'pl', 'polónia': 'pl',
    };

    const cleanQ = cleanCompanySearchName(query) || query.trim();
    let searchUrl = 'https://api.opencorporates.com/v0.4/companies/search?q=' +
      encodeURIComponent(cleanQ) + '&format=json&per_page=8';

    // Se há país, filtrar por jurisdição
    const jCode = targetCountry ? countryToJurisdiction[(targetCountry || '').toLowerCase().trim()] : null;
    if (jCode) searchUrl += '&jurisdiction_code=' + jCode;

    const resp = await fetch(searchUrl, {
      headers: { 'Accept': 'application/json' }
    });
    if (!resp.ok) return [];
    const data = await resp.json();
    const companies = data?.results?.companies || [];

    for (const item of companies) {
      const co = item?.company;
      if (!co) continue;
      const regAddr = co.registered_address || {};
      const street = regAddr.street_address || '';
      const city   = regAddr.locality || regAddr.city || '';
      const post   = regAddr.postal_code || '';
      const country= regAddr.country || targetCountry || '';
      const cc     = (country || '').toLowerCase().startsWith('port') ? 'pt'
                   : (country || '').toLowerCase().startsWith('esp')  ? 'es'
                   : (co.jurisdiction_code || '').split('_')[0] || '';

      if (!street && !city && !post) continue;

      const key = (country + '|' + city + '|' + street).toLowerCase();
      candidates.push({
        nome:        co.name || query,
        direcao1:    street,
        direcao2:    '',
        numero:      '',
        andar:       '',
        codigoPostal:post,
        localidade:  city,
        pais:        country,
        countryCode: cc,
        flag:        getCountryFlagEmoji(cc, country),
        telefone:    '',
        website:     co.homepage_url || '',
        fonteUrl:    co.opencorporates_url || 'https://opencorporates.com',
        provider:    '🏢 OpenCorporates (Registo Oficial de Empresas)'
      });
      if (candidates.length >= 5) break;
    }
  } catch(err) {
    console.warn('OpenCorporates erro:', err);
  }
  return candidates;
}

// ─── DuckDuckGo Instant Answer — website + descrição da empresa ──────────────
async function resolveEntityWebsiteFromDDG(query) {
  if (!query || query.trim().length < 2) return null;
  try {
    const url = 'https://api.duckduckgo.com/?q=' + encodeURIComponent(query.trim()) +
      '&format=json&no_redirect=1&no_html=1&skip_disambig=1';
    const resp = await fetch(url);
    if (!resp.ok) return null;
    const data = await resp.json();

    const website = data?.AbstractURL || data?.Website || '';
    const heading = data?.Heading || '';
    const abstract= data?.Abstract || data?.AbstractText || '';
    const image   = data?.Image || '';
    // Extrair domínio do website para usar como fonteUrl
    const fonteUrl = website || (data?.Results?.[0]?.FirstURL) || '';

    if (!website && !fonteUrl) return null;

    return { website, heading, abstract, fonteUrl };
  } catch(_) {
    return null;
  }
}

function parseSmartAddress(text) {
  if (!text || typeof text !== "string") return null;
  const raw = text.trim();
  if (!raw) return null;

  let direcao1 = "";
  let direcao2 = "";
  let numero = "";
  let andar = "";
  let codigoPostal = "";
  let localidade = "";
  let pais = "";
  let contribuinte = "";
  let telefone = "";
  let email = "";
  let website = "";

  let workingText = raw;

  // 1. Extração de Email
  const emailMatch = workingText.match(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/);
  if (emailMatch) {
    email = emailMatch[0].trim();
    workingText = workingText.replace(emailMatch[0], " ");
  }

  // 2. Extração de Website
  const webMatch = workingText.match(/\b(?:https?:\/\/|www\.)[^\s,;]+\b/i);
  if (webMatch) {
    website = webMatch[0].trim();
    workingText = workingText.replace(webMatch[0], " ");
  }

  // 3. Extração Explícita de Telefone quando tem rótulo (ex: Tel:, Telefone:, Tlm:, Mobile:, Fixo:)
  const labeledTelMatch = workingText.match(/\b(?:Tel(?:efone)?|Tlm|Telemóvel|Phone|Mobile|Fixo)[\s:.-]*(?:(?:\+|00)351[\s.-]*)?((?:2\d{2}|9[1236]\d)[\s.-]*\d{3}[\s.-]*\d{3}|\d{9})\b/i);
  if (labeledTelMatch) {
    telefone = labeledTelMatch[0].replace(/^[^\d+]+/, '').trim();
    workingText = workingText.replace(labeledTelMatch[0], " ");
  }

  // 4. Extração de Contribuinte (NIF / NIPC / CIF / VAT / Identificação Fiscal)
  // 4a. Com rótulo explícito (ex: NIF: 502 123 456, NIPC: 502123456, Contribuinte: 502123456, CIF: B-12345678, PT502123456)
  const nifPrefixMatch = workingText.match(/\b(?:NIF|NIPC|Contribuinte|Identifica[çc][ãa]o\s*Fiscal|CIF|VAT|IVA)[\s:.-]*(?:PT|ES)?[\s:.-]*([A-Z0-9][A-Z0-9\s.-]{7,11}[A-Z0-9])\b/i);
  if (nifPrefixMatch) {
    const rawVal = nifPrefixMatch[1].replace(/[\s.-]/g, "").toUpperCase();
    if (/^\d{9}$/.test(rawVal) || /^[A-HJ-NP-SUVW]\d{7}[0-9A-J]$/.test(rawVal)) {
      contribuinte = rawVal;
      workingText = workingText.replace(nifPrefixMatch[0], " ");
    }
  }

  // 4b. Formato com prefixo internacional avulso (ex: PT502123456 ou ESB12345678)
  if (!contribuinte) {
    const vatEuMatch = workingText.match(/\b(?:PT\s*([125689]\d{8})|ES\s*([A-HJ-NP-SUVW]\d{7}[0-9A-J]))\b/i);
    if (vatEuMatch) {
      contribuinte = (vatEuMatch[1] || vatEuMatch[2]).replace(/\s+/g, "").toUpperCase();
      workingText = workingText.replace(vatEuMatch[0], " ");
    }
  }

  // 4c. NIF Coletivo Português (NIPC) avulso: inicia sempre por 5 ou 6 (nunca é telefone!)
  if (!contribuinte) {
    const nifPtNipc = workingText.match(/\b([56]\d{8})\b/);
    if (nifPtNipc) {
      contribuinte = nifPtNipc[1];
      workingText = workingText.replace(nifPtNipc[0], " ");
    }
  }

  // 4d. CIF Espanhol avulso (Letra + 7 dígitos + Letra/Dígito)
  if (!contribuinte) {
    const cifEsAvulso = workingText.match(/\b([A-HJ-NP-SUVW]\d{7}[0-9A-J])\b/i);
    if (cifEsAvulso) {
      contribuinte = cifEsAvulso[1].toUpperCase();
      workingText = workingText.replace(cifEsAvulso[0], " ");
    }
  }

  // 5. Extração de Telefone Avulso (se ainda não extraído no passo 3)
  if (!telefone) {
    const telMatch = workingText.match(/(?:(?:\+|00)351[\s.-]*)?(?:2\d{2}|9[1236]\d)[\s.-]*\d{3}[\s.-]*\d{3}\b/) ||
                     workingText.match(/(?:(?:\+|00)34[\s.-]*)?(?:[689]\d{2})[\s.-]*\d{3}[\s.-]*\d{3}\b/);
    if (telMatch) {
      telefone = telMatch[0].trim();
      workingText = workingText.replace(telMatch[0], " ");
    }
  }

  // 4e. NIF Singular Português avulso (1, 2, 8, 9) caso sobre após telefone e CP
  if (!contribuinte) {
    const nifPtSingular = workingText.match(/\b([128]\d{8})\b/);
    if (nifPtSingular) {
      contribuinte = nifPtSingular[1];
      workingText = workingText.replace(nifPtSingular[0], " ");
    }
  }

  // 6. Código Postal e País
  const cpPtMatch = workingText.match(/\b(\d{4}-\d{3})\b/);
  const cpEsMatch = workingText.match(/\b(\d{5})\b/);
  if (cpPtMatch) {
    codigoPostal = cpPtMatch[1];
    pais = "Portugal";
    workingText = workingText.replace(cpPtMatch[0], " ");
  } else if (cpEsMatch) {
    codigoPostal = cpEsMatch[1];
    pais = "Espanha";
    workingText = workingText.replace(cpEsMatch[0], " ");
  }

  const paises = [
    { name: "Portugal", regex: /\b(?:Portugal)\b/i },
    { name: "Espanha", regex: /\b(?:Espanha|España|Spain)\b/i },
    { name: "França", regex: /\b(?:França|France)\b/i },
    { name: "Reino Unido", regex: /\b(?:Reino Unido|United Kingdom)\b/i }
  ];
  for (const p of paises) {
    if (p.regex.test(workingText)) {
      pais = p.name;
      workingText = workingText.replace(p.regex, " ");
      break;
    }
  }

  // 6. Localidade a seguir ao código postal
  if (codigoPostal) {
    const afterCpRegex = new RegExp(codigoPostal + "\\s*[-–,]?\\s*([A-Za-zÀ-Úà-ú\\-\\s]+?)(?=[,\\-–;.\\n\\|]|$)", "i");
    const afterCpMatch = raw.match(afterCpRegex);
    if (afterCpMatch && afterCpMatch[1]) {
      let loc = afterCpMatch[1].replace(/\b(?:Portugal|Espanha|España|Spain|França|France|Tel|NIF|CIF|Email|Website|Contribuinte)\b/gi, "").trim();
      if (loc && loc.length > 1) {
        localidade = loc;
      }
    }
  }

  // 7. Andar / Fração
  const andarMatch = workingText.match(/\b(\d+[ºªo]\s*(?:andar|Dto|Esq|Frt|frente|piso)?|R\/C|rés-do-chão|Planta\s*\d+|Piso\s*\d+)\b/i);
  if (andarMatch) {
    andar = andarMatch[1].trim();
    workingText = workingText.replace(andarMatch[0], " ");
  }

  // 8. Direção 2 (Polígono Industrial, Edifício, Zona, etc.)
  const d2Match = raw.match(/\b((?:Polígono|Poligono|Parque|Edifício|Edificio|Bloco|Torre|Urbanização|Urbanizacao|Centro Empresarial|Zona Industrial)[\s\wÀ-Úà-ú\-\–ºª]+?)(?=[,;\n]|$)/i);
  if (d2Match) {
    direcao2 = d2Match[1].trim();
    workingText = workingText.replace(d2Match[0], " ");
  }

  // 9. Número da porta
  const numMatch = workingText.match(/\b(?:n\.?[ºo]?\s*|nº\s*)?(\d+[A-Za-z]?)\b/i);
  if (numMatch) {
    numero = numMatch[1];
  }

  // 10. Limpar rótulos comuns (Tel:, Email:, etc.)
  workingText = workingText.replace(/\b(?:Tel|Telefone|Email|Web|Website|NIF|CIF|NIPC|Contribuinte|Morada|Direção)[\s:.-]*/gi, " ");
  if (codigoPostal) workingText = workingText.replace(codigoPostal, " ");
  if (localidade) workingText = workingText.replace(new RegExp("\\b" + localidade + "\\b", "gi"), " ");

  // 11. Linha da Rua (Direção 1)
  const parts = workingText.split(/[,;\n]+/).map(s => s.trim().replace(/^[,;\s\-.:]+|[,;\s\-.:]+$/g, "")).filter(s => s.length > 2);
  if (parts.length > 0) {
    direcao1 = parts[0];
    if (numero) {
      const numEndRegex = new RegExp("\\s*,?\\s*(?:n\\.?[ºo]?\\s*)?" + numero + "\\s*$", "i");
      direcao1 = direcao1.replace(numEndRegex, "").trim();
    }
  }

  return {
    direcao1: direcao1 || raw,
    direcao2,
    numero,
    andar,
    codigoPostal,
    localidade,
    pais: pais || "Portugal",
    contribuinte,
    telefone,
    email,
    website,
    provider: "Colagem Inteligente (Google Search)"
  };
}
window.parseSmartAddress = parseSmartAddress;

function applySmartPasteFromInput() {
  const inp = document.getElementById("aiSmartPasteInput");
  if (!inp || !inp.value.trim()) {
    if (typeof showToast === "function") showToast("Por favor, cole primeiro a morada copiada do Google.", "warning");
    return;
  }
  handleSmartPasteInput(inp.value.trim(), true);
}
window.applySmartPasteFromInput = applySmartPasteFromInput;

function handleSmartPasteInput(text, showNotification = false) {
  if (!text || text.trim().length < 4) return;
  const parsed = parseSmartAddress(text);
  if (!parsed) return;

  const currentEntity = (currentPendingContext && currentPendingContext.entityName) ? currentPendingContext.entityName : "Entidade";
  pendingAiAddressData = Object.assign({}, pendingAiAddressData || {}, parsed, {
    nome: currentEntity,
    website: parsed.website || pendingAiAddressData?.website || "",
    email: parsed.email || pendingAiAddressData?.email || "",
    telefone: parsed.telefone || pendingAiAddressData?.telefone || "",
    contribuinte: parsed.contribuinte || pendingAiAddressData?.contribuinte || "",
    fonteUrl: "https://www.google.com/search?q=" + encodeURIComponent(currentEntity + " morada")
  });

  updateAiModalPreview(pendingAiAddressData);

  const successEl = document.getElementById("aiSmartPasteSuccessMsg");
  if (successEl) {
    let msg = "Morada preenchida com sucesso!";
    if (parsed.contribuinte) {
      msg = "Morada e Contribuinte (" + parsed.contribuinte + ") preenchidos com sucesso!";
    }
    successEl.innerHTML = "<i class=\"fa-solid fa-circle-check\"></i> " + msg + " Pode rever e confirmar.";
    successEl.style.display = "block";
  }
  if (showNotification && typeof showToast === "function") {
    const toastMsg = parsed.contribuinte
      ? "Morada e Contribuinte (" + parsed.contribuinte + ") decompostos com sucesso!"
      : "Morada decomposta com sucesso! Pode rever e aplicar.";
    showToast(toastMsg, "success");
  }
}
window.handleSmartPasteInput = handleSmartPasteInput;
function renderAiCandidateCards() {
  const container = document.getElementById("aiCandidatesCardsList");
  if (!container) return;
  container.innerHTML = "";

  if (!availableAiCandidates || availableAiCandidates.length === 0) {
    const multiContainer = document.getElementById("aiMultipleCandidatesContainer");
    if (multiContainer) multiContainer.style.display = "none";
    container.innerHTML = "";
    return;
  }
  availableAiCandidates.forEach((cand, idx) => {
    const isSelected = (idx === selectedAiCandidateIndex);
    const card = document.createElement('div');
    card.className = 'ai-candidate-card';
    card.style.cssText = `
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.5rem 0.75rem;
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.2s;
      border: ${isSelected ? '2px solid #4f46e5' : '1px solid #cbd5e1'};
      background: ${isSelected ? '#eef2ff' : '#ffffff'};
      box-shadow: ${isSelected ? '0 2px 6px rgba(79, 70, 229, 0.15)' : 'none'};
    `;

    const left = document.createElement('div');
    left.style.cssText = 'display: flex; align-items: center; gap: 0.65rem; min-width: 0;';

    const flagEl = document.createElement('div');
    flagEl.style.cssText = 'font-size: 1.35rem; line-height: 1; flex-shrink: 0;';
    flagEl.textContent = cand.flag || '🌐';

    const info = document.createElement('div');
    info.style.cssText = 'min-width: 0; overflow: hidden;';

    const title = document.createElement('div');
    title.style.cssText = `font-size: 0.84rem; font-weight: 700; color: ${isSelected ? '#312e81' : '#1e293b'}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;`;
    title.innerHTML = `${cand.pais || 'Global'} <span style="font-weight: 600; color: #475569;">• ${cand.localidade || 'Sede'}</span>`;

    const sub = document.createElement('div');
    sub.style.cssText = 'font-size: 0.74rem; color: #64748b; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;';
    const addressPreview = [cand.direcao1, cand.numero ? 'Nº ' + cand.numero : '', cand.direcao2, cand.codigoPostal].filter(Boolean).join(', ') || '(Morada registada)';
    sub.textContent = addressPreview;

    info.appendChild(title);
    info.appendChild(sub);
    left.appendChild(flagEl);
    left.appendChild(info);

    const right = document.createElement('div');
    right.style.cssText = 'display: flex; align-items: center; gap: 0.4rem; flex-shrink: 0; margin-left: 0.5rem;';

    if (cand.website) {
      const wBadge = document.createElement('span');
      wBadge.title = 'Website disponível';
      wBadge.style.cssText = 'font-size: 0.68rem; color: #0284c7; background: #e0f2fe; padding: 2px 5px; border-radius: 4px;';
      wBadge.innerHTML = '<i class="fa-solid fa-globe"></i>';
      right.appendChild(wBadge);
    }

    if (cand.email) {
      const eBadge = document.createElement('span');
      eBadge.title = 'Email: ' + cand.email;
      eBadge.style.cssText = 'font-size: 0.68rem; color: #7c3aed; background: #f3e8ff; padding: 2px 5px; border-radius: 4px;';
      eBadge.innerHTML = '<i class="fa-solid fa-envelope"></i>';
      right.appendChild(eBadge);
    }
    if (cand.telefone) {
      const tBadge = document.createElement('span');
      tBadge.title = 'Telefone disponível';
      tBadge.style.cssText = 'font-size: 0.68rem; color: #16a34a; background: #dcfce7; padding: 2px 5px; border-radius: 4px;';
      tBadge.innerHTML = '<i class="fa-solid fa-phone"></i>';
      right.appendChild(tBadge);
    }

    const checkIcon = document.createElement('i');
    checkIcon.className = isSelected ? 'fa-solid fa-circle-check' : 'fa-regular fa-circle';
    checkIcon.style.cssText = `color: ${isSelected ? '#4f46e5' : '#94a3b8'}; font-size: 1rem; margin-left: 2px;`;
    right.appendChild(checkIcon);

    card.appendChild(left);
    card.appendChild(right);

    card.onclick = () => selectAiCandidate(idx);
    container.appendChild(card);
  });
}

function updateAiModalPreview(cand) {
  if (!cand) return;

  // Website Box
  const foundWebText = document.getElementById('aiFoundWebsiteText');
  const visitBtn = document.getElementById('aiBtnVisitFoundWebsite');
  if (cand.website) {
    if (foundWebText) foundWebText.textContent = cand.website;
    if (visitBtn) {
      visitBtn.style.display = 'inline-flex';
      visitBtn.href = cand.website.startsWith('http') ? cand.website : 'https://' + cand.website;
    }
  } else {
    if (foundWebText) foundWebText.textContent = 'Não identificada na pesquisa direta';
    if (visitBtn) visitBtn.style.display = 'none';
  }

  // Email Box
  const foundEmailText = document.getElementById('aiFoundEmailText');
  const mailBtn = document.getElementById('aiBtnMailFoundEmail');
  if (cand.email) {
    if (foundEmailText) foundEmailText.textContent = cand.email;
    if (mailBtn) {
      mailBtn.style.display = 'inline-flex';
      mailBtn.href = 'mailto:' + cand.email.trim();
    }
  } else {
    if (foundEmailText) foundEmailText.textContent = 'Não identificado';
    if (mailBtn) mailBtn.style.display = 'none';
  }

  // Telefone Box
  const foundTelText = document.getElementById('aiFoundTelefoneText');
  const callBtn = document.getElementById('aiBtnCallFoundTelefone');
  if (cand.telefone) {
    if (foundTelText) foundTelText.textContent = cand.telefone;
    if (callBtn) {
      callBtn.style.display = 'inline-flex';
      callBtn.href = 'tel:' + cand.telefone.replace(/\s+/g, '');
    }
  } else {
    if (foundTelText) foundTelText.textContent = 'Não identificado';
    if (callBtn) callBtn.style.display = 'none';
  }

  // Google Assisted Link
  const googleBtn = document.getElementById('aiBtnGoogleSearchAssisted');
  if (googleBtn) {
    const qTerms = encodeURIComponent((currentPendingContext?.entityName || cand.nome) + ' ' + (cand.pais || '') + ' ' + (cand.localidade || '') + ' sede morada contacto telefone');
    googleBtn.href = `https://www.google.com/search?q=${qTerms}`;
  }

  // Google Maps Assisted Link
  const mapsBtn = document.getElementById('aiBtnGoogleMapsAssisted');
  if (mapsBtn) {
    const mapParts = [
      cand.direcao1,
      cand.numero ? ('nº ' + cand.numero) : '',
      cand.direcao2,
      cand.codigoPostal,
      cand.localidade,
      cand.pais,
      currentPendingContext?.entityName || cand.nome
    ].filter(Boolean);
    const mapQuery = encodeURIComponent(mapParts.join(', '));
    mapsBtn.href = `https://www.google.com/maps/search/?api=1&query=${mapQuery}`;
  }

  // Address Breakdown
  const elDir1 = document.getElementById('aiPreviewDirecao1');
  if (elDir1) elDir1.textContent = cand.direcao1 || '(Não identificada)';

  const elNumAnd = document.getElementById('aiPreviewNumeroAndar');
  let numAndStr = '';
  if (cand.numero) numAndStr += 'Nº ' + cand.numero;
  if (cand.andar) numAndStr += (numAndStr ? ' • ' : '') + cand.andar;
  if (elNumAnd) elNumAnd.textContent = numAndStr || '-';

  const elDir2 = document.getElementById('aiPreviewDirecao2');
  const elDir2Container = document.getElementById('aiPreviewDirecao2Container');
  if (cand.direcao2 && cand.direcao2.trim()) {
    if (elDir2) elDir2.textContent = cand.direcao2.trim();
    if (elDir2Container) elDir2Container.style.display = 'block';
  } else {
    if (elDir2) elDir2.textContent = '-';
    if (elDir2Container) elDir2Container.style.display = 'none';
  }

  const elCp = document.getElementById('aiPreviewCodigoPostal');
  if (elCp) elCp.textContent = cand.codigoPostal || '(Vazio)';

  const elLoc = document.getElementById('aiPreviewLocalidade');
  if (elLoc) elLoc.textContent = cand.localidade || '(Vazio)';

  const elPais = document.getElementById('aiPreviewPais');
  if (elPais) elPais.textContent = cand.pais || 'Portugal';

  // Contribuinte (NIF/NIPC)
  const elContribuinte = document.getElementById('aiPreviewContribuinte');
  const elContribuinteContainer = document.getElementById('aiPreviewContribuinteContainer');
  if (cand.contribuinte && cand.contribuinte.trim() && cand.contribuinte.trim() !== '000000000') {
    if (elContribuinte) elContribuinte.textContent = cand.contribuinte.trim();
    if (elContribuinteContainer) elContribuinteContainer.style.display = 'block';
  } else {
    if (elContribuinte) elContribuinte.textContent = '-';
    if (elContribuinteContainer) elContribuinteContainer.style.display = 'none';
  }

  const elFonte = document.getElementById('aiPreviewFonte');
  if (elFonte) elFonte.textContent = 'Fonte: ' + (cand.fonteUrl || 'Pesquisa Oficial Institucional');

  const elEngine = document.getElementById('aiPreviewEngine');
  if (elEngine) elEngine.textContent = cand.provider || 'Motor de Pesquisa';
}

function selectAiCandidate(idx) {
  if (!availableAiCandidates || !availableAiCandidates[idx]) return;
  selectedAiCandidateIndex = idx;
  const cand = availableAiCandidates[idx];

  pendingAiAddressData = {
    ...cand,
    isEstatal: currentPendingContext?.isEstatal || false,
    tipoCliente: currentPendingContext?.tipoCliente || 'Privado',
    entityName: currentPendingContext?.entityName || cand.nome,
    targetSepIndex: currentPendingContext?.targetSepIndex || 0
  };

  renderAiCandidateCards();
  updateAiModalPreview(cand);
}
window.selectAiCandidate = selectAiCandidate;

async function triggerAiAddressEnrichment() {
  const tipoCliente = document.getElementById('tipoCliente')?.value || 'Privado';
  let entityName = '';
  let ministerio = '';
  let contribuinte = '';
  let existingWebsite = '';
  let existingEmail = '';
  let existingTelefone = '';
  let existingPais = '';
  let isEstatal = (tipoCliente === 'Estatal');

  if (isEstatal) {
    if (typeof syncCurrentActiveTabFromDOM === 'function') {
      syncCurrentActiveTabFromDOM();
    }
    const activeSep = currentEstatalSeparadores && currentEstatalSeparadores[activeEstatalSeparadorIndex];
    if (!activeSep || !activeSep.nome || !activeSep.nome.trim()) {
      showToast('Por favor, preencha primeiro o campo "Nome / Razão Social" deste separador.', 'warning');
      return;
    }
    entityName = activeSep.nome.trim();
    ministerio = document.getElementById('ministerio')?.value?.trim() || '';
    contribuinte = activeSep.contribuinte || '';
    existingWebsite = activeSep.website || '';
    existingEmail = activeSep.email || '';
    existingTelefone = activeSep.telefone || '';
    existingPais = activeSep.pais?.trim() || '';
  } else {
    const nomeEl = document.getElementById('clientNome');
    if (!nomeEl || !nomeEl.value.trim()) {
      showToast('Por favor, preencha primeiro o campo "Nome / Razão Social" do cliente.', 'warning');
      return;
    }
    entityName = nomeEl.value.trim();
    contribuinte = document.getElementById('clientContribuinte')?.value?.trim() || '';
    existingWebsite = document.getElementById('clientWebsite')?.value?.trim() || '';
    existingEmail = document.getElementById('clientEmail')?.value?.trim() || '';
    existingTelefone = document.getElementById('clientTelefone')?.value?.trim() || '';
    existingPais = document.getElementById('clientPais')?.value?.trim() || '';
  }

  currentPendingContext = {
    isEstatal,
    tipoCliente,
    entityName,
    ministerio,
    contribuinte,
    existingWebsite,
    existingEmail,
    existingTelefone,
    existingPais,
    targetSepIndex: activeEstatalSeparadorIndex
  };

  // Abrir Modal no estado Loading
  const modal = document.getElementById('aiAddressConfirmationModal');
  const loadingState = document.getElementById('aiAddressLoadingState');
  const contentState = document.getElementById('aiAddressContentState');
  const loadingTitle = document.getElementById('aiLoadingTitle');
  const loadingSubtitle = document.getElementById('aiLoadingSubtitle');

  if (modal) {
    modal.style.display = 'flex';
    modal.classList.add('active');
    const win = modal.querySelector('.modal-window');
    if (win) {
      win.style.left = '';
      win.style.top = '';
      win.style.margin = '';
      win.style.position = 'relative';
      win.style.transform = '';
    }
    if (typeof initModalResizing === 'function') {
      initModalResizing();
    }
  }
  if (loadingState) loadingState.style.display = 'block';
  if (contentState) contentState.style.display = 'none';
  if (loadingTitle) loadingTitle.textContent = `A pesquisar direção de "${entityName}"...`;
  if (loadingSubtitle) {
    if (existingPais) {
      loadingSubtitle.textContent = `Pesquisa ativa: ${entityName} (${existingPais})`;
    } else if (tipoCliente === 'Fundação') {
      loadingSubtitle.textContent = 'A consultar registo internacional de fundações e instituições';
    } else if (isEstatal) {
      loadingSubtitle.textContent = 'A consultar organismos e delegações oficiais';
    } else {
      loadingSubtitle.textContent = 'A consultar registos empresariais e sedes oficiais';
    }
  }

  const btn = document.getElementById('btnAiUpdateClientAddress');
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> <span>A pesquisar...</span>';
  }

  try {
    availableAiCandidates = [];
    selectedAiCandidateIndex = 0;
    const seenKeys = new Set();

    // 1. Diretório Institucional Oficial (Sedes principais verificadas)
    const dirMatches = resolveAllEntitiesFromLocalDirectory(entityName, ministerio, existingPais);
    for (const d of dirMatches) {
      const key = ((d.pais || '') + '|' + (d.localidade || '') + '|' + (d.direcao1 || '')).toLowerCase();
      if (!seenKeys.has(key)) {
        seenKeys.add(key);
        const dCountry = d.pais || 'Portugal';
        const dCc = (dCountry.toLowerCase() === 'espanha') ? 'es' : 'pt';
        const splitDir = splitSmartAddressLines(d.direcao1, d.direcao2, d.numero);
        availableAiCandidates.push({
          nome: d.aliases?.[0] || entityName,
          direcao1: splitDir.direcao1,
          direcao2: splitDir.direcao2,
          numero: splitDir.numero,
          andar: d.andar || '',
          codigoPostal: d.codigoPostal || '',
          localidade: d.localidade || 'Lisboa',
          pais: dCountry,
          countryCode: dCc,
          flag: getCountryFlagEmoji(dCc, dCountry),
          telefone: d.telefone || existingTelefone || '',
          email: d.email || existingEmail || '',
          website: d.website || existingWebsite || '',
          fonteUrl: d.fonteUrl || d.website || 'https://www.gov.pt',
          provider: 'Registo Institucional Oficial (Sede Principal)'
        });
      }
    }

    // 2. Wikipedia / Wikidata — fonte principal de dados reais de empresas
    const wikiCandidates = await resolveEntityCandidatesFromWikidata(entityName, existingPais);
    for (const wiki of wikiCandidates) {
      const key = ((wiki.pais || '') + '|' + (wiki.localidade || '') + '|' + (wiki.direcao1 || '')).toLowerCase();
      if (!seenKeys.has(key)) {
        seenKeys.add(key);
        availableAiCandidates.push({
          ...wiki,
          website: wiki.website || existingWebsite || '',
          telefone: wiki.telefone || existingTelefone || ''
        });
      }
    }

    // 3. OpenStreetMap (filtrado — só nós do tipo escritório/empresa/sede)
    const osmCandidates = await resolveEntityCandidatesFromNominatim(entityName, existingPais);
    for (const osm of osmCandidates) {
      const key = ((osm.pais || '') + '|' + (osm.localidade || '') + '|' + (osm.direcao1 || '')).toLowerCase();
      if (!seenKeys.has(key)) {
        seenKeys.add(key);
        availableAiCandidates.push({
          ...osm,
          website: osm.website || existingWebsite || '',
          telefone: osm.telefone || existingTelefone || ''
        });
      }
    }

    // 4. OpenCorporates — registo oficial de empresas (140+ países)
    if (availableAiCandidates.length < 4) {
      const ocCandidates = await resolveEntityCandidatesFromOpenCorporates(entityName, existingPais);
      for (const oc of ocCandidates) {
        const key = ((oc.pais || '') + '|' + (oc.localidade || '') + '|' + (oc.direcao1 || '')).toLowerCase();
        if (!seenKeys.has(key)) {
          seenKeys.add(key);
          availableAiCandidates.push({
            ...oc,
            website: oc.website || existingWebsite || '',
            telefone: oc.telefone || existingTelefone || ''
          });
        }
      }
    }

    // 5. DuckDuckGo — obter website oficial se ainda não encontrado
    if (!existingWebsite && availableAiCandidates.length < 4) {
      const ddgResult = await resolveEntityWebsiteFromDDG(entityName);
      if (ddgResult && ddgResult.website) {
        // Enriquecer candidatos existentes com o website do DDG
        for (const cand of availableAiCandidates) {
          if (!cand.website) cand.website = ddgResult.website;
        }
        // Se ainda zero candidatos, criar entrada apenas com website
        if (availableAiCandidates.length === 0 && ddgResult.fonteUrl) {
          availableAiCandidates.push({
            nome:        ddgResult.heading || entityName,
            direcao1:    '',
            direcao2:    '',
            numero:      '',
            andar:       '',
            codigoPostal:'',
            localidade:  existingPais || '',
            pais:        existingPais || '',
            countryCode: '',
            flag:        getCountryFlagEmoji('', existingPais),
            telefone:    existingTelefone || '',
            website:     ddgResult.website,
            fonteUrl:    ddgResult.fonteUrl,
            provider:    '🔍 DuckDuckGo (Website Oficial)'
          });
        }
      }
    }

    // 6. Gemini AI com Google Search e Fallbacks Robustos
    const rawGeminiKey = localStorage.getItem('sigec_gemini_api_key') || '';
    const geminiApiKey = rawGeminiKey.trim().replace(/^["']|["']$/g, '');
    lastGeminiError = '';

    console.log('[SIGEC-Enrichment] Candidatos antes do Gemini:', availableAiCandidates.length, '| Chave Gemini:', geminiApiKey ? 'SIM (' + geminiApiKey.substring(0,7) + '...)' : 'NÃO');

    if (geminiApiKey) {
      try {
        let aiTextResponse = '';
        let aiSourceUrl = '';

        // ── TENTATIVA 6a: Gemini 2.0 com Google Search Grounding ──
        try {
          const promptGrounding = `Pesquisa na web e encontra o número de contribuinte (NIF/NIPC em Portugal ou CIF em Espanha), a morada oficial e exata da sede social/fiscal (rua exata com número de porta, código postal e cidade oficial), website oficial, email oficial de atendimento e telefone da empresa/organização: "${entityName}"${existingPais ? ' (país: ' + existingPais + ')' : ''}. Responde em português.`;
          console.log('[SIGEC-Gemini 6a] A enviar com Google Search Grounding...');
          const gRespGrounding = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${geminiApiKey}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              contents: [{ parts: [{ text: promptGrounding }] }],
              tools: [{ googleSearch: {} }]
            })
          });

          if (gRespGrounding.ok) {
            const gGroundData = await gRespGrounding.json();
            aiTextResponse = gGroundData?.candidates?.[0]?.content?.parts?.[0]?.text || '';
            const groundingChunks = gGroundData?.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
            aiSourceUrl = groundingChunks?.[0]?.web?.uri || '';
            console.log('[SIGEC-Gemini 6a] Resposta obtida via Google Search!');
          } else {
            const errBody = await gRespGrounding.text();
            let parsedMsg = '';
            try { parsedMsg = JSON.parse(errBody)?.error?.message || errBody; } catch(_) { parsedMsg = errBody; }
            lastGeminiError = parsedMsg;
            console.warn('[SIGEC-Gemini 6a Erro]:', lastGeminiError);
          }
        } catch(e6a) {
          lastGeminiError = e6a.message || String(e6a);
          console.warn('[SIGEC-Gemini 6a Exceção]:', e6a);
        }

        // ── TENTATIVA 6a-alt: Se Grounding falhou, tentar Gemini Direto (sem ferramentas) ──
        if (!aiTextResponse) {
          console.log('[SIGEC-Gemini] A tentar modo conhecimento direto (sem tools)...');
          try {
            const directPrompt = `Indica o número de contribuinte (NIF/NIPC em Portugal ou CIF em Espanha), a morada oficial e exata da sede fiscal/social registada (rua e número de porta exatos, código postal, cidade/município e país), website oficial, email de contacto oficial e telefone da empresa ou organização "${entityName}"${existingPais ? ' (' + existingPais + ')' : ''}. Fornece todos os detalhes conhecidos.`;
            const gRespDirect = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${geminiApiKey}`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                contents: [{ parts: [{ text: directPrompt }] }]
              })
            });

            if (gRespDirect.ok) {
              const gDataDir = await gRespDirect.json();
              aiTextResponse = gDataDir?.candidates?.[0]?.content?.parts?.[0]?.text || '';
              lastGeminiError = ''; // Limpar erro pois fallback funcionou
              console.log('[SIGEC-Gemini Direto 2.0] Resposta obtida com sucesso!');
            } else {
              // Tentar fallback para gemini-1.5-flash
              const gResp15 = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${geminiApiKey}`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                  contents: [{ parts: [{ text: directPrompt }] }]
                })
              });
              if (gResp15.ok) {
                const gData15 = await gResp15.json();
                aiTextResponse = gData15?.candidates?.[0]?.content?.parts?.[0]?.text || '';
                lastGeminiError = '';
                console.log('[SIGEC-Gemini Direto 1.5] Resposta obtida com sucesso!');
              } else {
                const errBody15 = await gResp15.text();
                try { lastGeminiError = JSON.parse(errBody15)?.error?.message || errBody15; } catch(_) { lastGeminiError = errBody15; }
              }
            }
          } catch(eDir) {
            if (!lastGeminiError) lastGeminiError = eDir.message || String(eDir);
          }
        }

        // ── PASSO 6b: Extrair dados estruturados em JSON ──
        if (aiTextResponse) {
          const promptJson = `Com base neste texto sobre "${entityName}", extrai APENAS os dados de contacto e identificação fiscal em JSON:

TEXTO: ${aiTextResponse}

Devolve APENAS este JSON exato (sem texto extra, sem markdown):
{"website":"","email":"","telefone":"","contribuinte":"","direcao1":"","codigoPostal":"","localidade":"","pais":""}`;

          let parsed = null;
          try {
            const gRespJson = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${geminiApiKey}`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                contents: [{ parts: [{ text: promptJson }] }],
                generationConfig: { responseMimeType: 'application/json' }
              })
            });

            if (gRespJson.ok) {
              const gJsonData = await gRespJson.json();
              const jsonText = gJsonData?.candidates?.[0]?.content?.parts?.[0]?.text || '';
              parsed = JSON.parse(jsonText.trim());
            }
          } catch(eParse) {
            console.warn('[SIGEC-Gemini 6b] JSON mode falhou, a tentar regex:', eParse);
          }

          // Fallback regex se o modo JSON não devolver
          if (!parsed) {
            const jm = aiTextResponse.match(/\{[\s\S]*?\}/);
            if (jm) {
              try { parsed = JSON.parse(jm[0]); } catch(_) {}
            }
          }

          if (parsed) {
            const gCountry = parsed.pais || existingPais || 'Espanha';
            const gCc = gCountry.toLowerCase().includes('port') ? 'pt' : (gCountry.toLowerCase().includes('esp') ? 'es' : '');
            if (parsed.website || parsed.email || parsed.localidade || parsed.direcao1 || parsed.telefone || parsed.contribuinte) {
              const gSplit = splitSmartAddressLines(parsed.direcao1 || '', parsed.direcao2 || '', parsed.numero || '');
              availableAiCandidates.push({
                nome:        entityName,
                direcao1:    gSplit.direcao1,
                direcao2:    gSplit.direcao2,
                numero:      gSplit.numero,
                andar:       '',
                codigoPostal:parsed.codigoPostal || '',
                localidade:  parsed.localidade || '',
                pais:        gCountry,
                countryCode: gCc,
                flag:        getCountryFlagEmoji(gCc, gCountry),
                telefone:    parsed.telefone || existingTelefone || '',
                email:       parsed.email || existingEmail || '',
                website:     parsed.website || existingWebsite || '',
                contribuinte:parsed.contribuinte || '',
                fonteUrl:    aiSourceUrl || parsed.website || 'https://www.google.com',
                provider:    '🔎 Google (via Gemini AI)'
              });
              lastGeminiError = '';
              console.log('[SIGEC-Gemini] Candidato adicionado com sucesso!');
            }
          }
        }
      } catch (eGemini) {
        lastGeminiError = eGemini.message || String(eGemini);
        console.warn('Gemini AI falhou:', eGemini);
      }
    }

    // 7. Se for estatal e ainda sem resultados, tentar ministério central
    if (availableAiCandidates.length === 0 && isEstatal) {
      const minMatch = resolveEntityFromLocalDirectory(ministerio, '', existingPais);
      if (minMatch) {
        const mCountry = minMatch.pais || existingPais || 'Portugal';
        const mCc = (mCountry.toLowerCase() === 'espanha') ? 'es' : 'pt';
        availableAiCandidates.push({
          nome: ministerio,
          direcao1: minMatch.direcao1 || '',
          direcao2: minMatch.direcao2 || '',
          numero: minMatch.numero || '',
          andar: minMatch.andar || '',
          codigoPostal: minMatch.codigoPostal || '',
          localidade: minMatch.localidade || 'Lisboa',
          pais: mCountry,
          countryCode: mCc,
          flag: getCountryFlagEmoji(mCc, mCountry),
          telefone: minMatch.telefone || existingTelefone || '',
          website: minMatch.website || existingWebsite || 'https://www.gov.pt',
          fonteUrl: minMatch.fonteUrl || 'https://www.gov.pt',
          provider: 'Sede Ministerial Central'
        });
      }
    }

        // Configurar atalhos diretos do Google e Google Maps
    const entityQ = encodeURIComponent(entityName + " sede morada contacto telefone");
    const gDirect = document.getElementById("aiBtnGoogleDirectLink");
    if (gDirect) {
      gDirect.href = "https://www.google.com/search?q=" + entityQ;
    }
    const gMaps = document.getElementById("aiBtnGoogleMapsDirectLink");
    if (gMaps) {
      const qMaps = encodeURIComponent(entityName + (existingPais ? " " + existingPais : ""));
      gMaps.href = "https://www.google.com/maps/search/?api=1&query=" + qMaps;
    }
    const smartInput = document.getElementById("aiSmartPasteInput");
    if (smartInput) smartInput.value = "";
    const successEl = document.getElementById("aiSmartPasteSuccessMsg");
    if (successEl) successEl.style.display = "none";

    // Saneamento defensivo de todos os candidatos contra caracteres corrompidos
    availableAiCandidates = availableAiCandidates.map(cand => {
      if (!cand || typeof cand !== 'object') return cand;
      ['nome', 'direcao1', 'direcao2', 'numero', 'andar', 'codigoPostal', 'localidade', 'pais', 'telefone', 'website'].forEach(k => {
        if (cand[k] && typeof cand[k] === 'string') {
          cand[k] = (typeof sanitizeUtf8String === 'function') ? sanitizeUtf8String(cand[k]) : cand[k];
        }
      });
      return cand;
    });

    if (availableAiCandidates.length === 0) {
      if (loadingState) loadingState.style.display = "none";
      if (contentState) contentState.style.display = "block";
      const multiContainer = document.getElementById("aiMultipleCandidatesContainer");
      if (multiContainer) multiContainer.style.display = "none";
      
      pendingAiAddressData = {
        nome: entityName,
        direcao1: "",
        direcao2: "",
        numero: "",
        andar: "",
        codigoPostal: "",
        localidade: "",
        pais: existingPais || "Portugal",
        website: existingWebsite || "",
        email: existingEmail || "",
        telefone: existingTelefone || "",
        fonteUrl: "https://www.google.com/search?q=" + entityQ
      };
      updateAiModalPreview(pendingAiAddressData);

      const targetLabel = document.getElementById("aiTargetLabel");
      if (targetLabel) targetLabel.textContent = "Entidade a atualizar:";
      const targetEntity = document.getElementById("aiTargetEntityName");
      if (targetEntity) targetEntity.textContent = entityName;
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = "<i class=\"fa-solid fa-house\"></i> <span data-i18n=\"btn_ai_update_address\">Atualização de Direção</span>";
      }
      return;
    }

    // Ordenar candidatos: Se o utilizador já indicou um País, priorizar no topo
    if (existingPais && existingPais.trim()) {
      const epLow = existingPais.trim().toLowerCase();
      availableAiCandidates.sort((a, b) => {
        const aMatch = (a.pais && a.pais.toLowerCase().includes(epLow)) || (a.countryCode && a.countryCode === epLow);
        const bMatch = (b.pais && b.pais.toLowerCase().includes(epLow)) || (b.countryCode && b.countryCode === epLow);
        if (aMatch && !bMatch) return -1;
        if (!aMatch && bMatch) return 1;
        return 0;
      });
    }

    // Configurar seletor de múltiplos candidatos
    const multiContainer = document.getElementById('aiMultipleCandidatesContainer');
    const countBadge = document.getElementById('aiCandidatesCountBadge');

    if (availableAiCandidates.length > 1) {
      if (multiContainer) multiContainer.style.display = 'block';
      if (countBadge) countBadge.textContent = availableAiCandidates.length;
      renderAiCandidateCards();
    } else {
      if (multiContainer) multiContainer.style.display = 'none';
    }

    // Selecionar candidato inicial
    selectAiCandidate(0);

    // Atualizar cabeçalho da entidade no modal
    if (loadingState) loadingState.style.display = 'none';
    if (contentState) contentState.style.display = 'block';

    const targetLabel = document.getElementById('aiTargetLabel');
    if (targetLabel) {
      if (isEstatal) {
        targetLabel.textContent = 'Separador Ativo (Organismo):';
      } else if (tipoCliente === 'Fundação') {
        targetLabel.textContent = 'Fundação / Instituição:';
      } else {
        targetLabel.textContent = 'Cliente / Razão Social:';
      }
    }

    const targetEntity = document.getElementById('aiTargetEntityName');
    if (targetEntity) targetEntity.textContent = entityName;

    const targetContext = document.getElementById('aiTargetContext');
    if (targetContext) {
      targetContext.textContent = isEstatal 
        ? `Separador #${activeEstatalSeparadorIndex + 1}${ministerio ? ' • ' + ministerio : ''}`
        : `Tipo: ${tipoCliente}${contribuinte ? ' • NIF ' + contribuinte : ''}`;
    }

  } catch(err) {
    closeAiAddressModal();
    showToast('Aviso: ' + (err.message || 'Não foi possível encontrar a direção automaticamente na Internet.'), 'warning');
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = '<i class="fa-solid fa-house"></i> <span data-i18n="btn_ai_update_address">Atualização de Direção</span>';
    }
  }
}
window.triggerAiAddressEnrichment = triggerAiAddressEnrichment;

function confirmAndApplyAiAddress() {
  if (!pendingAiAddressData) {
    closeAiAddressModal();
    return;
  }

  const d = pendingAiAddressData;
  if (d.isEstatal) {
    if (currentEstatalSeparadores && currentEstatalSeparadores[d.targetSepIndex]) {
      const sep = currentEstatalSeparadores[d.targetSepIndex];
      if (d.direcao1) sep.direcao1 = d.direcao1;
      if (d.direcao2) sep.direcao2 = d.direcao2;
      if (d.numero) sep.numero = d.numero;
      if (d.andar) sep.andar = d.andar;
      if (d.codigoPostal) sep.codigoPostal = d.codigoPostal;
      if (d.localidade) sep.localidade = d.localidade;
      if (d.pais) sep.pais = d.pais;
      if (d.contribuinte && d.contribuinte.trim() && d.contribuinte.trim() !== '000000000') {
        sep.contribuinte = d.contribuinte.trim();
      }
      if (d.website && (!sep.website || sep.website.trim() === '')) {
        sep.website = d.website;
      }
      if (d.email && (!sep.email || sep.email.trim() === '')) {
        sep.email = d.email;
      }
      if (d.telefone && (!sep.telefone || sep.telefone.trim() === '')) {
        sep.telefone = d.telefone;
      }
      if (typeof renderEstatalSeparadores === 'function') {
        renderEstatalSeparadores();
      }
      showToast(`Direção e contactos do separador "${getSeparadorTitle(sep)}" atualizados com sucesso!`, 'success');
    }
  } else {
    // Cliente Privado ou Fundação
    if (d.direcao1) {
      const el = document.getElementById('clientDirecao1');
      if (el) el.value = d.direcao1;
    }
    if (d.direcao2) {
      const el = document.getElementById('clientDirecao2');
      if (el) el.value = d.direcao2;
    }
    if (d.numero) {
      const el = document.getElementById('clientNumero');
      if (el) el.value = d.numero;
    }
    if (d.andar) {
      const el = document.getElementById('clientAndar');
      if (el) el.value = d.andar;
    }
    if (d.codigoPostal) {
      const el = document.getElementById('clientCodigoPostal');
      if (el) el.value = d.codigoPostal;
    }
    if (d.localidade) {
      const el = document.getElementById('clientLocalidade');
      if (el) {
        el.value = d.localidade;
        if (typeof autoExpandInput === 'function') autoExpandInput(el);
      }
    }
    if (d.pais) {
      const el = document.getElementById('clientPais');
      if (el) {
        el.value = d.pais;
        if (typeof autoExpandInput === 'function') autoExpandInput(el);
      }
    }
    if (d.website) {
      const el = document.getElementById('clientWebsite');
      if (el && (!el.value || el.value.trim() === '')) {
        el.value = d.website;
        if (typeof updateClientWebsiteBtnState === 'function') updateClientWebsiteBtnState(d.website);
      }
    }
    if (d.email) {
      const el = document.getElementById('clientEmail');
      if (el && (!el.value || el.value.trim() === '')) {
        el.value = d.email;
      }
    }
    if (d.telefone) {
      const el = document.getElementById('clientTelefone');
      if (el && (!el.value || el.value.trim() === '')) {
        el.value = d.telefone;
      }
    }
    if (d.contribuinte && d.contribuinte.trim() && d.contribuinte.trim() !== '000000000') {
      const el = document.getElementById('clientContribuinte');
      if (el) {
        el.value = d.contribuinte.trim();
        try {
          el.dispatchEvent(new Event('input', { bubbles: true }));
          el.dispatchEvent(new Event('change', { bubbles: true }));
        } catch(_) {}
      }
    }
    const labelTipo = d.tipoCliente === 'Fundação' ? 'da Fundação' : 'da Empresa';
    showToast(`Direção e dados ${labelTipo} atualizados com sucesso!`, 'success');
  }

  closeAiAddressModal();
}
window.confirmAndApplyAiAddress = confirmAndApplyAiAddress;

function promptGeminiApiKey() {
  const currentKey = localStorage.getItem('sigec_gemini_api_key') || '';
  const newKey = prompt('Configuração da Chave da API Google Gemini:\n\nInsira a sua chave (Google AI Studio) para usar IA Gemini com pesquisa Google em tempo real.\nDeixe em branco para usar o motor de pesquisa web integrado:', currentKey);
  if (newKey !== null) {
    if (newKey.trim()) {
      localStorage.setItem('sigec_gemini_api_key', newKey.trim());
      showToast('Chave Google Gemini guardada com sucesso!', 'success');
    } else {
      localStorage.removeItem('sigec_gemini_api_key');
      showToast('Chave removida. A utilizar motor web integrado.', 'info');
    }
  }
}
window.promptGeminiApiKey = promptGeminiApiKey;

function saveGeminiKeyFromModal() {
  const inp = document.getElementById('aiModalApiKeyInput');
  if (!inp || !inp.value.trim()) {
    showToast('Por favor, insira a sua chave Google Gemini.', 'warning');
    return;
  }
  const clean = inp.value.trim().replace(/^["']|["']$/g, '');
  localStorage.setItem('sigec_gemini_api_key', clean);
  showToast('Chave Google Gemini guardada com sucesso! A reiniciar pesquisa...', 'success');
  if (typeof triggerAiAddressEnrichment === 'function') {
    triggerAiAddressEnrichment();
  }
}
window.saveGeminiKeyFromModal = saveGeminiKeyFromModal;

function removeGeminiKeyFromModal() {
  localStorage.removeItem('sigec_gemini_api_key');
  showToast('Chave Google Gemini removida.', 'info');
  if (typeof renderAiCandidateCards === 'function') {
    renderAiCandidateCards();
  }
}
window.removeGeminiKeyFromModal = removeGeminiKeyFromModal;



